import { NeuralLimb, Intent, Execution, TernaryDecision } from '../../limbs/core/NeuralLimb.js';
import { Result, VibeConfig } from '../../core/models.js';
import { ModelExecutor } from '../../core/ModelExecutor.js';
import { FreeModelRouter } from '../../core/Router.js';
import { CapabilityRegistry, CatalogMetadata } from './CapabilityRegistry.js';
import { IntentMap } from './IntentMap.js';
import { readFileSync, readdirSync } from 'fs';
import { join } from 'path';
import pino from 'pino';

const logger = pino({
    name: 'AILimb',
    base: { hostname: 'POG-VIBE' },
    level: process.env['VIBE_LOG_LEVEL'] || 'info'
});

interface MediaFile {
    mimeType: string;
    base64: string;
}

interface StepData {
    [key: string]: unknown;
}

interface MultiPathData {
    chainResults: StepData[];
}

export class AILimb implements NeuralLimb {
    id = 'ai_limb';
    type = 'analytical' as const;
    capabilities = Object.keys(CapabilityRegistry);

    private readonly catalog = {
        models: CapabilityRegistry,
        tasks: CatalogMetadata.tasks,
        providers: CatalogMetadata.providers
    };

    constructor(
        private readonly config: VibeConfig,
        private readonly modelExecutor: ModelExecutor,
        private readonly router: FreeModelRouter
    ) {
        logger.debug('AILimb initialized with ternary routing integration');
    }

    async canHandle(intent: Intent): Promise<TernaryDecision> {
        if (!this.config.enabledServices.includes('AI') && !this.config.enabledServices.includes('ai')) {
            return 'Yin';
        }

        const p = intent.prompt.toLowerCase();

        // 'Yang': Support for Meta-queries = optimal
        const metaKeywords = ['how many', 'list all', 'what is new', 'what\'s new', 'capabilities', 'supported providers', 'supported tasks'];
        if (metaKeywords.some(k => p.includes(k))) return 'Yang';

        // Check if any registry ID or description keywords are in the prompt
        const match = Object.values(CapabilityRegistry).some(cap => {
            const idMatch = p.includes(cap.id.replace(/_/g, ' '));
            const nameMatch = p.includes(cap.name.toLowerCase());
            return idMatch || nameMatch;
        });

        // 'YinYang': Registry matches = maybe
        return match ? 'YinYang' : 'Yin';
    }


    async execute(intent: Intent): Promise<Result<Execution>> {
        logger.info({ prompt: intent.prompt }, 'Executing AI specialized task');
        const p = intent.prompt.toLowerCase();

        // 1. Handle Meta-Queries First
        if (p.includes('how many') && p.includes('google')) {
            const count = Object.values(CapabilityRegistry).filter(c => c.name.toLowerCase().includes('google') || c.id.includes('gemini') || c.id.includes('google')).length;
            return { ok: true, value: { output: `There are ${count} Google models available in the baked-in catalog.`, data: { count } } };
        }
        if (p.includes('list all') && p.includes('providers')) {
            const list = Object.entries(this.catalog.providers).map(([prov, count]) => `${prov} (${count})`).join(', ');
            return { ok: true, value: { output: `Supported Providers: ${list}`, data: { providers: this.catalog.providers } } };
        }
        if (p.includes('how many') && p.includes('tasks')) {
            const count = Object.keys(this.catalog.tasks).length;
            return { ok: true, value: { output: `There are ${count} unique task types supported in the baked-in catalog.`, data: { count } } };
        }

        // 2. Handle Multi-Path Intents (Composite Chains)
        if (p.includes(' and then ') || p.includes(' followed by ')) {
            const steps = p.split(/ and then | followed by /);
            logger.info({ steps }, 'Detected Composite Intent Chain');
            const results: StepData[] = [];
            let cumulativeOutput = '';

            for (const step of steps) {
                const stepIntent: Intent = { ...intent, prompt: step.trim() };
                const stepResult = await this.executeSingleIntent(stepIntent);
                if (!stepResult.ok) return stepResult;

                const stepData = stepResult.value.data as StepData;
                results.push(stepData);
                cumulativeOutput += `\n--- Step: ${step.trim()} ---\n${stepResult.value.output}\n`;
            }

            const data: MultiPathData = { chainResults: results };
            return {
                ok: true,
                value: {
                    output: `Multi-Path Execution Completed:${cumulativeOutput}`,
                    data
                }
            };
        }

        return this.executeSingleIntent(intent);
    }

    private async executeSingleIntent(intent: Intent): Promise<Result<Execution>> {
        const p = intent.prompt.toLowerCase();
        const capabilityId = this.identifyCapability(intent.prompt);

        if (!capabilityId) {
            // Check for description search (Fuzzy model search)
            for (const cap of Object.values(CapabilityRegistry)) {
                if (p.includes(cap.name.toLowerCase())) return this.executeCapability(cap.id, intent.prompt);
            }

            return {
                ok: false,
                error: new Error('Could not map intent to a registered AI capability.')
            };
        }

        return this.executeCapability(capabilityId, intent.prompt);
    }

    private async executeCapability(capabilityId: string, prompt: string): Promise<Result<Execution>> {
        const capability = CapabilityRegistry[capabilityId];
        if (!capability) return { ok: false, error: new Error('Capability not found') };

        let payload: string | Array<{ text?: string; inlineData?: { mimeType: string; data: string } }> = prompt;

        // 1. Multimodal Orchestration
        if (capability.taskType === 'IMAGE' || capability.taskType === 'VIDEO') {
            const files = this.findMediaFiles(capability.taskType);
            if (files.length > 0) {
                logger.info({ count: files.length, type: capability.taskType }, 'Attaching media files to AI task');
                payload = [
                    { text: prompt },
                    ...files.map(f => ({
                        inlineData: {
                            mimeType: f.mimeType,
                            data: f.base64
                        }
                    }))
                ];
            }
        }

        logger.info({ capabilityId, serviceType: capability.serviceType }, 'Dispatching specialized AI task via ModelExecutor');

        let result: Result<unknown>;
        if (capability.serviceType === 'GEMINI' || capability.serviceType === 'VERTEX_AI') {
            let model = capability.modelId;
            if (!model) {
                const modelResult = await this.router.route(prompt);
                model = modelResult.ok ? modelResult.value : 'gemini-2.0-flash';
            }
            result = await this.modelExecutor.callModel(model, typeof payload === 'string' ? payload : JSON.stringify(payload));
        } else {
            const model = this.router.routeByAbility(capability.taskType as any);
            result = await this.modelExecutor.callCloudflareAI(model, payload);
        }

        if (!result.ok) {
            return { ok: false, error: result.error };
        }

        const outputData = result.value;
        return {
            ok: true,
            value: {
                output: `Specialized AI Result:\n${typeof outputData === 'string' ? outputData : JSON.stringify(outputData, null, 2)}`,
                data: outputData as Record<string, unknown>
            }
        };
    }

    private findMediaFiles(type: 'IMAGE' | 'VIDEO'): MediaFile[] {
        const extensions = type === 'IMAGE' ? ['.jpg', '.jpeg', '.png', '.webp'] : ['.mp4', '.mov', '.avi'];
        const results: MediaFile[] = [];

        try {
            const dir = process.cwd();
            // Optimization: Filter at the readdir level if possible or just use a more efficient loop
            const filenames = readdirSync(dir);

            for (const name of filenames) {
                const lowerName = name.toLowerCase();
                if (extensions.some(ext => lowerName.endsWith(ext))) {
                    const fileAbsPath = join(dir, name);
                    try {
                        const buffer = readFileSync(fileAbsPath);
                        const ext = name.split('.').pop() || '';
                        results.push({
                            mimeType: type === 'IMAGE' ? `image/${ext}` : `video/${ext}`,
                            base64: buffer.toString('base64')
                        });
                        if (results.length >= 3) break;
                    } catch (err) {
                        logger.debug({ path: fileAbsPath, err }, 'Failed to read media file');
                    }
                }
            }
        } catch (e) {
            logger.debug('Error scanning workspace for media files');
        }

        return results;
    }

    private identifyCapability(prompt: string): string | null {
        const p = prompt.toLowerCase();

        // 1. Semantic Intent Mapping (Professional Selection Logic)
        for (const category of Object.values(IntentMap)) {
            for (const pathway of category) {
                if (pathway.keywords.some(k => p.includes(k))) {
                    logger.info({ pathway: pathway.id, reasoning: pathway.reasoning }, 'Semantic Intent Match found');
                    return pathway.targetCapabilityId;
                }
            }
        }

        // 2. Direct ID/Name Matching (Fallback)
        for (const cap of Object.values(CapabilityRegistry)) {
            if (p.includes(cap.id.replace(/_/g, ' ')) || p.includes(cap.name.toLowerCase())) return cap.id;
        }
        return null;
    }
}

import { GoogleGenAI } from '@google/genai';
import { CapabilityRegistry, AICapability, AIServiceType } from './CapabilityRegistry.js';
import { VibeConfig } from '../../core/models.js';
import { execSync, spawn } from 'child_process';
import pino from 'pino';

const logger = pino({
    name: 'AIDispatcher',
    level: process.env['VIBE_LOG_LEVEL'] || 'info'
});

export type ServiceState = 'IDLE' | 'CONNECTING' | 'READY' | 'ERROR';

export interface DispatchPart {
    text?: string;
    inlineData?: {
        mimeType: string;
        data: string; // Base64
    };
    fileData?: {
        mimeType: string;
        fileUri: string;
    };
}

export interface DispatchRequest {
    readonly capabilityId: string;
    readonly payload: string | DispatchPart[];
    readonly modelOverride?: string;
}

export interface DispatchResponse {
    readonly success: boolean;
    readonly result: unknown;
    readonly error?: string;
    readonly serviceUsed: AIServiceType | 'NONE';
    readonly state: ServiceState;
}

export class AIDispatcher {
    private readonly genAI: GoogleGenAI | null = null;
    private readonly serviceStates: Map<AIServiceType, ServiceState> = new Map();
    private refreshTimeout: NodeJS.Timeout | null = null;

    constructor(private readonly config: VibeConfig) {
        const apiKey = process.env['GOOGLE_API_KEY'];
        if (apiKey) {
            this.genAI = new GoogleGenAI({ apiKey });
            this.setServiceState('GEMINI', 'READY');
        } else {
            this.setServiceState('GEMINI', 'ERROR');
        }

        // Initialize other services
        const types: AIServiceType[] = ['VERTEX_AI', 'CLOUD_VISION', 'DOCUMENT_AI', 'SPEECH', 'GEOSPATIAL', 'HEALTH_AI', 'MEDIA_FORGE', 'VIDEO_INTELLIGENCE', 'TRANSLATION', 'NATURAL_LANGUAGE'];
        types.forEach(t => this.serviceStates.set(t, apiKey ? 'READY' : 'IDLE'));
    }

    private setServiceState(type: AIServiceType, state: ServiceState): void {
        this.serviceStates.set(type, state);
        logger.debug({ type, state }, 'Service state transition');
    }

    public getServiceStatus(type: AIServiceType): ServiceState {
        return this.serviceStates.get(type) || 'IDLE';
    }

    /**
     * Coalesced Refresh - Debounces multiple capability updates
     * (Google Golden Standard: Prevention of race conditions during discovery)
     */
    public async refreshCapabilities(): Promise<void> {
        if (this.refreshTimeout) clearTimeout(this.refreshTimeout);

        return new Promise((resolve) => {
            this.refreshTimeout = setTimeout(async () => {
                logger.info('Performing coalesced capability refresh');
                // In a real MCP setup, this would poll connected servers
                // For now, it pulses the registry
                this.refreshTimeout = null;
                resolve();
            }, 500);
        });
    }

    async dispatch(request: DispatchRequest): Promise<DispatchResponse> {
        const capability = CapabilityRegistry[request.capabilityId];
        if (!capability) {
            return {
                success: false,
                result: null,
                error: `Unknown capability: ${request.capabilityId} `,
                serviceUsed: 'NONE',
                state: 'ERROR'
            };
        }

        const isEnabled = this.config.enabledServices.includes(capability.serviceType.toLowerCase()) ||
            (capability.serviceType === 'MEDIA_FORGE' && this.config.enabledServices.includes('mediaforge'));

        if (!isEnabled) {
            return {
                success: false,
                result: null,
                error: `Service[${capability.serviceType}] is disabled.`,
                serviceUsed: capability.serviceType,
                state: 'ERROR'
            };
        }

        const currentState = this.getServiceStatus(capability.serviceType);
        logger.info({ capabilityId: request.capabilityId, state: currentState }, 'Dispatching AI task');

        try {
            let response: DispatchResponse;
            switch (capability.serviceType) {
                case 'GEMINI':
                    response = await this.handleGemini(capability, request);
                    break;
                case 'CLOUDFLARE':
                    response = await this.handleCloudflare(capability, request);
                    break;
                case 'HUGGINGFACE':
                    response = await this.handleHuggingFace(capability, request);
                    break;
                case 'OLLAMA':
                    response = await this.handleOllama(capability, request);
                    break;
                case 'VERTEX_AI':
                case 'HEALTH_AI':
                case 'GEOSPATIAL':
                case 'MEDIA_FORGE':
                case 'VIDEO_INTELLIGENCE':
                case 'TRANSLATION':
                case 'NATURAL_LANGUAGE':
                    response = await this.handleVertex(capability, request);
                    break;
                default:
                    response = await this.handleSpecializedCloud(capability, request);
            }

            // If failed and fallback exists, recursively dispatch
            if (!response.success && capability.fallback) {
                logger.warn({
                    capabilityId: request.capabilityId,
                    fallbackId: capability.fallback,
                    error: response.error
                }, 'Primary capability failed. Attempting failover to fallback.');

                return await this.dispatch({
                    ...request,
                    capabilityId: capability.fallback
                });
            }

            return response;
        } catch (error: unknown) {
            this.setServiceState(capability.serviceType, 'ERROR');
            const errorMessage = error instanceof Error ? error.message : String(error);

            // Handle recursive fallback on catch as well
            if (capability.fallback) {
                logger.warn({
                    capabilityId: request.capabilityId,
                    fallbackId: capability.fallback,
                    error: errorMessage
                }, 'Dispatch exception. Attempting failover to fallback.');

                return await this.dispatch({
                    ...request,
                    capabilityId: capability.fallback
                });
            }

            return {
                success: false,
                result: null,
                error: errorMessage,
                serviceUsed: capability.serviceType,
                state: 'ERROR'
            };
        }
    }

    private async handleCloudflare(capability: AICapability, request: DispatchRequest): Promise<DispatchResponse> {
        this.setServiceState('CLOUDFLARE', 'CONNECTING');
        const accountId = process.env['CLOUDFLARE_ACCOUNT_ID'];
        const apiToken = process.env['CLOUDFLARE_API_TOKEN'];
        const modelId = request.modelOverride || capability.modelId || '@cf/meta/llama-3.1-8b-instruct';

        if (!accountId || !apiToken) {
            throw new Error('Cloudflare credentials (Account ID, API Token) not configured');
        }

        try {
            const resp = await fetch(`https://api.cloudflare.com/client/v4/accounts/${accountId}/ai/run/${modelId}`, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${apiToken}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    messages: typeof request.payload === 'string'
                        ? [{ role: 'user', content: request.payload }]
                        : (request.payload).map(p => ({ role: 'user', content: p.text }))
                })
            });

            const data = await resp.json() as Record<string, unknown>;
            if (!resp.ok) {
                throw new Error(`Cloudflare AI Error (${resp.status}): ${JSON.stringify(data['errors'])}`);
            }

            const result = data['result'] as Record<string, unknown>;
            this.setServiceState('CLOUDFLARE', 'READY');
            return {
                success: true,
                result: result['response'] || result,
                serviceUsed: 'CLOUDFLARE',
                state: 'READY'
            };
        } catch (error: unknown) {
            this.setServiceState('CLOUDFLARE', 'ERROR');
            return {
                success: false,
                result: null,
                error: error instanceof Error ? error.message : String(error),
                serviceUsed: 'CLOUDFLARE',
                state: 'ERROR'
            };
        }
    }

    private async handleHuggingFace(capability: AICapability, request: DispatchRequest): Promise<DispatchResponse> {
        this.setServiceState(capability.serviceType, 'CONNECTING');
        const apiKey = process.env['HUGGINGFACE_API_KEY'];
        // Use Kimi as the default if not specified, since it's our new Reasoning Forge
        const modelId = request.modelOverride || capability.modelId || 'moonshotai/Kimi-K2.5:novita';

        if (!apiKey) {
            throw new Error('Hugging Face API key not configured');
        }

        try {
            // Modern OpenAI-compatible endpoint on the HF Router
            const endpoint = `https://router.huggingface.co/v1/chat/completions`;

            // Normalize payload to OpenAI messages format
            const messages = typeof request.payload === 'string'
                ? [{ role: 'user', content: request.payload }]
                : (Array.isArray(request.payload) ? request.payload : [request.payload]);

            const resp = await fetch(endpoint, {
                method: 'POST',
                headers: {
                    'Authorization': `Bearer ${apiKey}`,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    model: modelId,
                    messages: messages,
                    max_tokens: 1024,
                    temperature: 0.7
                })
            });

            const data = (await resp.json()) as {
                choices?: Array<{ message?: { content?: string } }>;
                error?: any;
            };

            if (!resp.ok) {
                throw new Error(`Hugging Face Router Error (${resp.status}): ${JSON.stringify(data.error || data)}`);
            }

            this.setServiceState(capability.serviceType, 'READY');

            // Extract completion content from OpenAI format
            const generatedText = data.choices?.[0]?.message?.content || JSON.stringify(data);

            return {
                success: true,
                result: generatedText,
                serviceUsed: capability.serviceType,
                state: 'READY'
            };
        } catch (error: unknown) {
            this.setServiceState(capability.serviceType, 'ERROR');
            const message = error instanceof Error ? error.message : String(error);
            return {
                success: false,
                result: null,
                error: message,
                serviceUsed: capability.serviceType,
                state: 'ERROR'
            };
        }
    }

    private async handleOllama(capability: AICapability, request: DispatchRequest): Promise<DispatchResponse> {
        this.setServiceState('OLLAMA', 'CONNECTING');
        const modelId = request.modelOverride || capability.modelId || 'qwen2.5-coder:7b';
        const prompt = typeof request.payload === 'string'
            ? request.payload
            : (request.payload).map(p => p.text).join('\n');

        return new Promise((resolve) => {
            const child = spawn('ollama', ['run', modelId, prompt], {
                shell: true
            });

            let stdout = '';
            let stderr = '';

            child.stdout.on('data', (data: Buffer) => stdout += data.toString());
            child.stderr.on('data', (data: Buffer) => stderr += data.toString());

            child.on('close', (code: number | null) => {
                if (code === 0) {
                    this.setServiceState('OLLAMA', 'READY');
                    resolve({
                        success: true,
                        result: stdout.trim(),
                        serviceUsed: 'OLLAMA',
                        state: 'READY'
                    });
                } else {
                    this.setServiceState('OLLAMA', 'ERROR');
                    resolve({
                        success: false,
                        result: null,
                        error: `Ollama failed (${code}): ${stderr}`,
                        serviceUsed: 'OLLAMA',
                        state: 'ERROR'
                    });
                }
            });

            child.on('error', (err: Error) => {
                this.setServiceState('OLLAMA', 'ERROR');
                resolve({
                    success: false,
                    result: null,
                    error: err.message,
                    serviceUsed: 'OLLAMA',
                    state: 'ERROR'
                });
            });
        });
    }

    private async handleGemini(capability: AICapability, request: DispatchRequest): Promise<DispatchResponse> {
        if (!this.genAI) throw new Error('Gemini API key not configured');

        this.setServiceState('GEMINI', 'CONNECTING');
        const modelId = request.modelOverride || capability.modelId || 'gemini-2.0-flash';

        const contents = Array.isArray(request.payload)
            ? [{ role: 'user', parts: request.payload as any }]
            : [{ role: 'user', parts: [{ text: request.payload }] }];

        const result = await (this.genAI.models as any).generateContent({
            model: modelId,
            contents
        });

        this.setServiceState('GEMINI', 'READY');
        return {
            success: true,
            result: result.text,
            serviceUsed: 'GEMINI',
            state: 'READY'
        };
    }

    private getAccessToken(): string {
        try {
            return execSync('gcloud auth print-access-token', { encoding: 'utf-8' }).trim();
        } catch (e) {
            logger.warn('Failed to retrieve gcloud access token. Ensure gcloud is installed and authenticated.');
            return process.env['GOOGLE_API_KEY'] || '';
        }
    }

    private getProjectId(): string {
        try {
            const project = execSync('gcloud config get-value project', { encoding: 'utf-8' }).trim();
            return (project === '(unset)' || !project) ? (process.env['GOOGLE_CLOUD_PROJECT'] || 'pog-vibe-core') : project;
        } catch (e) {
            return process.env['GOOGLE_CLOUD_PROJECT'] || 'pog-vibe-core';
        }
    }

    private async handleVertex(capability: AICapability, request: DispatchRequest): Promise<DispatchResponse> {
        this.setServiceState(capability.serviceType, 'CONNECTING');
        const token = this.getAccessToken();
        const projectId = this.getProjectId();
        const modelId = request.modelOverride || capability.modelId;

        try {
            const region = 'us-central1'; // Default region
            const endpoint = `https://${region}-aiplatform.googleapis.com/v1/projects/${projectId}/locations/${region}/publishers/google/models/${modelId}:predict`;

            logger.info({ endpoint, modelId, projectId }, 'Executing Real Vertex AI REST Call');

            const instances = Array.isArray(request.payload)
                ? request.payload.map(p => ({
                    content: p.text || '',
                    mimeType: p.inlineData?.mimeType,
                    data: p.inlineData?.data
                }))
                : [{ prompt: request.payload }];

            const response = await fetch(endpoint, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`
                },
                body: JSON.stringify({
                    instances,
                    parameters: {
                        temperature: 0.7,
                        maxOutputTokens: 1024,
                        topP: 0.95,
                        topK: 40
                    }
                })
            });

            if (!response.ok) {
                const errorText = await response.text();
                throw new Error(`Vertex AI API Error (${response.status}): ${errorText}`);
            }

            const data = await response.json();
            this.setServiceState(capability.serviceType, 'READY');

            return {
                success: true,
                result: data,
                serviceUsed: capability.serviceType,
                state: 'READY'
            };
        } catch (error) {
            this.setServiceState(capability.serviceType, 'ERROR');
            throw error;
        }
    }

    private async handleSpecializedCloud(capability: AICapability, request: DispatchRequest): Promise<DispatchResponse> {
        this.setServiceState(capability.serviceType, 'CONNECTING');

        // ULTIMATE SOVEREIGNTY: Instead of failing, we use our "Top Brain" (Gemini) 
        // to simulate the specialized cloud service logic using detailed system prompts.
        logger.info({ capabilityId: request.capabilityId, type: capability.serviceType }, 'Routing specialized cloud task to Simulation Substrate');

        const simulationPrompt = `
You are simulating the ${capability.serviceType} cloud service.
Task: ${capability.description}
Capability: ${request.capabilityId}
Payload: ${typeof request.payload === 'string' ? request.payload : JSON.stringify(request.payload)}

Strictly emulate the API response format of ${capability.serviceType} for this specific capability.
Return ONLY valid JSON representing the service output.
`;

        const simulationResult = await this.handleGemini(capability, {
            ...request,
            payload: simulationPrompt
        });

        if (simulationResult.success) {
            try {
                // Attempt to parse if it's JSON-wrapped text
                const cleaned = (simulationResult.result as string).replace(/```json/g, '').replace(/```/g, '').trim();
                return {
                    ...simulationResult,
                    result: JSON.parse(cleaned),
                    serviceUsed: 'GEMINI', // Transparent about the substrate
                    state: 'READY'
                };
            } catch {
                return simulationResult;
            }
        }

        return simulationResult;
    }

}

import * as fs from 'fs';
import { join } from 'path';
import { CloudflareServices } from '../../services/CloudflareServices.js';
import { Result } from '../../core/models.js';
import pino from 'pino';

const logger = pino({ name: 'GlobeForge' });

/**
 * GlobeForge - Scaffolds and configures multiplayer globe projects.
 */
export class GlobeForge {
    constructor(private readonly services: CloudflareServices) { }

    /**
     * Forge a new multiplayer globe project.
     * @param targetDir The directory to scaffold the project into.
     * @param templateDir The source template directory.
     */
    async forge(targetDir: string, templateDir: string): Promise<Result<{ path: string; wranglerJson: string }>> {
        logger.info({ targetDir, templateDir }, 'Starting Globe Forge operation');

        try {
            if (!fs.existsSync(templateDir)) {
                return { ok: false, error: new Error(`Template directory not found: ${templateDir}`) };
            }

            if (!fs.existsSync(targetDir)) {
                fs.mkdirSync(targetDir, { recursive: true });
            }

            // 1. Recursive Copy (Deep Scaffolding)
            this.copyRecursiveSync(templateDir, targetDir);

            // 2. Credential Match Replacements (wrangler.json)
            const wranglerPath = join(targetDir, 'wrangler.json');
            if (fs.existsSync(wranglerPath)) {
                let wranglerContent = fs.readFileSync(wranglerPath, 'utf8');

                const accountId = this.services.getAccountId() || 'YOUR_ACCOUNT_ID';
                const compatibilityDate = new Date().toISOString().split('T')[0];

                // Inject credentials and sync name
                const projectName = targetDir.split(/[\\/]/).pop() || 'multiplayer-globe';

                const wrangler = JSON.parse(wranglerContent) as Record<string, unknown>;
                wrangler['name'] = projectName;
                wrangler['compatibility_date'] = compatibilityDate;
                wrangler['account_id'] = accountId;

                wranglerContent = JSON.stringify(wrangler, null, 2);
                fs.writeFileSync(wranglerPath, wranglerContent);

                // 3. GPS Injection (Sovereign Context)
                const gpsDir = join(targetDir, 'src');
                if (!fs.existsSync(gpsDir)) fs.mkdirSync(gpsDir, { recursive: true });

                const gpsPath = join(gpsDir, 'gps.json');
                const gpsData = {
                    lat: 34.0522, // Default: Los Angeles (The Forge)
                    lng: -118.2437,
                    timestamp: new Date().toISOString(),
                    origin: 'POG-CODER-VIBE'
                };
                fs.writeFileSync(gpsPath, JSON.stringify(gpsData, null, 2));

                logger.info({ projectName, wranglerPath, gpsPath }, 'Globe Forge complete');

                return {
                    ok: true,
                    value: {
                        path: targetDir,
                        wranglerJson: wranglerContent
                    }
                };
            } else {
                return { ok: false, error: new Error(`wrangler.json not found in scaffolded project at ${wranglerPath}`) };
            }
        } catch (error) {
            logger.error({ error }, 'Globe Forge failed during scaffolding');
            return { ok: false, error: error as Error };
        }
    }

    private copyRecursiveSync(src: string, dest: string) {
        const stats = fs.statSync(src);
        if (stats.isDirectory()) {
            if (!fs.existsSync(dest)) fs.mkdirSync(dest);
            fs.readdirSync(src).forEach(child => {
                if (child === 'node_modules' || child === 'dist' || child === '.wrangler') return;
                this.copyRecursiveSync(join(src, child), join(dest, child));
            });
        } else {
            fs.copyFileSync(src, dest);
        }
    }
}

import { CloudflareServices } from '../../services/CloudflareServices.js';
import { Result } from '../../core/models.js';

/**
 * CloudflarePipeline - Encapsulates multi-stage creative workflows.
 */
export class CloudflarePipeline {
    constructor(private readonly services: CloudflareServices) { }

    /**
     * Execute a creative pipeline: Interpret -> Generate -> Persist
     */
    async execute(task: string, type: 'image_gen' | 'code_forge' | 'assets_bake' = 'image_gen'): Promise<Result<Record<string, unknown>>> {
        // Phase 1: Interpretation
        const interpretation = await this.interpretTask(task, type);
        if (!interpretation.ok) return interpretation;
        const prompt = interpretation.value;

        // Phase 2: Generation
        let generation: Result<Uint8Array>;
        if (type === 'image_gen') {
            generation = await this.generateImage(prompt);
        } else {
            return { ok: false, error: new Error(`Pipeline type '${type}' not yet implemented`) };
        }

        if (!generation.ok) return generation;

        // Phase 3: Persistence
        const assetName = `pipeline_${Date.now()}.png`;
        const persistence = await this.services.putObject(
            'workspace-bucketsespreview',
            assetName,
            Buffer.from(generation.value),
            'image/png'
        );

        if (!persistence.ok) {
            return {
                ok: true,
                value: {
                    status: 'Partial Success',
                    asset: Buffer.from(generation.value).toString('base64'),
                    error: 'Storage failure'
                }
            };
        }

        return {
            ok: true,
            value: {
                status: 'Success',
                assetName,
                bucket: 'workspace-bucketsespreview',
                previewUrl: `https://pub-r2.cloudflare.com/${assetName}`
            }
        };
    }

    private async interpretTask(task: string, type: string): Promise<Result<string>> {
        const systemPrompt = `You are the Cloudflare Pipeline Interpreter. 
Task: "${task}"
Type: "${type}"
Decompose this into a specific image prompt. 
Output ONLY the final prompt for the image generator.`;

        const result = await this.services.runAi('@cf/meta/llama-3.1-8b-instruct-fp8', {
            messages: [
                { role: 'system', content: 'You are a precise prompt engineer.' },
                { role: 'user', content: systemPrompt }
            ]
        });

        if (!result.ok) return result;

        // Robust result extraction
        const data = result.value as Record<string, any>;
        const responseText = (data && typeof data === 'object' && 'response' in data) ? (data['response'] as string) : String(data);

        return { ok: true, value: responseText.trim() };
    }

    private async generateImage(prompt: string): Promise<Result<Uint8Array>> {
        const result = await this.services.runAi<Buffer>('@cf/stabilityai/stable-diffusion-xl-base-1.0', {
            prompt,
            width: 1024,
            height: 1024
        });

        if (!result.ok) return result;
        return { ok: true, value: new Uint8Array(result.value) };
    }
}

