import { GoogleGenAI, Tool, HarmCategory, HarmBlockThreshold } from '@google/genai';
import pino from 'pino';
import { Result, ModelResponse, FunctionCall } from './models.js';
import { KeyVault } from '../utils/KeyVault.js';
import { HealthRegistry } from './HealthRegistry.js';
import { GoogleServices } from '../services/GoogleServices.js';

const logger = pino({
    name: 'GeminiService',
    base: { hostname: 'POG-VIBE' }
});

export interface GeminiConfig {
    apiKey: string;
    useVertexAI?: boolean;
    apiEndpoint?: string;
    customHeaders?: Record<string, string>;
    modelName?: string;
}

export type ServiceHealthState = 'READY' | 'RATE_LIMITED' | 'CRITICAL_FAILURE';

/**
 * GeminiService - Unified Intelligence Layer (Sovereign Substrate)
 * 
 * Incorporates automated failover, key rotation, and sensory integration.
 */
export class GeminiService extends GoogleServices {
    private genAI: GoogleGenAI;
    private readonly keyVault: KeyVault | undefined;
    private healthState: ServiceHealthState = 'READY';
    private lastBackoffUntil: number = 0;
    private readonly currentModel: string;

    constructor(config: GeminiConfig | string, keyVault?: KeyVault) {
        if (typeof config === 'string') {
            super({ apiKey: config });
            this.currentModel = 'gemini-2.0-flash';
        } else {
            super({ apiKey: config.apiKey });
            this.currentModel = config.modelName || 'gemini-2.0-flash';
        }

        this.keyVault = keyVault;

        this.genAI = new GoogleGenAI({
            apiKey: this.config.apiKey,
            ...(typeof config !== 'string' && config.customHeaders ? { customHeaders: config.customHeaders } : {}),
            ...(typeof config !== 'string' && config.apiEndpoint ? { apiEndpoint: config.apiEndpoint } : {})
        } as { apiKey: string; customHeaders?: Record<string, string>; apiEndpoint?: string });

        // Register health provider
        HealthRegistry.getInstance().registerProvider('gemini', () => this.getHealth());
    }

    public getHealth(): { state: ServiceHealthState; cooldownSeconds: number } {
        const now = Date.now();
        if (this.healthState === 'RATE_LIMITED' && now < this.lastBackoffUntil) {
            return { state: 'RATE_LIMITED', cooldownSeconds: Math.ceil((this.lastBackoffUntil - now) / 1000) };
        }

        if (this.healthState === 'RATE_LIMITED' && now >= this.lastBackoffUntil) {
            this.healthState = 'READY';
        }

        return { state: this.healthState, cooldownSeconds: 0 };
    }

    async generateContent(
        prompt: string,
        modelOverride?: string,
        tools?: Tool[]
    ): Promise<Result<ModelResponse>> {
        const health = this.getHealth();
        if (health.state === 'RATE_LIMITED') {
            return { ok: false, error: new Error(`Gemini API is rate limited. Cooldown: ${health.cooldownSeconds}s`) };
        }

        return this.retryWithBackoff<ModelResponse>(async () => {
            const startTime = Date.now();
            const targetModel = modelOverride || this.currentModel;

            // 1. Prepare contents
            const contents = [{ role: 'user', parts: [{ text: prompt }] }];

            // 2. Prepare tools
            const genTools = (tools && tools.length > 0) ? tools : undefined;

            const response = await this.genAI.models.generateContent({
                model: targetModel,
                contents,
                config: {
                    ...(genTools ? { tools: genTools } : {}),
                    safetySettings: [
                        { category: HarmCategory.HARM_CATEGORY_HARASSMENT, threshold: HarmBlockThreshold.BLOCK_NONE },
                        { category: HarmCategory.HARM_CATEGORY_HATE_SPEECH, threshold: HarmBlockThreshold.BLOCK_NONE },
                        { category: HarmCategory.HARM_CATEGORY_SEXUALLY_EXPLICIT, threshold: HarmBlockThreshold.BLOCK_NONE },
                        { category: HarmCategory.HARM_CATEGORY_DANGEROUS_CONTENT, threshold: HarmBlockThreshold.BLOCK_NONE }
                    ]
                }
            });

            // 3. Robust candidate validation
            const candidates = response.candidates || [];
            if (candidates.length === 0) {
                throw new Error('EMPTY_RESPONSE: Gemini returned no candidates');
            }

            const candidate = candidates[0];
            const finishReason = candidate.finishReason;

            if (finishReason === 'SAFETY' || finishReason === 'RECITATION' || finishReason === 'OTHER') {
                throw new Error(`BLOCKED_RESPONSE: ${finishReason}`);
            }

            const content = candidate.content;
            if (!content || !content.parts || content.parts.length === 0) {
                throw new Error('MALFORMED_RESPONSE: No content parts');
            }

            const text = response.text?.() || content.parts?.[0]?.text || '';

            const rawParts = content.parts || [];
            const functionCalls: FunctionCall[] = rawParts
                .map((p: any) => {
                    if (p.functionCall) {
                        return {
                            name: p.functionCall.name as string,
                            args: p.functionCall.args as Record<string, unknown>
                        };
                    }
                    return null;
                })
                .filter((p: FunctionCall | null): p is FunctionCall => p !== null);

            if (this.keyVault) {
                this.keyVault.resetFailCount();
            }
            this.healthState = 'READY';

            const modelResponse: ModelResponse = {
                model: targetModel,
                response: text,
                latency: Date.now() - startTime,
                ...(functionCalls.length > 0 ? { functionCalls } : {})
            };

            return { ok: true, value: modelResponse };
        }, modelOverride || this.currentModel, prompt, tools);
    }

    private async retryWithBackoff<T>(
        fn: () => Promise<Result<T>>,
        model: string,
        prompt: string,
        tools?: Tool[],
        maxAttempts = 3,
        initialDelay = 1000
    ): Promise<Result<T>> {
        let lastError: Error | unknown;
        for (let attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                const result = await fn();
                if (result.ok) return result;

                // If the error is quota/auth, we might still want to handle it via rotateKey
                // but let's see if we should retry first
                lastError = result.error;
            } catch (error: unknown) {
                lastError = error;
                const { isQuota, isAuth, message } = this.classifyError(error);

                if (isQuota && model !== 'gemini-2.0-flash-lite') {
                    logger.warn({ model }, 'Quota hit, falling back to Flash Lite for retry attempt');
                    return (this.generateContent(prompt, 'gemini-2.0-flash-lite', tools) as Promise<Result<T>>);
                }

                if ((isQuota || isAuth) && this.keyVault) {
                    const rotated = this.keyVault.rotateKey(isQuota ? 'rate_limit' : 'auth_error');
                    if (rotated) {
                        const newKey = this.keyVault.getCurrentKey();
                        if (newKey) {
                            logger.info('Retrying with rotated key');
                            this.genAI = new GoogleGenAI({ apiKey: newKey });
                            // Reset model connection
                            return (this.generateContent(prompt, model, tools) as Promise<Result<T>>);
                        }
                    }
                }

                if (!this.isRetryable(error) || attempt === maxAttempts) {
                    if (isQuota) {
                        this.healthState = 'RATE_LIMITED';
                        this.lastBackoffUntil = Date.now() + 60000;
                        logger.error({ model, cooldown: 60 }, 'Gemini rate limit hit - entering cooldown');
                    } else if (isAuth) {
                        this.healthState = 'CRITICAL_FAILURE';
                    }
                    break;
                }

                const delay = initialDelay * Math.pow(2, attempt - 1);
                logger.warn({ attempt, delay, error: message }, 'Retrying Gemini request after backoff');
                await new Promise(resolve => setTimeout(resolve, delay));
            }
        }

        const message = lastError instanceof Error ? lastError.message : 'Unknown Gemini error';
        logger.error({
            error: message,
            model,
            stack: lastError instanceof Error ? lastError.stack : undefined
        }, 'Gemini generation failed after retries');
        return { ok: false, error: (lastError instanceof Error ? lastError : new Error(message)) };
    }

    private isRetryable(error: unknown): boolean {
        const message = error instanceof Error ? error.message.toLowerCase() : String(error).toLowerCase();
        return message.includes('empty_response') ||
            message.includes('malformed_response') ||
            message.includes('500') ||
            message.includes('503') ||
            message.includes('deadline') ||
            message.includes('econnreset');
    }

    async generateContentStream(prompt: string, modelOverride?: string): Promise<Result<AsyncGenerator<string, void, unknown>>> {
        const health = this.getHealth();
        if (health.state !== 'READY') return { ok: false, error: new Error('Gemini not ready') };

        const targetModel = modelOverride || this.currentModel;
        try {
            const responseStream = await this.genAI.models.generateContentStream({
                model: targetModel,
                contents: [{ role: 'user', parts: [{ text: prompt }] }]
            });

            async function* streamGenerator() {
                for await (const chunk of responseStream) {
                    const text = chunk.text?.() || '';
                    if (text) yield text;
                }
            }

            if (this.keyVault) {
                this.keyVault.resetFailCount();
            }

            return { ok: true, value: streamGenerator() };
        } catch (error: unknown) {
            const err = error instanceof Error ? error : new Error(String(error));
            logger.error({ error: err.message, model: targetModel }, 'Gemini stream failed');
            return { ok: false, error: err };
        }
    }

    async embed(text: string): Promise<Result<Float32Array>> {
        try {
            const result = await this.genAI.models.embedContent({
                model: 'text-embedding-004',
                contents: [{ role: 'user', parts: [{ text }] }]
            });
            const embedding = result.embeddings?.[0];

            if (!embedding || !embedding.values) {
                throw new Error('No embedding returned');
            }

            return { ok: true, value: new Float32Array(embedding.values) };
        } catch (error: unknown) {
            const err = error instanceof Error ? error : new Error(String(error));
            logger.error({ error: err.message }, 'Embedding generation failed');
            return { ok: false, error: err };
        }
    }
}

import { VectorDB } from '../learning/VectorDB.js';
import { Result, BuildStatus, HealthStatus, ResourcePressure, UserEngagement } from './models.js';
import { HEXAGRAM_REGISTRY, DEFAULT_HEXAGRAM, HexagramDefinition } from './HexagramDefinitions.js';

export enum YaoState {
    OldYang = 0, // Moving Yang
    YoungYin = 1, // Stable Yin
    YoungYang = 2, // Stable Yang
    OldYin = 3    // Moving Yin
}

export interface ContextCard {
    lineIndex: number;
    title: string;
    content: string;
    importance: number;
    state: YaoState;
    updatedAt?: string;
}

export interface SystemState {
    buildPass: BuildStatus;
    cloudHealthy: HealthStatus;
    localModels: HealthStatus;
    noRecentErrors: HealthStatus;
    userActive: UserEngagement;
    lowResourcePressure: ResourcePressure;
    /** Line 6: Dashboard/Preview/WebSocket health */
    dashboardHealthy?: HealthStatus;
}

export class HexagramManager {
    private lines: ContextCard[] = [];
    private readonly projectId: string;

    private readonly FACET_MAP: Record<number, string> = {
        1: 'Foundation / Structural Roots',
        2: 'Memory Pulse / Service Health',
        3: 'Transition / Current Activity',
        4: 'External Environment / Dependencies',
        5: 'Authority / Core Business Logic',
        6: 'Culmination / UI & User Perception'
    };

    constructor(private readonly vectorDB: VectorDB, projectId: string) {
        this.projectId = projectId;
    }

    async initialize(): Promise<void> {
        const result = await this.vectorDB.getHexagramContext(this.projectId);
        if (result.ok) {
            this.lines = (result.value as any[]).map((row: any) => ({
                lineIndex: row.lineIndex as number,
                title: (row.title as string) || 'Untitled',
                content: (row.content as string) || '',
                importance: (row.importance as number) || 1,
                state: (row.state as number) as YaoState
            }));
        }

        // Ensure 6 lines exist
        while (this.lines.length < 6) {
            this.lines.push({
                lineIndex: this.lines.length + 1,
                title: 'Empty Slot',
                content: 'No context recorded for this pillar.',
                importance: 0,
                state: YaoState.YoungYang // Default Young Yang
            });
        }
    }

    async setLine(index: number, card: ContextCard): Promise<Result<void>> {
        if (index < 1 || index > 6) {
            return { ok: false, error: new Error('Invalid line index (1-6)') };
        }
        this.lines[index - 1] = card;
        return this.vectorDB.updateHexagramLine(index, this.projectId, card.title, card.content, card.state);
    }

    async getHexagramContext(): Promise<Result<ContextCard[]>> {
        return { ok: true, value: this.lines };
    }

    async pinCard(index: number, title: string, content: string, state: YaoState = YaoState.YoungYang): Promise<Result<void>> {
        if (index < 1 || index > 6) {
            return { ok: false, error: new Error('Invalid line index (1-6)') };
        }
        const card: ContextCard = { lineIndex: index, title, content, state, importance: 1 };

        // Persist to VectorDB for long-term Context Memory (Resilient)
        if (this.vectorDB) {
            try {
                // Fire and forget - do not await to avoid blocking critical metabolic loops
                void this.vectorDB.addLesson({
                    id: `hex_card_${Date.now()}_${index}`,
                    projectId: this.projectId,
                    sessionId: 'system',
                    text: `Hexagram Card [Line ${index}]: ${title} - ${content} (${YaoState[state]})`,
                    embedding: new Float32Array(768).fill(0), // Initialized state
                    createdAt: Date.now(),
                    metadata: { type: 'hexagram_card', line: index, state: YaoState[state] },
                    errorType: 'none'
                }).catch(() => { });
            } catch (e) {
                // Ignore synchronous errors
            }
        }

        return this.setLine(index, card);
    }

    /**
     * Dynamically casts the Hexagram based on real-time system state.
     * Maps operational metrics to the 6 Yao lines.
     */
    async updateLinesFromState(state: SystemState): Promise<void> {
        // Line 1: Foundation (Build Status)
        // Pass = Yang (Solid), Fail = Yin (Broken), Warning/Partial = Old Yang (Change)
        let buildYao = YaoState.YoungYin;
        if (state.buildPass === BuildStatus.Passed) buildYao = YaoState.YoungYang;
        else if (state.buildPass === BuildStatus.Warning) buildYao = YaoState.OldYang;

        await this.pinCard(1, 'Build Foundation',
            state.buildPass === BuildStatus.Passed ? 'Build Passing' : (state.buildPass === BuildStatus.Warning ? 'Issues Detected' : 'Build Failing'),
            buildYao);

        // Line 3: Transition (Recent Errors)
        // Stable = Yang, Critical = Yin, Degraded = Moving
        let stabilityYao = YaoState.YoungYang;
        if (state.noRecentErrors === HealthStatus.Critical) stabilityYao = YaoState.YoungYin;
        else if (state.noRecentErrors === HealthStatus.Degraded) stabilityYao = YaoState.OldYin;

        await this.pinCard(3, 'System Stability',
            state.noRecentErrors === HealthStatus.Ready ? 'Stable' : (state.noRecentErrors === HealthStatus.Degraded ? 'Errors Detected' : 'Critical Errors'),
            stabilityYao);

        // Line 4: Environment (Cloud/Resources)
        // Optimal = Yang, Critical = Yin, High Pressure = Moving
        let resourceYao = YaoState.YoungYang;
        if (state.cloudHealthy === HealthStatus.Critical || state.lowResourcePressure === ResourcePressure.Critical)
            resourceYao = YaoState.YoungYin;
        else if (state.cloudHealthy === HealthStatus.Degraded || state.lowResourcePressure === ResourcePressure.High)
            resourceYao = YaoState.OldYin;

        await this.pinCard(4, 'External Environment',
            state.cloudHealthy === HealthStatus.Ready ? 'Cloud Nominal' : 'Resource Pressure/Degradation',
            resourceYao);

        // Line 5: Authority (Local/Cloud Models)
        // Ready = Yang, Critical = Yin, Degraded = Moving
        let cognitiveYao = YaoState.YoungYang;
        if (state.localModels === HealthStatus.Critical) cognitiveYao = YaoState.YoungYin;
        else if (state.localModels === HealthStatus.Degraded) cognitiveYao = YaoState.OldYang;

        await this.pinCard(5, 'Cognitive Authority',
            state.localModels === HealthStatus.Ready ? 'Local Models Active' : 'Reliance on Cloud Only',
            cognitiveYao);

        // Line 6: Culmination (Dashboard/UI/Preview Health)
        // Ready = Yang, Critical = Yin, Degraded = Moving
        let dashboardYao = YaoState.YoungYang;
        if (state.dashboardHealthy === HealthStatus.Critical) dashboardYao = YaoState.YoungYin;
        else if (state.dashboardHealthy === HealthStatus.Degraded) dashboardYao = YaoState.OldYin;

        await this.pinCard(6, 'UI Culmination',
            state.dashboardHealthy === HealthStatus.Ready ? 'Dashboard Connected' : 'Dashboard Disconnected',
            dashboardYao);
    }

    /**
     * Calculates the current I Ching Hexagram based on the 6 Yao states.
     * Returns a strategic definition capable of guiding agent behavior.
     */
    getInterpretation(): HexagramDefinition {
        const binaryId = this.calculateHexagramId(this.lines, false);
        const fallback: HexagramDefinition = {
            ...DEFAULT_HEXAGRAM,
            binary: binaryId,
            id: 0,
            name: 'Unknown Archetype',
            description: 'No interpretation found for this state.',
            strategy: 'MAINTAIN'
        };
        return HEXAGRAM_REGISTRY[binaryId] || fallback;
    }

    async formatForPrompt(queryEmbedding?: Float32Array): Promise<string> {
        const result = await this.getHexagramContext();
        if (!result.ok) return 'Hexagram context unavailable.';

        const cards = result.value;
        const metadata = this.getInterpretation();

        let output = '=== SOVEREIGN HEXAGRAM CONTEXT ===\n';
        output += `ARCHETYPE: ${metadata.name} (${metadata.binary})\n`;
        output += `MEANING: ${metadata.description}\n`;
        output += `> STRATEGIC DIRECTIVE: ${metadata.strategy}\n\n`;

        output += 'The following high-priority context cards are pinned to the active hexagram:\n\n';

        for (let i = 1; i <= 6; i++) {
            const card = cards.find(c => c.lineIndex === i) || cards[i - 1];
            const facet = this.FACET_MAP[i];

            if (card) {
                const stateStr = this.getStateString(card.state);
                output += `Line ${i} [${facet}]:\n`;
                output += `TITLE: ${card.title}\n`;
                output += `STATE: ${stateStr}\n`;
                output += `CONTENT: ${card.content}\n\n`;
            } else {
                output += `Line ${i} [${facet}]: (Empty)\n\n`;
            }
        }

        // --- SEMANTIC MEMORY (Proactive RAG) ---
        if (queryEmbedding) {
            const similar = await this.vectorDB.searchSimilar(queryEmbedding, 5, this.projectId);
            if (similar.ok && similar.value.length > 0) {
                const currentProject = similar.value.filter(l => l.projectId === this.projectId);
                const crossProject = similar.value.filter(l => l.projectId !== this.projectId && l.projectId !== 'global');

                if (currentProject.length > 0) {
                    output += '=== SEMANTIC MEMORY (Active Project Lessons) ===\n';
                    output += 'The following historical patterns are relevant to the current intent:\n\n';
                    for (const lesson of currentProject) {
                        output += `[LESSON: ${lesson.metadata?.['type'] || 'General'}]\n`;
                        output += `CONTEXT: ${lesson['text'].substring(0, 500)}${lesson['text'].length > 500 ? '...' : ''}\n\n`;
                    }
                }

                if (crossProject.length > 0) {
                    output += '=== PROJECT CONSTELLATION (Cross-Workspace Semantic Memory) ===\n';
                    output += 'The following high-fidelity patterns have been identified from other sovereign workspaces:\n\n';
                    for (const lesson of crossProject) {
                        output += `[SHORTCUT FROM PROJECT: ${lesson.projectId}]\n`;
                        output += `PATTERN: ${lesson['text'].substring(0, 600)}${lesson['text'].length > 600 ? '...' : ''}\n\n`;
                    }
                    output += '>> Acknowledge these patterns in your reasoning if they prevent regression or provide optimal shortcuts.\n\n';
                }
            }
        }

        const hasMoving = cards.some(c => c.state === YaoState.OldYang || c.state === YaoState.OldYin);

        if (hasMoving) {
            const futureId = this.calculateHexagramId(cards, true);
            const futureMeta = HEXAGRAM_REGISTRY[futureId] || { name: 'Unknown', strategy: 'Uncertainty' };
            output += `\n>> FUTURE TRANSITION: ${futureMeta.name}\n`;
            output += `>> FUTURE STRATEGY: ${futureMeta.strategy}\n`;
        }

        return output;
    }

    private getStateString(state: number): string {
        switch (state) {
            case YaoState.OldYang: return 'Old Yang (◯ Moving)';
            case YaoState.YoungYin: return 'Young Yin (⚋ Stable)';
            case YaoState.YoungYang: return 'Young Yang (⚊ Stable)';
            case YaoState.OldYin: return 'Old Yin (✕ Moving)';
            default: return 'Unknown';
        }
    }

    private calculateHexagramId(cards: ContextCard[], future: boolean): string {
        // Yang (1) = YoungYang (2) or OldYang (0)
        // Yin (0) = YoungYin (1) or OldYin (3)
        // If future is true, OldYang becomes Yin, OldYin becomes Yang.

        let binary = '';
        for (let i = 1; i <= 6; i++) {
            const card = cards.find(c => c.lineIndex === i) || cards[i - 1];
            const state = card ? card.state : 2; // Default to YoungYang if empty

            let isYang = (state === 0 || state === 2);
            if (future) {
                if (state === 0) isYang = false; // Old Yang -> Yin
                if (state === 3) isYang = true;  // Old Yin -> Yang
            }
            binary = (isYang ? '1' : '0') + binary; // Bottom to top
        }
        return binary;
    }
}

import { spawn, exec } from 'child_process';
import { promisify } from 'util';
import pino from 'pino';
import { Tool } from '@google/genai';
import {
    Result,
    ModelResponse,
    VibeConfig,
    ModelAbility as MA
} from './models.js';
import { GeminiService } from './GeminiService.js';
import type { FreeModelRouter } from './Router.js';

const execAsync = promisify(exec);

export class ModelExecutor {
    private readonly logger: pino.Logger;

    constructor(
        private readonly config: VibeConfig,
        private readonly geminiService: GeminiService | undefined,
        private router?: FreeModelRouter
    ) {
        this.logger = pino({
            name: 'ModelExecutor',
            base: { hostname: this.config.agentName }
        });
    }

    setRouter(router: FreeModelRouter) {
        this.router = router;
    }

    async callModel(model: string, prompt: string, tools?: Tool[]): Promise<Result<ModelResponse>> {
        const startTime = Date.now();

        // 1. Explicit Cloud Redirects (Prefix-based)
        if (model.startsWith('gemini:')) {
            const geminiModel = model.replace('gemini:', '');
            return this.callGeminiFallback(prompt, geminiModel, tools);
        }

        if (model.startsWith('cloudflare:')) {
            const cfModel = model.replace('cloudflare:', '');
            return this.callCloudflareGateway(prompt, cfModel, startTime);
        }

        const STORAGE_THRESHOLD_GB = 5;
        const CONTEXT_THRESHOLD_TOKENS = 32000;

        // 2. Resource Health Checks (Local Stability)
        const storageCheck = await this.checkStorageHealth(STORAGE_THRESHOLD_GB);
        if (storageCheck.ok === false) {
            this.logger.warn({ error: (storageCheck as { error: Error }).error, action: 'forcing_cloud_fallback' }, 'Local storage critical');
            return this.callGeminiFallback(prompt, undefined, tools);
        }

        // 3. Context Overflow Detection
        const estimatedTokens = prompt.length / 4;
        if (estimatedTokens > CONTEXT_THRESHOLD_TOKENS) {
            this.logger.info({ tokens: estimatedTokens, action: 'forcing_cloud_fallback' }, 'Prompt exceeds local context');
            return this.callGeminiFallback(prompt, 'gemini-2.0-flash', tools);
        }

        // 4. Execution Chain: Local -> Cloudflare -> Gemini -> Sovereign CLI -> Ghost Limb
        const tiers: import('./models.js').CascadeTier[] = [];
        let generationMode: 'AI' | 'CLI-Fallback' | 'Ghost-Limb' = 'AI';
        let failureCount = 0;

        try {
            const response = await this.callOllama(model, prompt);
            tiers.push({ name: 'Local Ollama', status: 'success', timestamp: Date.now() });
            return {
                ok: true,
                value: {
                    model,
                    response,
                    latency: Date.now() - startTime,
                    provenance: { tiers, finalModel: model, latency: Date.now() - startTime, generationMode, failureCount }
                }
            };
        } catch (ollamaError) {
            const errorMessage = ollamaError instanceof Error ? ollamaError.message : String(ollamaError);
            tiers.push({ name: 'Local Ollama', status: 'failure', error: errorMessage, timestamp: Date.now() });
            failureCount++;

            // Try Cloudflare as Primary Backup
            const cfResult = await this.callCloudflareGateway(prompt, model, startTime);
            if (cfResult.ok) {
                tiers.push({ name: 'Cloudflare Edge', status: 'success', timestamp: Date.now() });
                const val = cfResult.value;
                return {
                    ok: true,
                    value: {
                        ...val,
                        provenance: { tiers, finalModel: val.model, latency: Date.now() - startTime, generationMode, failureCount }
                    }
                };
            }
            tiers.push({ name: 'Cloudflare Edge', status: 'failure', error: String(cfResult.error), timestamp: Date.now() });
            failureCount++;

            // Secondary Fallback to Gemini SDK
            try {
                const geminiResult = await this.callGeminiFallback(prompt, undefined, tools, true);
                tiers.push({ name: 'Gemini Cloud', status: 'success', timestamp: Date.now() });
                const val = (geminiResult as { value: ModelResponse }).value; // Now strictly typed Result<ModelResponse>
                return {
                    ok: true,
                    value: {
                        ...val,
                        provenance: { tiers, finalModel: val.model, latency: Date.now() - startTime, generationMode, failureCount }
                    }
                };
            } catch (geminiError) {
                const errorMessage = geminiError instanceof Error ? geminiError.message : String(geminiError);
                tiers.push({ name: 'Gemini Cloud', status: 'failure', error: errorMessage, timestamp: Date.now() });
                failureCount++;
                generationMode = 'CLI-Fallback';

                // Tertiary Fallback: Sovereign CLI
                const cliResult = await this.callSovereignCLI(prompt);
                if (cliResult.ok) {
                    tiers.push({ name: 'Sovereign CLI', status: 'success', timestamp: Date.now() });
                    const val = cliResult.value;
                    return {
                        ok: true,
                        value: {
                            ...val,
                            provenance: { tiers, finalModel: val.model, latency: Date.now() - startTime, generationMode, failureCount }
                        }
                    };
                }
                tiers.push({ name: 'Sovereign CLI', status: 'failure', error: String(cliResult.error), timestamp: Date.now() });
                failureCount++;

                // Final "Ghost" Fallback (Deterministic)
                generationMode = 'Ghost-Limb';
                const task = model.includes('code') ? 'code-scaffold' : 'text-template';
                const ghostResult = await this.callGhostLimb(task, { prompt });

                if (ghostResult.ok) {
                    tiers.push({ name: 'Ghost Limb', status: 'success', timestamp: Date.now() });
                    return {
                        ok: true,
                        value: {
                            model: `ghost:${task}`,
                            response: (ghostResult.value['result'] as string) || JSON.stringify(ghostResult.value),
                            latency: Date.now() - startTime,
                            provenance: { tiers, finalModel: `ghost:${task}`, latency: Date.now() - startTime, generationMode, failureCount }
                        }
                    };
                }

                return { ok: false, error: cliResult.error };
            }
        }
    }

    /**
     * Generic Cloudflare AI call (Used for Media/Image Gen)
     */
    async callCloudflareAI(model: string, input: unknown, isBinaryInput = false): Promise<Result<unknown>> {
        const gatewayUrl = this.config.cloudflareGatewayUrl;
        if (!gatewayUrl) {
            return { ok: false, error: new Error('Cloudflare AI Gateway URL not configured') };
        }

        const startTime = Date.now();
        try {
            const finalUrl = gatewayUrl.endsWith('/') ? `${gatewayUrl}${model}` : `${gatewayUrl}/${model}`;

            const headers: Record<string, string> = {
                'Authorization': `Bearer ${process.env['CLOUDFLARE_API_TOKEN'] || process.env['CLOUDFLARE_API_KEY'] || ''}`
            };

            if (!isBinaryInput) {
                headers['Content-Type'] = 'application/json';
            } else {
                headers['Content-Type'] = 'application/octet-stream';
            }

            const response = await fetch(finalUrl, {
                method: 'POST',
                headers,
                body: (isBinaryInput ? (input as any) : JSON.stringify(input))
            });

            const latency = Date.now() - startTime;
            this.logger.debug({ model, latency }, 'Cloudflare AI call completed');

            if (!response.ok) {
                const errorBody = await response.text();
                return { ok: false, error: new Error(`Cloudflare AI failed (${response.status}): ${errorBody}`) };
            }

            // Image generation usually returns binary or base64
            const contentType = response.headers.get('content-type');
            if (contentType?.includes('application/json')) {
                const data = await response.json();
                return { ok: true, value: data };
            } else {
                // Return as buffer/blob for media
                const buffer = await response.arrayBuffer();
                return { ok: true, value: Buffer.from(buffer) };
            }
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    async transcribeAudio(audioBuffer: Buffer): Promise<Result<string>> {
        const model = this.router ? this.router.routeByAbility(MA.Transcription) : "@cf/openai/whisper";
        this.logger.info({ model }, 'Calling Cloudflare Whisper for transcription');

        const result = await this.callCloudflareAI(model, audioBuffer, true);
        if (!result.ok) return result as unknown as Result<string>;

        const data = result.value as { result?: { text?: string }; text?: string };
        if (data.result && data.result.text) {
            return { ok: true, value: data.result.text };
        }

        return { ok: true, value: data.text || JSON.stringify(data) };
    }

    /**
     * Call a deterministic "Ghost Limb" fallback in the Cloudflare Worker
     */
    async callGhostLimb(task: string, input: unknown): Promise<Result<Record<string, unknown>>> {
        const gatewayUrl = this.config.cloudflareGatewayUrl;
        if (!gatewayUrl) return { ok: false, error: new Error('Cloudflare AI Gateway URL not configured') };

        try {
            const finalUrl = gatewayUrl.endsWith('/') ? `${gatewayUrl}deterministic/${task}` : `${gatewayUrl}/deterministic/${task}`;
            const response = await fetch(finalUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${process.env['CLOUDFLARE_API_TOKEN'] || process.env['CLOUDFLARE_API_KEY'] || ''}`
                },
                body: JSON.stringify(input)
            });

            if (!response.ok) throw new Error(`Ghost Limb failed (${response.status})`);
            return { ok: true, value: await response.json() as Record<string, unknown> };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    private async callCloudflareGateway(
        prompt: string,
        model: string,
        startTime: number
    ): Promise<Result<ModelResponse>> {
        const gatewayUrl = this.config.cloudflareGatewayUrl;
        if (!gatewayUrl) {
            return { ok: false, error: new Error('Cloudflare AI Gateway URL not configured') };
        }

        try {
            // Use the passed model or a default
            const cfModel = model.startsWith('@cf/') || model.startsWith('@hf/') ? model : "@cf/meta/llama-3.1-8b-instruct";

            const finalUrl = gatewayUrl.endsWith('/') ? `${gatewayUrl}ai/run/${cfModel}` : `${gatewayUrl}/ai/run/${cfModel}`;
            const response = await fetch(finalUrl, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${process.env['CLOUDFLARE_API_TOKEN'] || process.env['CLOUDFLARE_API_KEY'] || ''}`
                },
                body: JSON.stringify({
                    messages: [{ role: 'user', content: prompt }]
                })
            });

            if (!response.ok) {
                const errorText = await response.text();
                throw new Error(`Cloudflare Hub failed (${response.status}): ${errorText}`);
            }

            const data = await response.json() as { response?: string; result?: { response?: string } };
            return {
                ok: true,
                value: {
                    model: `cloudflare:${cfModel}`,
                    response: data.response || data.result?.response || JSON.stringify(data),
                    latency: Date.now() - startTime
                }
            };
        } catch (error) {
            const err = error instanceof Error ? error : new Error(String(error));
            this.logger.error({ error: err.message }, 'Cloudflare Universal Hub call failed critically');
            return { ok: false, error: err };
        }
    }

    private async callGeminiFallback(
        prompt: string,
        modelOverride?: string,
        tools?: Tool[],
        disableFallback = false
    ): Promise<Result<ModelResponse>> {
        const startTime = Date.now();
        try {
            if (!this.geminiService) {
                throw new Error('Gemini Service is not initialized (check GOOGLE_API_KEY)');
            }

            const result = await this.geminiService.generateContent(prompt, modelOverride, tools);
            if (!result.ok) throw (result as any).error;

            return result;
        } catch (geminiError) {
            if (disableFallback) throw geminiError;

            this.logger.warn({ geminiError }, 'Gemini execution failed, attempting Cloudflare AI Gateway');
            return this.callCloudflareGateway(prompt, modelOverride || 'gemini-2.0-flash', startTime);
        }
    }

    private async callSovereignCLI(prompt: string): Promise<Result<ModelResponse>> {
        const startTime = Date.now();
        // Using 'gemini -y' as the primary sovereign fallback.
        // This assumes the user has a 'gemini' CLI tool in their path, distinct from the 'gcloud' resource manager.
        // If 'gemini' is not found, we could try 'gcloud gemini ...' but mostly likely that is for resource mgmt.
        // The user's prompt implies 'gemini -y' is the way to Prompt the model.
        const cmd = `gemini -y "${prompt.replace(/"/g, '\\"')}"`;

        try {
            this.logger.info({ cmd }, 'Invoking Sovereign CLI Fallback');
            const { stdout, stderr } = await execAsync(cmd);

            if (stderr && !stdout) {
                this.logger.warn({ stderr }, 'Sovereign CLI stderr output');
            }

            // If we get output, we assume success even if there was stderr (warnings)
            if (stdout) {
                return {
                    ok: true,
                    value: {
                        model: 'cli:gemini-y',
                        response: stdout.trim(),
                        latency: Date.now() - startTime
                    }
                };
            }

            return { ok: false, error: new Error(`Sovereign CLI produced no output. Stderr: ${stderr}`) };

        } catch (error) {
            return { ok: false, error: new Error(`Sovereign CLI execution failed: ${error instanceof Error ? error.message : String(error)}`) };
        }
    }

    private async callOllama(model: string, prompt: string): Promise<string> {
        return new Promise((resolve, reject) => {
            const ollamaPath = this.config.ollamaModelsPath ||
                this.config.errorTrackerModelPath ||
                'D:\\ollama-models';
            this.logger.info({ model, path: ollamaPath }, 'Invoking Ollama CLI with custom model path');

            const child = spawn('ollama', ['run', model, prompt], {
                env: {
                    ...process.env,
                    OLLAMA_MODELS: ollamaPath
                },
                shell: true
            });

            const timeout = setTimeout(() => {
                child.kill();
                reject(new Error(`Ollama execution timed out after 30s for model: ${model}`));
            }, 30000);

            let stdout = '';
            let stderr = '';

            child.stdout.on('data', (data) => {
                stdout += data.toString();
            });

            child.stderr.on('data', (data) => {
                stderr += data.toString();
            });

            child.on('close', (code) => {
                clearTimeout(timeout);
                if (code === 0) {
                    resolve(stdout.trim());
                } else {
                    reject(new Error(`Ollama CLI failed with code ${code}: ${stderr}`));
                }
            });

            child.on('error', (err) => {
                clearTimeout(timeout);
                reject(err);
            });
        });
    }

    private async checkStorageHealth(thresholdGB: number): Promise<Result<number>> {
        try {
            // Windows specific command
            const { stdout } = await execAsync('wmic logicaldisk where "DeviceID=\'C:\'" get FreeSpace');
            const lines = stdout.trim().split('\n');
            const freeBytesStr = lines[1]?.trim() || '';
            const freeBytes = parseInt(freeBytesStr, 10);

            if (isNaN(freeBytes)) {
                this.logger.error({ stdout }, 'Failed to parse free space from WMIC');
                return { ok: true, value: 1024 };
            }

            const freeGB = freeBytes / 1024 / 1024 / 1024;
            if (freeGB < thresholdGB) {
                return { ok: false, error: new Error(`Low Disk Space: ${freeGB.toFixed(2)}GB`) };
            }
            return { ok: true, value: freeGB };
        } catch (error) {
            this.logger.error({ error }, 'Storage health check failed critically');
            return { ok: true, value: 1024 };
        }
    }
}

import { StaticModelRegistry } from '../api/ai/StaticModelRegistry.js';
import { FreeModelConfig, ModelType } from './models.js';

/**
 * ModelInventory
 * Bridges the static registry (scraped from AI+API_LIST.md) to the dynamic router.
 */
export class ModelInventory {
    static getAvailableModels(): FreeModelConfig[] {
        return Object.values(StaticModelRegistry).map(cap => {
            const serviceType = cap.serviceType as string;
            const modelId = cap.modelId || 'unknown-model';
            const id = cap.id;

            const isLocal = serviceType === 'OLLAMA';
            const isCloudflare = serviceType === 'MEDIA_FORGE' && modelId.startsWith('@cf');
            const isGemini = serviceType === 'GEMINI';

            let type = ModelType.CloudFree;
            if (isLocal) type = ModelType.Local;
            else if (isCloudflare) type = ModelType.Cloudflare;

            const taskType = cap.taskType.toLowerCase();

            // Determine command
            let command = `google:${modelId}`;
            if (isLocal) command = `ollama run ${modelId}`;
            else if (isCloudflare) command = `cloudflare:run ${modelId}`;

            // Determine Priority & Dynamic Fallback
            let priority = id.startsWith('gold_') ? 90 : 50;
            if (id.startsWith('side_')) priority = 70; // High priority for side-tasks
            if (id.includes('pro')) priority = 100;
            if (id.includes('flash')) priority = 80;

            // Tiered Fallback Logic (Trinity Substrate)
            let fallback: string | undefined;
            if (isGemini) {
                // Gemini (Reasoning) falls back to Cloudflare (Utility)
                fallback = 'gold_cloudflare_llama_3_1';
            } else if (isCloudflare) {
                // Cloudflare (Utility) falls back to Local (Sovereign)
                fallback = 'gold_qwen_2_5_coder_7b';
            } else if (id.startsWith('side_')) {
                // Side models fall back to primary local core
                fallback = 'gold_qwen_2_5_coder_7b';
            } else if (isLocal) {
                // Local core is the final substrate floor
                fallback = undefined;
            }

            return {
                name: modelId,
                command,
                type,
                capabilities: [taskType, 'agentic'],
                fallback: fallback || 'gold_qwen_2_5_coder_7b', // Final Sovereign floor
                maxTokens: id.includes('pro') ? 128000 : 32768,
                priority
                // Health is determined dynamically by Router.getModelHealthGrid()
            } as FreeModelConfig;
        });
    }


    /**
     * Helper to get full map for indexing
     */
    static getRegistry() {
        return StaticModelRegistry;
    }
}

