/**
 * IntentVerifier - The Sovereign Auditor.
 * Runs after every execution turn to ensure alignment with:
 * 1. Original User Intent (The "Command")
 * 2. Hexagram Context (The "Situation")
 * 3. Project Rules (The "Law")
 */
export class IntentVerifier {
    private readonly logger: pino.Logger;

    constructor(
        private readonly executor: ModelExecutor,
        private readonly hexagramManager: HexagramManager
    ) {
        this.logger = pino({ name: 'IntentVerifier' });
    }

    /**
     * Verifies the output of a single execution turn against the sovereign intent.
     */
    async verify(
        originalPrompt: string,
        turnResult: AgentTurnResult,
        context: ExecutionContext
    ): Promise<VerificationResult> {
        // Skip verification if the turn is just continuing (intermediate steps) unless strictly enforced
        // But the user requested "compare user intent requested against outputs as it goes", so we verify everything.

        const outputText = turnResult.status === 'stop'
            ? turnResult.finalResult || 'No output'
            : turnResult.nextMessage;

        const hexagramContext = await this.hexagramManager.formatForPrompt();

        const auditPrompt = `
=== SOVEREIGN AUDIT ===
Your task is to VERIFY if the following execution step aligns with the User's Sovereign Intent and the Project Rules.

ORIGINAL INTENT:
"${originalPrompt}"

CURRENT EXECUTION OUTPUT:
"${outputText.substring(0, 2000)}..."

CONSEQUENTIAL CONTEXT:
Session ID: ${context.sessionId}
File Path: ${context.filePath || 'None'}

CONTEXT (The Situation):
${hexagramContext}

PROJECT RULES (The Law):
1. NO MOCKS or Placeholders.
2. NO "I cannot do that" (unless physically impossible).
3. NO deviations from explicit commands (e.g. if user said "delete", did it delete?).

TASK:
Score the alignment from 0-100.
- 100: Perfect alignment.
- 80-99: Minor stylistic drift, but intent preserved.
- <50: Critical failure (Refusal, Hallucination, Rule Violation).

OUTPUT FORMAT (JSON):
{
  "score": number,
  "reasoning": "Brief explanation of the score",
  "correction": "Suggested fix if score < 80"
}
`;

        const result = await this.executor.callModel('gemini:gemini-3-flash-preview', auditPrompt);

        if (!result.ok) {
            this.logger.warn({ error: result.error }, 'Verification failed, assuming alignment');
            return { score: 100, isAligned: true, reasoning: 'Verifier offline' };
        }

        try {
            const responseText = result.value.response.replace(/```json|```/g, '').trim();
            const audit = JSON.parse(responseText);

            this.logger.info({
                score: audit.score,
                reason: audit.reasoning
            }, 'Intent Verification Complete');

            return {
                score: audit.score,
                isAligned: audit.score >= 80,
                reasoning: audit.reasoning,
                correction: audit.correction
            };

        } catch (e) {
            this.logger.error({ error: e, response: result.value.response }, 'Failed to parse verification audit');
            return { score: 100, isAligned: true, reasoning: 'Parse failure' };
        }
    }
}

/**
 * DiffPresenter - Visual diff generation and CLI presentation
 * Based on gemini-cli's write-file.ts diff patterns
 */

import * as Diff from 'diff';
import chalk from 'chalk';
import prompts from 'prompts';
import pino from 'pino';

const logger = pino({
    name: 'DiffPresenter',
    base: { hostname: 'POG-VIBE' }
});

export interface DiffResult {
    oldContent: string;
    newContent: string;
    patch: string;
    stats: { additions: number; deletions: number; changes: number };
}

export type UserAction = 'accept' | 'reject' | 'edit';

export class DiffPresenter {
    /**
     * Create unified diff between old and new content
     */
    static createDiff(oldContent: string, newContent: string, filename: string): DiffResult {
        const patch = Diff.createPatch(
            filename,
            oldContent,
            newContent,
            'Current',
            'Proposed',
            { context: 3 }
        );

        const changes = Diff.diffLines(oldContent, newContent);
        let additions = 0;
        let deletions = 0;
        let totalChanges = 0;

        changes.forEach(change => {
            if (change.added) {
                additions += change.count || 0;
                totalChanges++;
            }
            if (change.removed) {
                deletions += change.count || 0;
                totalChanges++;
            }
        });

        return {
            oldContent,
            newContent,
            patch,
            stats: { additions, deletions, changes: totalChanges }
        };
    }

    /**
     * Render diff with color coding for terminal
     */
    static renderDiff(diffResult: DiffResult): string {
        const lines = diffResult.patch.split('\n');

        return lines.map(line => {
            if (line.startsWith('+++ ') || line.startsWith('--- ')) {
                return chalk.bold(line);
            }
            if (line.startsWith('@@')) {
                return chalk.cyan(line);
            }
            if (line.startsWith('+')) {
                return chalk.green(line);
            }
            if (line.startsWith('-')) {
                return chalk.red(line);
            }
            return chalk.gray(line);
        }).join('\n');
    }

    /**
     * Display diff stats summary
     */
    static renderStats(stats: { additions: number; deletions: number; changes: number }): string {
        const parts = [];

        if (stats.additions > 0) {
            parts.push(chalk.green(`+${stats.additions}`));
        }
        if (stats.deletions > 0) {
            parts.push(chalk.red(`-${stats.deletions}`));
        }

        return `[${parts.join(' ')}] ${stats.changes} change(s)`;
    }

    /**
     * Show diff and prompt user for action
     */
    static async presentDiffAndPrompt(
        diffResult: DiffResult,
        filename: string
    ): Promise<UserAction> {
        console.log('\n' + chalk.bold.underline(`Changes to ${filename}:`));
        console.log(this.renderStats(diffResult.stats));
        console.log(this.renderDiff(diffResult));
        console.log('');

        try {
            const response = await prompts({
                type: 'select',
                name: 'action',
                message: 'Apply this change?',
                choices: [
                    { title: '✓ Accept', value: 'accept' },
                    { title: '✗ Reject', value: 'reject' },
                    { title: '✎ Edit', value: 'edit' }
                ],
                initial: 0
            });

            if (!response.action) {
                // User cancelled (Ctrl+C)
                logger.info('User cancelled diff review');
                return 'reject';
            }

            return response.action as UserAction;
        } catch (error) {
            logger.error({ error }, 'Prompt error, defaulting to reject');
            return 'reject';
        }
    }

    /**
     * Create inline diff (for compact display)
     */
    static createInlineDiff(oldContent: string, newContent: string): string {
        const changes = Diff.diffWords(oldContent, newContent);

        return changes.map(change => {
            if (change.added) {
                return chalk.green.bold(change.value);
            }
            if (change.removed) {
                return chalk.red.strikethrough(change.value);
            }
            return change.value;
        }).join('');
    }
}

/**
 * CodebaseIndexer - Auto-indexes project files into VectorDB
 * Respects .gitignore and filters out binary/generated files
 */

import { VectorDB } from './VectorDB.js';
import { GeminiService } from '../core/GeminiService.js';
import { readFileSync, readdirSync, statSync, existsSync } from 'fs';
import { join, relative } from 'path';
import ignore from 'ignore';
import pino from 'pino';

const logger = pino({
    name: 'CodebaseIndexer',
    base: { hostname: 'POG-VIBE' }
});

export class CodebaseIndexer {
    private readonly vectorDB: VectorDB;
    private readonly gemini: GeminiService | undefined;
    private ignoreFilter: ReturnType<typeof ignore>;
    private projectRoot: string;

    constructor(vectorDB: VectorDB, gemini: GeminiService | undefined, projectRoot: string) {
        this.vectorDB = vectorDB;
        this.gemini = gemini;
        this.projectRoot = projectRoot;
        this.ignoreFilter = this.loadGitignore(projectRoot);
    }

    /**
     * Update the project root for multi-workspace support
     */
    setProjectRoot(newRoot: string): void {
        this.projectRoot = newRoot;
        this.ignoreFilter = this.loadGitignore(newRoot);
        logger.info({ newRoot }, 'CodebaseIndexer root updated');
    }

    private loadGitignore(root: string): ReturnType<typeof ignore> {
        const ig = ignore();

        // Try to load .gitignore
        try {
            const gitignorePath = join(root, '.gitignore');
            if (existsSync(gitignorePath)) {
                const content = readFileSync(gitignorePath, 'utf8');
                ig.add(content);
            }
        } catch (error) {
            logger.debug({ error }, 'No .gitignore found, using defaults');
        }

        // Always ignore these
        ig.add([
            'node_modules/**',
            '.git/**',
            'dist/**',
            'build/**',
            'coverage/**',
            '.gemini/**',
            '*.lock',
            'package-lock.json',
            '.env',
            '*.log'
        ]);

        return ig;
    }

    /**
     * Index entire project into VectorDB
     */
    async indexProject(): Promise<{ indexed: number; skipped: number }> {
        logger.info({ root: this.projectRoot }, 'Starting codebase indexing');
        const startTime = Date.now();

        let indexed = 0;
        let skipped = 0;

        const processDir = async (dir: string) => {
            try {
                const files = readdirSync(dir);

                for (const file of files) {
                    const fullPath = join(dir, file);
                    const relPath = relative(this.projectRoot, fullPath);

                    if (this.ignoreFilter.ignores(relPath)) continue;

                    try {
                        const stat = statSync(fullPath);

                        if (stat.isDirectory()) {
                            await processDir(fullPath);
                        } else {
                            if (!this.isCodeFile(file)) continue;

                            try {
                                const content = readFileSync(fullPath, 'utf8');
                                if (content.length > 500000) {
                                    skipped++;
                                    continue;
                                }

                                // Generate real embedding if service is available
                                let embedding = new Float32Array(0);
                                const gemini = this.gemini;
                                if (gemini && typeof gemini.embed === 'function') {
                                    const embedResult = await gemini.embed(content);
                                    if (embedResult.ok) {
                                        embedding = new Float32Array(embedResult.value);
                                    }
                                }

                                await this.vectorDB.addLesson({
                                    id: relPath,
                                    text: content,
                                    embedding,
                                    sessionId: 'indexer',
                                    projectId: this.projectRoot.split(/[\\/]/).pop() || 'global',
                                    errorType: '',
                                    createdAt: Date.now(),
                                    metadata: {
                                        path: relPath,
                                        type: this.getFileType(fullPath),
                                        lines: content.split('\n').length
                                    }
                                });
                                indexed++;
                            } catch (e) {
                                logger.warn({ file: relPath }, 'Failed to index');
                                skipped++;
                            }
                        }
                    } catch (statError) {
                        // ignore stat errors
                    }
                }
            } catch (dirError) {
                // ignore dir errors
            }
        };

        await processDir(this.projectRoot);

        const elapsed = ((Date.now() - startTime) / 1000).toFixed(2);
        logger.info({ indexed, skipped, elapsed }, 'Indexing complete');

        return { indexed, skipped };
    }

    /**
     * Check if file is a code file worth indexing
     */
    private isCodeFile(filename: string): boolean {
        const codeExts = [
            '.ts', '.tsx', '.js', '.jsx',
            '.py', '.java', '.go', '.rs',
            '.c', '.cpp', '.h', '.hpp',
            '.rb', '.php', '.swift', '.kt',
            '.cs', '.scala', '.clj', '.ex',
            '.md', '.json', '.yaml', '.yml',
            '.sql', '.sh', '.bash'
        ];

        return codeExts.some(ext => filename.endsWith(ext));
    }

    /**
     * Determine file type from extension
     */
    private getFileType(filename: string): string {
        const ext = filename.split('.').pop()?.toLowerCase();

        const typeMap: Record<string, string> = {
            'ts': 'typescript',
            'tsx': 'typescript-react',
            'js': 'javascript',
            'jsx': 'javascript-react',
            'py': 'python',
            'java': 'java',
            'go': 'go',
            'rs': 'rust',
            'md': 'markdown',
            'json': 'json',
            'yaml': 'yaml',
            'yml': 'yaml'
        };

        return ext ? (typeMap[ext] || ext) : 'unknown';
    }

    /**
     * Index a single file (for incremental updates)
     */
    async indexFile(filePath: string): Promise<void> {
        const relativePath = relative(this.projectRoot, filePath);

        if (this.ignoreFilter.ignores(relativePath)) {
            logger.debug({ file: relativePath }, 'File ignored');
            return;
        }

        try {
            const content = readFileSync(filePath, 'utf8');

            // Generate real embedding if service is available
            let embedding = new Float32Array(0);
            const gemini = this.gemini;
            if (gemini && typeof gemini.embed === 'function') {
                const embedResult = await gemini.embed(content);
                if (embedResult.ok) {
                    embedding = new Float32Array(embedResult.value);
                }
            }

            await this.vectorDB.addLesson({
                id: relativePath,
                text: content,
                embedding,
                sessionId: 'indexer',
                projectId: this.projectRoot.split(/[\\/]/).pop() || 'global',
                errorType: '',
                createdAt: Date.now(),
                metadata: {
                    path: relativePath,
                    type: this.getFileType(filePath),
                    lines: content.split('\n').length
                }
            });

            logger.debug({ file: relativePath }, 'File indexed');
        } catch (error) {
            logger.error({ file: filePath, error }, 'Failed to index file');
        }
    }
}

/**
 * Vector Database - Local storage for lessons and embeddings
 * 
 * Responsibilities:
 * - Persist lessons and errors for long-term learning
 * - Provide vector search using cosine similarity (JS-side)
 * - Manage database schema
 */

import sqlite3 from 'sqlite3';
import pino from 'pino';
import type { Result, VibeConfig, Lesson } from '../core/models.js';
import { getLearningDbPath } from '../utils/SovereignPathResolver.js';

const logger = pino({
  name: 'VectorDB',
  base: { hostname: 'POG-VIBE' }
});

export class VectorDB {
  private db?: sqlite3.Database;
  private readonly dbPath: string;

  constructor(_config: VibeConfig) {
    // Use SovereignPathResolver for ternary-aware path resolution
    // Priority: D:\pog-coder-vibe\vibe-learning.db (Sovereign) → ~/.pog-coder-vibe/vibe-learning.db (Home) → .pog/vibe-learning.db (ProjectLocal)
    this.dbPath = getLearningDbPath();
  }

  async initialize(): Promise<Result<void>> {
    try {
      logger.info({ dbPath: this.dbPath }, 'Initializing VectorDB');

      return new Promise((resolve) => {
        this.db = new sqlite3.Database(this.dbPath, (err) => {
          if (err) {
            logger.error({ err }, 'Failed to open database');
            resolve({ ok: false, error: err });
            return;
          }

          this.createTables()
            .then(() => this.ensureSchema())
            .then(() => resolve({ ok: true, value: undefined }))
            .catch((tableErr: Error) => {
              logger.error({ tableErr }, 'Database table creation or migration failed');
              resolve({ ok: false, error: tableErr });
            });
        });
      });
    } catch (error) {
      return { ok: false, error: error as Error };
    }
  }

  async indexModelRegistry(_registry: Record<string, unknown>): Promise<Result<void>> {
    return new Promise((resolve) => {
      if (!this.db) {
        resolve({ ok: false, error: new Error('Database not initialized') });
        return;
      }

      this.db.serialize(() => {
        this.db!.run(`
          CREATE TABLE IF NOT EXISTS gutenberg_chunks (
            id TEXT PRIMARY KEY,
            book_id INTEGER NOT NULL,
            chunk_index INTEGER NOT NULL,
            content TEXT NOT NULL,
            embedding BLOB NOT NULL,
            metadata TEXT
          )
        `);

        // Index on book_id for faster filtering
        this.db!.run('CREATE INDEX IF NOT EXISTS idx_gutenberg_book_id ON gutenberg_chunks(book_id)');

        const stmt = this.db!.prepare(`
          INSERT OR REPLACE INTO model_capabilities (id, name, description, capabilities, embedding)
          VALUES (?, ?, ?, ?, ?)
        `);

        try {
          this.db!.run('BEGIN TRANSACTION');

          for (const [id, modelVal] of Object.entries(_registry)) {
            const model = modelVal as Record<string, unknown>;
            // Safe fallback for optional fields
            const name = (model['name'] as string) || id;
            const desc = (model['description'] as string) || '';
            const caps = JSON.stringify((model['capabilities'] as string[]) || []);
            const embed = model['embedding'] ? Buffer.from(model['embedding'] as Uint8Array | number[]) : null;

            stmt.run(id, name, desc, caps, embed);
          }

          this.db!.run('COMMIT', (err) => {
            stmt.finalize();
            if (err) resolve({ ok: false, error: err });
            else resolve({ ok: true, value: undefined });
          });
        } catch (err) {
          this.db!.run('ROLLBACK');
          stmt.finalize();
          resolve({ ok: false, error: err as Error });
        }
      });
    });
  }

  /**
   * Store literary chunks with vector embeddings.
   */
  async storeGutenbergChunks(chunks: Array<{
    id: string;
    bookId: number;
    chunkIndex: number;
    content: string;
    embedding: Float32Array;
    metadata?: Record<string, unknown>;
  }>): Promise<Result<void>> {
    return new Promise((resolve) => {
      if (!this.db) {
        resolve({ ok: false, error: new Error('Database not initialized') });
        return;
      }

      const stmt = this.db.prepare(`
        INSERT OR REPLACE INTO gutenberg_chunks (id, book_id, chunk_index, content, embedding, metadata)
        VALUES (?, ?, ?, ?, ?, ?)
      `);

      this.db.serialize(() => {
        try {
          this.db!.run('BEGIN TRANSACTION');

          for (const chunk of chunks) {
            stmt.run(
              chunk.id,
              chunk.bookId,
              chunk.chunkIndex,
              chunk.content,
              Buffer.from(chunk.embedding.buffer),
              JSON.stringify(chunk.metadata || {})
            );
          }

          this.db!.run('COMMIT', (err) => {
            stmt.finalize();
            if (err) resolve({ ok: false, error: err });
            else resolve({ ok: true, value: undefined });
          });
        } catch (err) {
          this.db!.run('ROLLBACK');
          stmt.finalize();
          resolve({ ok: false, error: err as Error });
        }
      });
    });
  }

  /**
   * Semantic search for literary context using cosine similarity.
   * NOTE: SQLite doesn't have native vector search, so we fetch all and compute in JS.
   * For production scaling, use pgvector/vector extension. For <1GB text, this is fine.
   */
  async searchGutenberg(embedding: Float32Array, limit: number = 5): Promise<Result<Array<{
    content: string;
    bookId: number;
    score: number;
    metadata: Record<string, unknown>;
  }>>> {
    return new Promise((resolve) => {
      if (!this.db) {
        resolve({ ok: false, error: new Error('Database not initialized') });
        return;
      }

      // Memory-efficient: Stream rows instead of loading all at once if possible,
      // but for <100k chunks, loading into memory is faster than iterated I/O.
      this.db.all('SELECT * FROM gutenberg_chunks', (err, rows: Array<Record<string, unknown>>) => {
        if (err) {
          resolve({ ok: false, error: err });
          return;
        }

        const results = rows.map(row => {
          const embeddingBuffer = row['embedding'] as Buffer;
          const storedEmbedding = new Float32Array(
            embeddingBuffer.buffer,
            embeddingBuffer.byteOffset,
            embeddingBuffer.byteLength / 4
          );

          return {
            content: row['content'] as string,
            bookId: row['book_id'] as number,
            score: this.cosineSimilarity(embedding, storedEmbedding),
            metadata: JSON.parse((row['metadata'] as string) || '{}') as Record<string, unknown>
          };
        });

        // Sort by score descending and take top N
        results.sort((a, b) => b.score - a.score);
        resolve({ ok: true, value: results.slice(0, limit) });
      });
    });
  }

  async findBestModel(queryEmbedding: Float32Array): Promise<Result<string[]>> {
    return new Promise((resolve) => {
      if (!this.db) return resolve({ ok: false, error: new Error('DB not init') });

      this.db.all('SELECT * FROM model_capabilities', [], (err, rows: Array<Record<string, unknown>>) => {
        if (err) return resolve({ ok: false, error: err });

        // Simple cosine similarity scan
        const scored = rows.map(r => {
          const embeddingBuffer = r['embedding'] as Buffer;
          const embedding = new Float32Array(embeddingBuffer.buffer);
          return {
            id: r['id'] as string,
            score: this.cosineSimilarity(queryEmbedding, embedding)
          };
        });

        scored.sort((a, b) => b.score - a.score);
        resolve({ ok: true, value: scored.slice(0, 3).map(s => s.id) });
      });
    });
  }

  private async ensureSchema(): Promise<void> {
    if (!this.db) return;

    return new Promise((resolve) => {
      this.db!.all("PRAGMA table_info(lessons)", async (err, _rows: Array<Record<string, unknown>>) => {
        if (err) {
          logger.error({ err }, 'Failed to check schema');
          resolve();
          return;
        }

        const columns = _rows.map(r => r['name'] as string);
        const migrations: string[] = [];

        if (!columns.includes('projectId')) {
          migrations.push("ALTER TABLE lessons ADD COLUMN projectId TEXT NOT NULL DEFAULT 'global'");
        }
        if (!columns.includes('sessionId')) {
          migrations.push("ALTER TABLE lessons ADD COLUMN sessionId TEXT");
        }

        if (migrations.length === 0) {
          resolve();
          return;
        }

        logger.info({ count: migrations.length }, 'Applying database migrations');

        try {
          // Execute migrations sequentially within the serialize block (or outside with high-fidelity locks)
          for (const sql of migrations) {
            await new Promise<void>((mRes, mRej) => {
              this.db!.run(sql, (mErr) => {
                if (mErr) {
                  logger.error({ sql, mErr }, 'Migration failed');
                  mRej(mErr);
                } else {
                  mRes();
                }
              });
            });
          }

          // Ensure indexes are also awaited
          await new Promise<void>((iRes) => {
            this.db!.run("CREATE INDEX IF NOT EXISTS idx_lessons_project ON lessons(projectId)", () => iRes());
          });
          await new Promise<void>((iRes) => {
            this.db!.run("CREATE INDEX IF NOT EXISTS idx_lessons_session ON lessons(sessionId)", () => iRes());
          });

          resolve();
        } catch (migErr) {
          logger.error({ migErr }, 'Migration sequence failed');
          resolve(); // Still proceed but log error
        }
      });
    });
  }

  private async createTables(): Promise<void> {
    if (!this.db) throw new Error('Database not initialized');

    return new Promise((resolve, reject) => {
      this.db!.serialize(() => {
        // Create initial table
        this.db!.run(`
          CREATE TABLE IF NOT EXISTS lessons (
            id TEXT PRIMARY KEY,
            text TEXT NOT NULL,
            embedding BLOB,
            sessionId TEXT,
            projectId TEXT NOT NULL DEFAULT 'global',
            errorType TEXT,
            createdAt INTEGER NOT NULL,
            regretLikelihood REAL DEFAULT 0,
            metadata TEXT
          )
        `, (err) => { if (err) reject(err); });

        // Create hexagram_context table
        this.db!.run(`CREATE TABLE IF NOT EXISTS hexagram_context (
            line_index INTEGER NOT NULL,
            projectId TEXT NOT NULL,
            title TEXT NOT NULL,
            content TEXT NOT NULL,
            state INTEGER NOT NULL DEFAULT 2,
            updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            PRIMARY KEY (line_index, projectId)
        )`, (err) => { if (err) reject(err); });

        // Create gutenberg_chunks table for RAG
        this.db!.run(`CREATE TABLE IF NOT EXISTS gutenberg_chunks (
            id TEXT PRIMARY KEY,
            book_id INTEGER NOT NULL,
            chunk_index INTEGER NOT NULL,
            content TEXT NOT NULL,
            embedding BLOB NOT NULL,
            metadata TEXT
        )`, (err) => {
          if (err) reject(err);
          else resolve();
        });
      });
    });
  }

  async addLesson(lesson: Lesson & { projectId: string }): Promise<Result<void>> {
    return new Promise((resolve) => {
      if (!this.db) {
        resolve({ ok: false, error: new Error('Database not initialized') });
        return;
      }

      const query = `
        INSERT OR REPLACE INTO lessons (id, text, embedding, sessionId, projectId, errorType, createdAt, regretLikelihood, metadata)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      `;

      const params = [
        lesson.id,
        lesson.text,
        Buffer.from(lesson.embedding.buffer),
        lesson.sessionId,
        lesson.projectId,
        lesson.errorType,
        lesson.createdAt,
        lesson.regretLikelihood || 0,
        lesson.metadata ? JSON.stringify(lesson.metadata) : null
      ];

      this.db.run(query, params, (err) => {
        if (err) {
          logger.error({ err }, 'Failed to add lesson');
          resolve({ ok: false, error: err });
        } else {
          logger.debug({ lessonId: lesson.id }, 'Lesson added');
          resolve({ ok: true, value: undefined });
        }
      });
    });
  }

  /**
   * Search for similar lessons using cosine similarity
   * Note: This fetches recent lessons and computes similarity in JS
   * Suitable for local use with < 10,000 lessons
   */
  async getHexagramContext(projectId: string): Promise<Result<Record<string, unknown>[]>> {
    return new Promise((resolve) => {
      if (!this.db) {
        resolve({ ok: false, error: new Error('Database not initialized') });
        return;
      }

      this.db.all('SELECT * FROM hexagram_context WHERE projectId = ? ORDER BY line_index ASC', [projectId], (err, rows) => {
        if (err) return resolve({ ok: false, error: err });
        else resolve({ ok: true, value: rows as Record<string, unknown>[] });
      });
    });
  }

  async updateHexagramLine(lineIndex: number, projectId: string, title: string, content: string, state: number): Promise<Result<void>> {
    return new Promise((resolve) => {
      if (!this.db) {
        resolve({ ok: false, error: new Error('Database not initialized') });
        return;
      }

      const query = `
        INSERT OR REPLACE INTO hexagram_context (line_index, projectId, title, content, state, updated_at)
        VALUES (?, ?, ?, ?, ?, CURRENT_TIMESTAMP)
      `;

      this.db.run(query, [lineIndex, projectId, title, content, state], (err) => {
        if (err) return resolve({ ok: false, error: err });
        else resolve({ ok: true, value: undefined });
      });
    });
  }

  async searchSimilar(queryEmbedding: Float32Array, limit = 5, currentProjectId?: string): Promise<Result<Lesson[]>> {
    return new Promise((resolve) => {
      if (!this.db) {
        resolve({ ok: false, error: new Error('Database not initialized') });
        return;
      }

      // Fetch last 1000 lessons to compare
      this.db.all('SELECT * FROM lessons ORDER BY createdAt DESC LIMIT 1000', [], (err, rows: Array<Record<string, unknown>>) => {
        if (err) {
          resolve({ ok: false, error: err });
          return;
        }

        const lessons = rows.map(row => {
          const embeddingBuffer = row['embedding'] as Buffer;
          const embedding = new Float32Array(
            embeddingBuffer.buffer,
            embeddingBuffer.byteOffset,
            embeddingBuffer.byteLength / 4
          );

          let similarity = this.cosineSimilarity(queryEmbedding, embedding);

          // Apply boost if it's the current project
          if (currentProjectId && row['projectId'] === currentProjectId) {
            similarity += 0.1;
          }

          return {
            ...row,
            embedding,
            projectId: row['projectId'] as string,
            similarity,
            metadata: JSON.parse(row['metadata'] as string) as Record<string, unknown>
          } as Lesson & { similarity: number };
        });

        // Sort by similarity and return top K
        const sorted = lessons
          .sort((a, b) => b.similarity - a.similarity)
          .slice(0, limit)
          .map(({ similarity: _, ...lesson }) => lesson as Lesson);

        resolve({ ok: true, value: sorted });
      });
    });
  }

  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    // Safety check
    const len = Math.min(a.length, b.length);

    for (let i = 0; i < len; i++) {
      dotProduct += (a[i] ?? 0) * (b[i] ?? 0);
      normA += (a[i] ?? 0) * (a[i] ?? 0);
      normB += (b[i] ?? 0) * (b[i] ?? 0);
    }

    const denominator = Math.sqrt(normA) * Math.sqrt(normB);
    return denominator === 0 ? 0 : dotProduct / denominator;
  }

  async getLessonCount(): Promise<number> {
    return new Promise((resolve) => {
      if (!this.db) return resolve(0);
      this.db.get('SELECT COUNT(*) as count FROM lessons', (err, row: Record<string, unknown>) => {
        if (err) resolve(0);
        else resolve((row?.['count'] as number) || 0);
      });
    });
  }

  async close(): Promise<void> {
    return new Promise((resolve) => {
      if (this.db) {
        this.db.close((err) => {
          if (err) logger.error({ err }, 'Error closing database');
          resolve();
        });
      } else {
        resolve();
      }
    });
  }
}

import { BaseLimb } from '../core/BaseLimb.js';
import type { Intent, Execution, TernaryDecision } from '../core/NeuralLimb.js';
import type { Result, VibeConfig } from '../../core/models.js';
import { AIDispatcher } from '../../api/ai/Dispatcher.js';

/**
 * BioIntelligenceLimb - Analytical Bio-Intelligence
 * 
 * Migrated to ToolingSpine for standardized orchestration.
 */
export class BioIntelligenceLimb extends BaseLimb {
    readonly id = 'bio_intelligence';
    readonly type = 'analytical' as const;

    private readonly dispatcher: AIDispatcher;

    constructor(config: VibeConfig) {
        super(config);
        this.dispatcher = new AIDispatcher(config);
        this.registerBioTools();
    }

    private registerBioTools(): void {
        const tools: import('../../core/ToolingSpine.js').LimbTool[] = [
            {
                name: 'hear_acoustic_analysis',
                description: 'Analyze health-related sounds like coughs or breathing.',
                parameters: {
                    type: 'object' as const,
                    properties: {
                        prompt: { type: 'string', description: 'Clinical context or patient case to analyze' }
                    },
                    required: ['prompt'] as const
                },
                handler: async (args: Record<string, unknown>): Promise<Result<unknown>> => {
                    return this.handleBioCall('hear_acoustic_analysis', args['prompt'] as string);
                }
            },
            {
                name: 'medgemma_reasoning',
                description: 'Perform advanced medical reasoning and comprehension.',
                parameters: {
                    type: 'object' as const,
                    properties: {
                        prompt: { type: 'string', description: 'Clinical context or patient case to analyze' }
                    },
                    required: ['prompt'] as const
                },
                handler: async (args: Record<string, unknown>): Promise<Result<unknown>> => {
                    return this.handleBioCall('medgemma_reasoning', args['prompt'] as string);
                }
            },
            {
                name: 'derm_foundation_analysis',
                description: 'Analyze medical photographs of human skin for dermatological assessment.',
                parameters: {
                    type: 'object' as const,
                    properties: {
                        prompt: { type: 'string', description: 'Clinical context or patient case to analyze' }
                    },
                    required: ['prompt'] as const
                },
                handler: async (args: Record<string, unknown>): Promise<Result<unknown>> => {
                    return this.handleBioCall('derm_foundation_analysis', args['prompt'] as string);
                }
            },
            {
                name: 'pathology_analysis',
                description: 'Analyze pathology slides and H&E patches.',
                parameters: {
                    type: 'object' as const,
                    properties: {
                        prompt: { type: 'string', description: 'Clinical context or patient case to analyze' }
                    },
                    required: ['prompt'] as const
                },
                handler: async (args: Record<string, unknown>): Promise<Result<unknown>> => {
                    return this.handleBioCall('pathology_analysis', args['prompt'] as string);
                }
            }
        ];

        this.registerTools(tools);
    }

    override async canHandle(intent: Intent): Promise<TernaryDecision> {
        const prompt = intent.prompt.toLowerCase();

        // 'Yang': Specific medical substrates = optimal
        const specificSubstrates = ['hear', 'medgemma', 'path foundation', 'derm foundation'];
        if (specificSubstrates.some(s => prompt.includes(s))) return 'Yang';

        // 'YinYang': General medical keywords = maybe
        const keywords = ['medical', 'heart', 'cough', 'skin', 'pathology', 'biological', 'clinical', 'diagnosis'];
        if (keywords.some(k => prompt.includes(k))) return 'YinYang';

        // 'YinYang': Capability matches = maybe
        if (this.spine.getCapabilities().some(cap => prompt.includes(cap))) return 'YinYang';

        return 'Yin';
    }


    override async execute(intent: Intent): Promise<Result<Execution>> {
        const prompt = intent.prompt.toLowerCase();
        let capabilityId = 'medgemma_reasoning'; // Default medical reasoning

        if (prompt.includes('heart') || prompt.includes('cough') || prompt.includes('hear')) {
            capabilityId = 'hear_acoustic_analysis';
        } else if (prompt.includes('skin') || prompt.includes('derm')) {
            capabilityId = 'derm_foundation_analysis';
        } else if (prompt.includes('pathology') || prompt.includes('slide')) {
            capabilityId = 'pathology_analysis';
        }

        const result = await this.spine.handleCall(capabilityId, { prompt: intent.prompt });
        if (!result.ok) return { ok: false, error: result.error };

        const resData = result.value as Record<string, unknown>;

        return {
            ok: true,
            value: {
                output: (resData['output'] as string) || 'Bio-intelligence analysis complete.',
                data: resData['data']
            }
        };
    }

    private async handleBioCall(name: string, payload: string): Promise<Result<unknown>> {
        this.logger.info({ capabilityId: name, payload }, 'Executing bio-intelligence tool call');

        const response = await this.dispatcher.dispatch({
            capabilityId: name,
            payload
        });

        if (!response.success) {
            return { ok: false, error: new Error(response.error || `Bio intelligence tool ${name} failed`) };
        }

        return {
            ok: true,
            value: {
                output: `Bio-intelligence analysis complete via ${name}.`,
                data: response.result
            }
        };
    }
}

import { BaseLimb } from '../core/BaseLimb.js';
import { ModelInventory } from '../../core/ModelInventory.js';
import { HealthRegistry } from '../../core/HealthRegistry.js';
import { TaskClassifier } from '../../core/TaskClassifier.js';
import type { Intent, Execution } from '../core/NeuralLimb.js';
import type { Result, VibeConfig } from '../../core/models.js';
import { z } from 'zod';

/**
 * AIModelLimb - Neural Health & Smart Routing Substrate
 * 
 * Provides visibility into the global model cluster health and 
 * advises on optimal task-to-model mapping.
 */
export class AIModelLimb extends BaseLimb {
    readonly id = 'aimodel_limb';
    readonly type = 'cloud';
    private readonly registry = HealthRegistry.getInstance();

    constructor(config: VibeConfig) {
        super(config);
        this.registerTools([
            {
                name: 'model_health',
                description: 'Returns the current health status of all registered model providers (Ollama, Cloudflare, Gemini).',
                parameters: { type: 'object', properties: {} },
                handler: async () => this.getModelHealth()
            },
            {
                name: 'benchmark_models',
                description: 'Runs quick latency checks against available models to verify connectivity and performance.',
                parameters: { type: 'object', properties: {} },
                handler: async () => this.benchmarkModels()
            },
            {
                name: 'smart_route',
                description: 'Suggests the optimal model for a specific user prompt based on health and task complexity.',
                parameters: {
                    type: 'object',
                    properties: {
                        prompt: { type: 'string', description: 'The user intent/prompt' }
                    },
                    required: ['prompt']
                },
                schema: z.object({ prompt: z.string() }),
                handler: async (args: Record<string, unknown>) => this.suggestSmartRoute(args['prompt'] as string)
            }
        ]);
    }

    private async getModelHealth(): Promise<Result<Record<string, unknown>>> {
        const health = this.registry.getAllHealth();
        return { ok: true, value: health };
    }

    private async benchmarkModels(): Promise<Result<unknown[]>> {
        const models = ModelInventory.getAvailableModels();
        const results = models.map(m => ({
            name: m.name,
            available: m.health?.isAvailable || false,
            tier: m.type,
            priority: m.priority
        }));

        this.logger.info({ modelsCount: results.length }, 'Cluster benchmark complete');
        return { ok: true, value: results };
    }

    private async suggestSmartRoute(prompt: string): Promise<Result<Record<string, unknown>>> {
        const weights = TaskClassifier.analyzeProbabilities(prompt);
        const complexity = TaskClassifier.assessComplexity(prompt, weights);

        // Naive but effective heuristic for tool call advice
        let suggestion = 'local:qwen2.5-coder';
        if (complexity === 'Yang' || complexity === 'YinYang') suggestion = 'cloud:gemini-3-pro';
        else if ((weights['api-orchestration'] || 0) > 0.5) suggestion = 'edge:llama-3.1-8b';

        return {
            ok: true,
            value: {
                suggestion,
                reasoning: `Complexity [${complexity}] and weights [${JSON.stringify(weights)}] suggest this tier.`,
                metrics: { complexity, weights }
            }
        };
    }

    override async execute(intent: Intent): Promise<Result<Execution>> {
        const userIntent = this.getUserIntent(intent).toLowerCase();

        if (userIntent.includes('health') || userIntent.includes('models')) {
            const health = await this.getModelHealth();
            if (health.ok) return { ok: true, value: { output: `[CLUSTER_HEALTH]\n${JSON.stringify(health.value, null, 2)}` } };
        }

        return super.execute(intent);
    }
}

import { BaseLimb } from '../core/BaseLimb.js';
import { z } from 'zod';
import type { Intent, Execution, TernaryDecision } from '../core/NeuralLimb.js';
import type { Result, VibeConfig, ModelResponse } from '../../core/models.js';
import { CloudflareServices } from '../../services/CloudflareServices.js';

// Cloudflare AI model IDs (from official templates)
const MODELS = {
    ULTRA: '@cf/openai/gpt-oss-120b',
    HEAVY: '@cf/meta/llama-3.3-70b-instruct-fp8-fast',
    CHAT: '@cf/meta/llama-3.1-8b-instruct-fp8',
    EMBEDDING: '@cf/baai/bge-large-en-v1.5',
    WHISPER: '@cf/openai/whisper-large-v3-turbo',
    CODER: '@cf/qwen/qwen2.5-coder-32b-instruct',
    IMAGE: '@cf/stabilityai/stable-diffusion-xl-base-1.0',
    LIGHT: '@cf/meta/llama-3.2-3b-instruct'
} as const;

/**
 * CloudflareLimb - Unified Cloudflare Workers AI Capabilities
 * 
 * Migrated to ToolingSpine for standardized orchestration.
 */
export type ServiceHealthState = 'READY' | 'RATE_LIMITED' | 'CRITICAL_FAILURE';

export class CloudflareLimb extends BaseLimb {
    readonly id = 'cloudflare_ai';
    readonly type = 'cloud' as const;

    private readonly services: CloudflareServices;
    private readonly healthInterval: NodeJS.Timeout | undefined;
    private healthState: ServiceHealthState = 'READY';
    private lastBackoffUntil: number = 0;

    constructor(config: VibeConfig) {
        super(config);
        const cfConfig: { accountId: string; apiToken: string; gatewayUrl?: string } = {
            accountId: (process.env['CLOUDFLARE_ACCOUNT_ID'] || config.cloudflareAccountId || ''),
            apiToken: (process.env['CLOUDFLARE_API_TOKEN'] || config.cloudflareApiToken || '')
        };
        if (process.env['CLOUDFLARE_WORKER_URL']) {
            cfConfig.gatewayUrl = process.env['CLOUDFLARE_WORKER_URL'];
        }
        this.services = new CloudflareServices(cfConfig);

        // Register health provider
        import('../../core/HealthRegistry.js').then(m => {
            m.HealthRegistry.getInstance().registerProvider('cloudflare', () => this.getHealth());
        });

        this.registerCloudflareTools();

        // Phase 23: Periodic Spatial Telemetry
        this.healthInterval = setInterval(() => this.updateSpatialHealth(), 30000); // Pulse every 30s
    }

    /**
     * Proper Close: Ensures intervals are cleared.
     */
    public override async close(): Promise<void> {
        this.logger.info('Closing CloudflareLimb resources...');
        if (this.healthInterval) {
            clearInterval(this.healthInterval);
        }
    }

    /**
     * Report current service health and availability
     */
    public getHealth(): { state: ServiceHealthState; cooldownSeconds: number } {
        const now = Date.now();
        if (this.healthState === 'RATE_LIMITED' && now < this.lastBackoffUntil) {
            return { state: 'RATE_LIMITED', cooldownSeconds: Math.ceil((this.lastBackoffUntil - now) / 1000) };
        }

        if (this.healthState === 'RATE_LIMITED' && now >= this.lastBackoffUntil) {
            this.healthState = 'READY';
        }

        return { state: this.healthState, cooldownSeconds: 0 };
    }

    /**
     * Specialized status for Cloudflare AI monitoring
