            health: health.state,
            cooldown: health.cooldownSeconds,
            backoffUntil: this.lastBackoffUntil > 0 ? new Date(this.lastBackoffUntil).toISOString() : 'None',
            provider: 'Cloudflare Workers AI'
        };
    }

