import { EventEmitter } from 'events';
import type { NeuralLimb, Intent, Execution, TernaryDecision } from './NeuralLimb.js';
import type { Result, VibeConfig } from '../../core/models.js';
import { ToolingSpine, type LimbTool } from '../../core/ToolingSpine.js';
import type { ModelExecutor } from '../../core/ModelExecutor.js';
import pino from 'pino';

/**
 * BaseLimb - The standardized substrate for all Sovereign AI Limbs.
 * 
 * Provides automated tool registration, routing, and high-fidelity logging.
 */
export abstract class BaseLimb extends EventEmitter implements NeuralLimb {
    abstract id: string;
    abstract type: 'creative' | 'analytical' | 'maintenance' | 'memory' | 'cloud' | 'action' | 'experimental' | 'sensory' | 'metabolic' | 'psychic' | 'metaphysical' | 'system';

    // Strategic Affinity
    public preferredHexagrams: string[] = []; // e.g., '111111' (Creative)
    public avoidHexagrams: string[] = [];     // e.g., '010111' (Conflict)

    public readonly spine: ToolingSpine = new ToolingSpine();
    protected readonly logger: pino.Logger;

    constructor(
        protected readonly config: VibeConfig,
        protected readonly executor?: ModelExecutor
    ) {
        super();
        this.logger = pino({
            name: this.constructor.name,
            base: { hostname: 'POG-VIBE' }
        });
    }

    /**
     * Common capability listing based on registered tools.
     */
    get capabilities(): string[] {
        return this.spine.getCapabilities();
    }

    /**
     * Extracts the raw user intent from a potentially system-wrapped prompt.
     */
    protected getUserIntent(intent: Intent): string {
        const p = intent.prompt;
        const intentMarker = '### CURRENT USER INTENT';
        if (p.includes(intentMarker)) {
            const parts = p.split(intentMarker);
            const content = parts[1];
            if (content) {
                const subParts = content.split('### EXECUTION DIRECTIVE');
                const userPart = subParts[0];
                if (userPart) return userPart.trim();
            }
        }
        return p.trim();
    }

    /**
     * Default canHandle implementation using Semantic Sovereignty logic.
     * Returns: 'Yin' (skip), 'YinYang' (maybe), 'Yang' (optimal match)
     */
    async canHandle(intent: Intent): Promise<TernaryDecision> {
        const p = this.getUserIntent(intent).toLowerCase();

        // 'Yang': Direct limb ID match = optimal
        if (p.includes(this.id.toLowerCase())) return 'Yang';

        // Count capability matches
        const matches = this.spine.getCapabilities()
            .filter(cap => p.includes(cap.toLowerCase())).length;

        if (matches >= 2) return 'Yang';   // Strong match = escalate
        if (matches === 1) return 'YinYang'; // Partial match = balanced
        return 'Yin';                     // No match = de-escalate
    }


    /**
     * Default execute implementation: attempts a Cognitive Response if no tool is matched.
     * This acts as a "Sovereign Chat" fallback within specialized limbs.
     */
    async execute(intent: Intent): Promise<Result<Execution>> {
        if (this.executor) {
            this.logger.info('Direct execution triggered - invoking Cognitive Response fallback');
            const prompt = `You are a specialized limb of POG-CODER-VIBE.
ID: ${this.id}
TYPE: ${this.type}
CAPABILITIES: ${this.capabilities.join(', ')}

The user has triggered this limb with an intent that didn't map to a specific formal tool call.
Use your specialized context to provide a brilliant, straight-up response or guidance.

User Intent: ${this.getUserIntent(intent)}`;

            const response = await this.executor.callModel('gemini:gemini-2.0-flash', prompt);
            if (response.ok) {
                return {
                    ok: true,
                    value: {
                        output: `[Sovereign Cognitive Response - ${this.id}]\n${response.value.response}`,
                        data: { source: this.id, cognitive: true }
                    }
                };
            }
        }

        return {
            ok: false,
            error: new Error(`Limb [${this.id}] requires formal tool calls. Use getTools() to see options.`)
        };
    }

    /**
     * Exposes formal tool declarations to the Supervisor.
     */
    getTools(): import('./NeuralLimb.js').ToolDeclaration[] {
        return this.spine.getGeminiDeclarations() as import('./NeuralLimb.js').ToolDeclaration[];
    }

    /**
     * Standardized tool call handling via the Spine.
     */
    async handleToolCall(name: string, args: Record<string, unknown>): Promise<Result<Execution>> {
        this.logger.debug({ tool: name, args }, 'Routing tool call through Spine');
        const res = await this.spine.handleCall(name, args);
        if (!res.ok) return res;

        const val = res.value;
        // High-fidelity mapping of spine results to Execution substrate
        if (val && typeof val === 'object' && 'output' in val) {
            return { ok: true, value: val as Execution };
        }
        return {
            ok: true,
            value: {
                output: typeof val === 'string' ? val : JSON.stringify(val, null, 2),
                data: val
            }
        };
    }

    /**
     * Get detailed diagnostic/contextual status of the limb.
     */
    public getStatus(): Record<string, unknown> {
        const tools = this.getTools();
        const flatTools = tools.flatMap(t => t.functionDeclarations);

        return {
            id: this.id,
            type: this.type,
            capabilities: this.capabilities,
            toolCount: flatTools.length,
            tools: flatTools.map(t => ({
                name: t.name,
                description: t.description
            }))
        };
    }

    /**
     * Assigns a ModelExecutor for cognitive fallbacks.
     */
    public setExecutor(executor: ModelExecutor): void {
        (this as unknown as { executor?: ModelExecutor }).executor = executor;
    }

    /**
     * Helper to register tools locally in the derived constructor.
     */
    protected registerTools(tools: LimbTool[]): void {
        this.spine.registerTools(tools);
    }

    /**
     * Emits a "Memory Pulse" for Hexagram Line 2.
     * All limbs utilize this to broadcast service health and activity.
     */
    protected async pinPulse(state: import('../../core/HexagramManager.js').YaoState, detail: string): Promise<void> {
        this.spine.emitPulse(state, detail, this.id);
        this.logger.info({ state, detail }, 'Limb Pulse Emitted');
    }

    /**
     * Get detailed diagnostic/contextual status of the limb
     */
    public getStatus(): Record<string, unknown> {
        return {
            id: this.id,
            type: this.type,
            capabilities: this.capabilities,
            preferredHexagrams: this.preferredHexagrams,
            avoidHexagrams: this.avoidHexagrams
        };
    }

    /**
     * Optional: Perform resource cleanup (close DBs, kill processes, etc.)
     */
    public async close(): Promise<void> {
        // Default implementation does nothing
    }
}

import { BaseLimb } from './BaseLimb.js';
import { Result, VibeConfig } from '../../core/models.js';
import { SOVEREIGN_COMPONENTS } from '../webapp/SovereignLibrary.js';

/**
 * CognitionLimb - The Sovereign Inline Intelligence.
 * 
 * Replaces cloud-based "ghost text" with high-fidelity local prediction.
 * Leverages the Sovereign Library as a few-shot context to ensure
 * generated code is always "on brand" and architecturally aligned.
 */
import { ModelExecutor } from '../../core/ModelExecutor.js';

export class CognitionLimb extends BaseLimb {
    id = 'cognition';
    type = 'analytical' as const;

    constructor(config: VibeConfig, executor?: ModelExecutor) {
        super(config, executor);
        this.registerCognitionTools();
    }

    private registerCognitionTools(): void {
        this.registerTools([
            {
                name: 'predict_inline',
                description: 'Generate high-speed inline code completion based on cursor context and Sovereign patterns.',
                parameters: {
                    type: 'object',
                    properties: {
                        fileContent: { type: 'string', description: 'The full content of the file being edited' },
                        cursorOffset: { type: 'number', description: 'The character offset of the cursor' },
                        contextLines: { type: 'number', description: 'Number of lines of context to consider (default: 50)' }
                    },
                    required: ['fileContent', 'cursorOffset']
                },
                handler: async (args) => {
                    return this.handlePredictInline(args);
                }
            }
        ]);
    }

    private async handlePredictInline(args: any): Promise<Result<string>> {
        const { fileContent, cursorOffset, contextLines = 50 } = args;

        if (!this.executor) {
            return { ok: false, error: new Error('CognitionLimb requires an active executor for prediction.') };
        }

        // 1. Slice Context
        const beforeCursor = fileContent.slice(0, cursorOffset);
        const afterCursor = fileContent.slice(cursorOffset);

        // Take last N lines before cursor for urgency
        const linesBefore = beforeCursor.split('\n');
        const contextBefore = linesBefore.slice(-contextLines).join('\n');

        // 2. Identify Sovereign Context
        // Check if we are inside a component that resembles a Sovereign Pattern
        const knownPatterns = Object.keys(SOVEREIGN_COMPONENTS).join(', ');

        // 3. Construct Prompt (Optimized for Speed)
        const prompt = `ROLE: Sovereign Inline Engine (Latency <200ms)
CONTEXT: POG-CODER-VIBE Substrate
AVAILABLE PATTERNS: ${knownPatterns}

TASK: Complete the code at the [CURSOR] position.
RULES:
1. Output ONLY the code completion. No markdown, no conversation.
2. Match the indentation and style of the context exactly.
3. If the user is starting a Sovereign Pattern (e.g., "Hero"), auto-complete with high fidelity from the Library.

CODE BEFORE CURSOR:
${contextBefore}
[CURSOR]
CODE AFTER CURSOR:
${afterCursor.slice(0, 500)} // Lookahead for context

COMPLETION:`;

        // 4. Execute Prediction
        // We use the monitor model (tinyllama or similar fast model) if available, 
        // otherwise default to the configured fast model.
        // For now, we rely on the executor's default routing, but ideally this should be a "flash" route.
        const model = this.config.monitorModel || 'qwen2.5-coder:7b';

        const result = await this.executor.callModel(model, prompt);

        if (!result.ok) {
            this.logger.warn({ error: result.error }, 'Inline prediction failed');
            return { ok: false, error: result.error };
        }

        // 5. Sanitize Output
        // Remove any thinking or markdown wrappers if the model hallucinated them
        let code = result.value.response;
        code = code.replace(/```tsx?/g, '').replace(/```/g, '');

        // Remove "COMPLETION:" label if present (sometimes models leak it)
        code = code.replace(/^COMPLETION:\s*/i, '');

        return {
            ok: true,
            value: code
        };
    }
}

import { BaseLimb } from './BaseLimb.js';
import { z } from 'zod';
import { Type } from '@google/genai';
import type { VibeConfig, Result } from '../../core/models.js';
import type { FreeModelRouter } from '../../core/Router.js';

/**
 * ControlPlaneLimb - The "Executive Function" of the POG system.
 * 
 * Houses the internal orchestration tools previously hardcoded in Orchestrator.ts.
 * Standardized via the Tooling Spine.
 */
export class ControlPlaneLimb extends BaseLimb {
    readonly id = 'control_plane';
    readonly type = 'analytical';

    constructor(
        config: VibeConfig,
        private readonly router: FreeModelRouter, // Fixed: Explicit typing instead of 'any'
    ) {
        super(config);
        this.registerControlTools();
    }

    private registerControlTools(): void {
        this.registerTools([
            {
                name: 'plan_tool_execution',
                description: 'Decomposes a task into a sequence of actionable steps with tool mappings.',
                parameters: {
                    type: 'object',
                    properties: {
                        goal: { type: 'string', description: 'The final objective.' },
                        steps: {
                            type: 'array',
                            items: {
                                type: 'object',
                                properties: {
                                    tool: { type: 'string', enum: ['Sandbox', 'GitManager', 'WebAppForge', 'Wrangler', 'gcloud', 'FileSystem'] },
                                    args: { type: 'array', items: { type: 'string' } },
                                    reasoning: { type: 'string' },
                                    rollback: { type: 'string', description: 'Command to run if this step fails.' }
                                },
                                required: ['tool', 'args', 'reasoning']
                            }
                        }
                    },
                    required: ['goal', 'steps']
                },
                schema: z.object({
                    goal: z.string(),
                    steps: z.array(z.object({
                        tool: z.enum(['Sandbox', 'GitManager', 'WebAppForge', 'Wrangler', 'gcloud', 'FileSystem']),
                        args: z.array(z.string()),
                        reasoning: z.string(),
                        rollback: z.string().optional()
                    }))
                }),
                handler: async (args: Record<string, unknown>): Promise<Result<{ status: string }>> => {
                    const steps = (args['steps'] as unknown[]) || [];
                    this.logger.info({ goal: args['goal'] as string, stepCount: steps.length }, 'Plan documented in Control Plane');
                    return { ok: true, value: { status: 'plan_recorded' } };
                }
            },
            {
                name: 'route_model',
                description: 'Selects the optimal model for a specific task type and context.',
                parameters: {
                    type: 'object',
                    properties: {
                        taskType: { type: 'string', enum: ['architecture', 'syntax', 'refactor', 'debug', 'generate'] },
                        contextSize: { type: 'number', description: 'Estimated token count.' },
                        requiresCloud: { type: 'boolean' },
                        reason: { type: 'string', description: 'The reasoning or prompt context that requires routing.' }
                    },
                    required: ['taskType', 'reason']
                },
                schema: z.object({
                    taskType: z.enum(['architecture', 'syntax', 'refactor', 'debug', 'generate']),
                    contextSize: z.number().optional(),
                    requiresCloud: z.boolean().optional(),
                    reason: z.string()
                }),
                handler: async (args: Record<string, unknown>): Promise<Result<{ selectedModel: string; reason: string }>> => {
                    this.logger.info({ reason: args['reason'] as string }, 'Dynamic routing coordination');
                    // Fixed: Explicit coordination through the router instance
                    const routeResult = await this.router.route(args['reason'] as string);
                    return {
                        ok: true,
                        value: {
                            selectedModel: routeResult.ok ? routeResult.value : 'fallback',
                            reason: args['reason'] as string
                        }
                    };
                }
            },
            {
                name: 'evaluate_result',
                description: 'Analyzes execution output to determine success and identify lessons.',
                parameters: {
                    type: 'object',
                    properties: {
                        success: { type: 'boolean' },
                        errorType: { type: 'string', description: 'Categorized error (e.g., Timeout, Syntax, Permission).' },
                        diff: { type: 'string', description: 'Unified diff of changes made.' },
                        lessons: {
                            type: 'array',
                            items: { type: Type.STRING }
                        },
                        regretLikelihood: { type: 'number', minimum: 0, maximum: 1 }
                    },
                    required: ['success', 'lessons', 'regretLikelihood']
                },
                schema: z.object({
                    success: z.boolean(),
                    errorType: z.string().optional(),
                    diff: z.string().optional(),
                    lessons: z.array(z.string()),
                    regretLikelihood: z.number().min(0).max(1)
                }),
                handler: async (args: Record<string, unknown>): Promise<Result<{ auditId: string }>> => {
                    this.logger.info({ success: args['success'] }, 'Result evaluation recorded');
                    return { ok: true, value: { auditId: `AUDIT_${Date.now()}` } };
                }
            },
            {
                name: 'manage_durable_memory',
                description: 'Manages persistent state and assets (Vector snapshots, artifacts) on GCS.',
                parameters: {
                    type: 'object',
                    properties: {
                        intent: {
                            type: 'string',
                            enum: [
                                'store_vector_snapshot',
                                'fetch_execution_artifact',
                                'commit_model_output',
                                'load_router_checkpoint',
                                'archival_cleanup'
                            ]
                        },
                        payload_uri: { type: 'string' },
                        metadata: { type: 'object' }
                    },
                    required: ['intent', 'payload_uri']
                },
                schema: z.object({
                    intent: z.enum([
                        'store_vector_snapshot',
                        'fetch_execution_artifact',
                        'commit_model_output',
                        'load_router_checkpoint',
                        'archival_cleanup'
                    ]),
                    payload_uri: z.string(),
                    metadata: z.record(z.unknown()).optional() // Fixed: Using unknown instead of any
                }),
                handler: async (args: Record<string, unknown>): Promise<Result<{ status: string; uri: string }>> => {
                    this.logger.info({ intent: args['intent'] as string, uri: args['payload_uri'] as string }, 'Durable memory operation');
                    return { ok: true, value: { status: 'operation_queued', uri: args['payload_uri'] as string } };
                }
            },
            {
                name: 'emit_execution_manifest',
                description: 'Records a complete audit log of a cognitive intent to GCS.',
                parameters: {
                    type: 'object',
                    properties: {
                        intentId: { type: 'string' },
                        routingDecision: { type: 'object' },
                        toolChain: {
                            type: 'array',
                            items: { type: 'string' }
                        },
                        artifactPointers: {
                            type: 'array',
                            items: { type: 'string' }
                        },
                        lessonDerived: { type: 'boolean' }
                    },
                    required: ['intentId', 'routingDecision', 'toolChain']
                },
                schema: z.object({
                    intentId: z.string(),
                    routingDecision: z.record(z.unknown()), // Fixed: Using unknown
                    toolChain: z.array(z.string()),
                    artifactPointers: z.array(z.string()).optional(),
                    lessonDerived: z.boolean().optional()
                }),
                handler: async (args: Record<string, unknown>): Promise<Result<{ manifestUri: string }>> => {
                    this.logger.info({ intentId: args['intentId'] }, 'Emitting execution manifest');
                    return { ok: true, value: { manifestUri: `gs://pog-audit/manifests/${Date.now()}.json` } };
                }
            },
            {
                name: 'cloud_shell_cognitive_assist',
                description: 'Leverages Gemini in Cloud Shell for terminal-aware code generation or debugging.',
                parameters: {
                    type: 'object',
                    properties: {
                        intent: {
                            type: 'string',
                            enum: ['explain_terminal_error', 'generate_infra_script', 'debug_context']
                        },
                        terminal_context: { type: 'string' },
                        proposed_action: { type: 'string' }
                    },
                    required: ['intent', 'terminal_context']
                },
                schema: z.object({
                    intent: z.enum(['explain_terminal_error', 'generate_infra_script', 'debug_context']),
                    terminal_context: z.string(),
                    proposed_action: z.string().optional()
                }),
                handler: async (args: Record<string, unknown>): Promise<Result<{ status: string; advice: string }>> => {
                    this.logger.info({ intent: args['intent'] }, 'Cloud Shell cognitive assist requested');
                    return { ok: true, value: { status: 'assist_provided', advice: 'Review terminal history for context.' } };
                }
            },
            {
                name: 'manage_event_triggers',
                description: 'Configures and manages event-driven triggers for cross-surface orchestration.',
                parameters: {
                    type: 'object',
                    properties: {
                        action: { type: 'string', enum: ['create', 'delete', 'list'] },
                        triggerId: { type: 'string' },
                        source: {
                            type: 'object',
                            properties: {
                                provider: { type: 'string', enum: ['storage.googleapis.com', 'pubsub.googleapis.com'] },
                                event: { type: Type.STRING, description: 'e.g., google.cloud.storage.object.v1.finalized' }
                            }
                        },
                        destination: {
                            type: 'object',
                            properties: {
                                type: { type: 'string', enum: ['cloud_function', 'cloud_run', 'workflow'] },
                                uri: { type: Type.STRING }
                            }
                        }
                    },
                    required: ['action', 'triggerId']
                },
                schema: z.object({
                    action: z.enum(['create', 'delete', 'list']),
                    triggerId: z.string(),
                    source: z.object({
                        provider: z.enum(['storage.googleapis.com', 'pubsub.googleapis.com']),
                        event: z.string()
                    }).optional(),
                    destination: z.object({
                        type: z.enum(['cloud_function', 'cloud_run', 'workflow']),
                        uri: z.string()
                    }).optional()
                }),
                handler: async (args: Record<string, unknown>): Promise<Result<{ status: string; triggerId: string }>> => {
                    this.logger.info({ action: args['action'] as string, triggerId: args['triggerId'] as string }, 'Event trigger management');
                    return { ok: true, value: { status: 'trigger_configured', triggerId: args['triggerId'] as string } };
                }
            }
        ]);
    }

    override async canHandle(intent: import('../core/NeuralLimb.js').Intent): Promise<import('../core/NeuralLimb.js').TernaryDecision> {
        const p = intent.prompt.toLowerCase();

        // 'Yang': Direct mention of control plane = optimal
        if (p.includes('control plane') || p.includes('orchestrator logs')) return 'Yang';

        // 'YinYang': Capability matches = maybe
        if (this.spine.getCapabilities().some(cap => p.includes(cap))) return 'YinYang';

        return 'Yin';
    }
}

import { BaseLimb } from './BaseLimb.js';
import { z } from 'zod';
import { VibeConfig } from '../../core/models.js';
import { Sandbox } from '../../sandbox/Sandbox.js';
import * as fs from 'fs';
import { join, relative } from 'path';
import { SmartEdit } from '../../core/SmartEdit.js';
import { readManyFiles } from '../../utils/ReadManyFiles.js';

/**
 * FileSystemLimb - Atomic file operations for Sovereign AI
 * 
 * Migrated to ToolingSpine for standardized orchestration.
 */
export class FileSystemLimb extends BaseLimb {
    readonly id = 'filesystem';
    readonly type = 'maintenance' as const;

    constructor(
        config: VibeConfig,
        private readonly sandbox: Sandbox
    ) {
        super(config);
        this.registerFileSystemTools();
    }

    private registerFileSystemTools(): void {
        this.registerTools([
            {
                name: 'read_file',
                description: 'Read the contents of a file from the project root.',
                parameters: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Relative path to the file.' }
                    },
                    required: ['path']
                },
                schema: z.object({
                    path: z.string().describe('Relative path to the file.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const filePath = args['path'] as string;
                    const absPath = join(this.config.projectRoot, filePath);
                    if (!fs.existsSync(absPath)) throw new Error(`File not found: ${filePath}`);
                    return { ok: true, value: fs.readFileSync(absPath, 'utf8') };
                }
            },
            {
                name: 'read_many_files',
                description: 'Read multiple files in a single turn. Optimization for batch processing.',
                parameters: {
                    type: 'object',
                    properties: {
                        paths: { type: 'array', items: { type: 'string' }, description: 'Array of relative file paths.' }
                    },
                    required: ['paths']
                },
                schema: z.object({
                    paths: z.array(z.string()).describe('Array of relative file paths.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const paths = (args['paths'] as string[]) || [];
                    const absPaths = paths.map((p: string) => join(this.config.projectRoot, p));
                    return await readManyFiles(absPaths);
                }
            },
            {
                name: 'write_file',
                description: 'Overwrite a file with new content. Automatically creates a sandbox snapshot.',
                parameters: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Relative path to the file.' },
                        content: { type: 'string', description: 'The new content of the file.' }
                    },
                    required: ['path', 'content']
                },
                schema: z.object({
                    path: z.string().describe('Relative path to the file.'),
                    content: z.string().describe('The new content of the file.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const filePath = args['path'] as string;
                    const content = args['content'] as string;
                    const absPath = join(this.config.projectRoot, filePath);
                    const snapshot = await this.sandbox.createSnapshot(`write_file: ${filePath}`);
                    fs.writeFileSync(absPath, content);
                    return { ok: true, value: { status: 'persisted', snapshotId: snapshot.ok ? snapshot.value : 'none' } };
                }
            },
            {
                name: 'patch_file',
                description: 'Replace a specific block of text in a file.',
                parameters: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Relative path to the file.' },
                        search: { type: 'string', description: 'The exact string to search for.' },
                        replace: { type: 'string', description: 'The string to replace it with.' }
                    },
                    required: ['path', 'search', 'replace']
                },
                schema: z.object({
                    path: z.string().describe('Relative path to the file.'),
                    search: z.string().describe('The exact string to search for.'),
                    replace: z.string().describe('The string to replace it with.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const filePath = args['path'] as string;
                    const absPath = join(this.config.projectRoot, filePath);
                    if (!fs.existsSync(absPath)) throw new Error(`File not found: ${filePath}`);

                    const content = fs.readFileSync(absPath, 'utf8');
                    const editResult = await SmartEdit.calculateReplacement(content, {
                        file_path: absPath,
                        old_string: args['search'] as string,
                        new_string: args['replace'] as string
                    });

                    if (editResult.occurrences === 0) {
                        throw new Error(`Patch failed: Search string not found in file (Strategies: Exact|Flexible|Regex failed).`);
                    }

                    await this.sandbox.createSnapshot(`patch_file: ${filePath} (Strategy: ${editResult.strategy})`);
                    const finalContent = SmartEdit.restoreTrailingNewline(content, editResult.newContent);
                    fs.writeFileSync(absPath, finalContent);

                    return { ok: true, value: { status: 'patched', strategy: editResult.strategy, occurrences: editResult.occurrences } };
                }
            },
            {
                name: 'smart_edit',
                description: 'Advanced file editing with multiple matching strategies (Exact, Flexible, Regex). Use for complex refactors where indentation might vary.',
                parameters: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Relative path to the file.' },
                        old_string: { type: 'string', description: 'The text block to replace.' },
                        new_string: { type: 'string', description: 'The new text block.' },
                        instruction: { type: 'string', description: 'Instruction for the edit (used for self-correction logs).' }
                    },
                    required: ['path', 'old_string', 'new_string']
                },
                schema: z.object({
                    path: z.string().describe('Relative path to the file.'),
                    old_string: z.string().describe('The text block to replace.'),
                    new_string: z.string().describe('The new text block.'),
                    instruction: z.string().optional().describe('Instruction for the edit.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const filePath = args['path'] as string;
                    const absPath = join(this.config.projectRoot, filePath);
                    if (!fs.existsSync(absPath)) throw new Error(`File not found: ${filePath}`);

                    const content = fs.readFileSync(absPath, 'utf8');
                    const result = await SmartEdit.calculateReplacement(content, {
                        file_path: absPath,
                        old_string: args['old_string'] as string,
                        new_string: args['new_string'] as string
                    });

                    if (result.occurrences === 0) {
                        return { ok: false, error: new Error('SmartEdit failed to find matching content for provided old_string.') };
                    }

                    await this.sandbox.createSnapshot(`smart_edit: ${filePath}`);
                    const finalContent = SmartEdit.restoreTrailingNewline(content, result.newContent);
                    fs.writeFileSync(absPath, finalContent);

                    return { ok: true, value: { status: 'edited', strategy: result.strategy, occurrences: result.occurrences } };
                }
            },
            {
                name: 'list_files',
                description: 'List files in a directory recursively.',
                parameters: {
                    type: 'object',
                    properties: {
                        dir: { type: 'string', description: 'Relative directory path (defaults to root).' }
                    }
                },
                schema: z.object({
                    dir: z.string().optional().describe('Relative directory path (defaults to root).')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const dirPath = (args['dir'] as string) || '';
                    const dir = join(this.config.projectRoot, dirPath);
                    const files = this.walk(dir).map(f => relative(this.config.projectRoot, f));
                    return { ok: true, value: files };
                }
            },
            {
                name: 'create_directory',
                description: 'Create a new directory recursively within the project root.',
                parameters: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Relative directory path to create.' }
                    },
                    required: ['path']
                },
                schema: z.object({
                    path: z.string().describe('Relative directory path to create.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const path = args['path'] as string;
                    const absPath = join(this.config.projectRoot, path);
                    if (fs.existsSync(absPath)) return { ok: true, value: { status: 'exists' } };
                    fs.mkdirSync(absPath, { recursive: true });
                    return { ok: true, value: { status: 'created', path: path } };
                }
            },
            {
                name: 'delete_file',
                description: 'Safe removal of a file within the project root. Checks existence first.',
                parameters: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Relative path to the file to delete.' }
                    },
                    required: ['path']
                },
                schema: z.object({
                    path: z.string().describe('Relative path to the file to delete.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const filePath = args['path'] as string;
                    const absPath = join(this.config.projectRoot, filePath);
                    if (!fs.existsSync(absPath)) throw new Error(`File not found: ${filePath}`);
                    fs.unlinkSync(absPath);
                    return { ok: true, value: { status: 'deleted', path: filePath } };
                }
            },
            {
                name: 'move_file',
                description: 'Atomic move or rename of a file or directory.',
                parameters: {
                    type: 'object',
                    properties: {
                        source: { type: 'string', description: 'Relative source path.' },
                        destination: { type: 'string', description: 'Relative destination path.' }
                    },
                    required: ['source', 'destination']
                },
                schema: z.object({
                    source: z.string().describe('Relative source path.'),
                    destination: z.string().describe('Relative destination path.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const source = args['source'] as string;
                    const destination = args['destination'] as string;
                    const srcAbs = join(this.config.projectRoot, source);
                    const dstAbs = join(this.config.projectRoot, destination);
                    if (!fs.existsSync(srcAbs)) throw new Error(`Source not found: ${source}`);
                    fs.renameSync(srcAbs, dstAbs);
                    return { ok: true, value: { status: 'moved', from: source, to: destination } };
                }
            },
            {
                name: 'rollback_snapshot',
                description: 'Rollback the project state to a previous snapshot (Ollama Review Mode).',
                parameters: {
                    type: 'object',
                    properties: {
                        snapshotId: { type: 'string', description: 'The ID of the snapshot to restore.' }
                    },
                    required: ['snapshotId']
                },
                schema: z.object({
                    snapshotId: z.string().describe('The ID of the snapshot to restore.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const snapshotId = args['snapshotId'] as string;
                    const rbResult = await this.sandbox.rollback(snapshotId);
                    if (!rbResult.ok) throw rbResult.error;
                    return { ok: true, value: { status: 'rolled_back', snapshotId: snapshotId } };
                }
            },
            {
                name: 'generate_pog_manifest',
                description: 'Generate a pog.md manifest for a directory to explain its purpose and contents.',
                parameters: {
                    type: 'object',
                    properties: {
                        path: { type: 'string', description: 'Relative path to the directory.' }
                    },
                    required: ['path']
                },
                schema: z.object({
                    path: z.string().describe('Relative path to the directory.')
                }),
                handler: async (args: Record<string, unknown>) => {
                    const dirPath = args['path'] as string;
                    const absPath = join(this.config.projectRoot, dirPath);
                    if (!fs.existsSync(absPath) || !fs.statSync(absPath).isDirectory()) {
                        throw new Error(`Directory not found: ${dirPath}`);
                    }
                    const dirFiles = fs.readdirSync(absPath);
                    const manifestContent = `# 📁 Pog Manifest: ${dirPath}\n\nThis folder contains specialized code for the POG-VIBE system.\n\n## 📄 File Inventory\n\n${dirFiles.map(f => `- **${f}**: [Pending AI Description]`).join('\n')}\n\n---\n\n*Generated by POG-VIBE Project Portability Engine.*`;
                    const manifestPath = join(absPath, 'pog.md');
                    fs.writeFileSync(manifestPath, manifestContent);
                    return { ok: true, value: { status: 'manifest_generated', path: relative(this.config.projectRoot, manifestPath) } };
                }
            }
        ]);
    }

    private walk(dir: string): string[] {
        let results: string[] = [];
        const list = fs.readdirSync(dir);
        for (let file of list) {
            if (file === 'node_modules' || file === '.git' || file === 'dist' || file === '.pog') continue;
            file = join(dir, file);
            const stat = fs.statSync(file);
            if (stat && stat.isDirectory()) {
                results = results.concat(this.walk(file));
            } else {
                results.push(file);
            }
        }
        return results;
    }
}

