    override getStatus(): Record<string, any> {
        const books = this.loadMetadataCache();
        return {
            id: this.id,
            type: this.type,
            capabilities: this.spine.getCapabilities(),
            totalBooks: books.length,
            libraryPath: this.GUTENBERG_CACHE
        };
    }

    override async canHandle(intent: Intent): Promise<TernaryDecision> {
        const userIntent = this.getUserIntent(intent).toLowerCase();

        // 'Yang': Explicit gutenberg/literature keywords = optimal
        const keywords = ['gutenberg', 'literature', 'author style', 'ingest book'];
        if (keywords.some(k => userIntent.includes(k))) return 'Yang';

        // 'YinYang': General book/corpus keywords = maybe
        if (userIntent.includes('book') || userIntent.includes('corpus') || userIntent.includes('download')) return 'YinYang';

        // 'YinYang': Capability matches = maybe
        if (this.spine.getCapabilities().some(cap => userIntent.includes(cap))) return 'YinYang';

        return 'Yin';
    }


    override async execute(intent: Intent): Promise<Result<Execution>> {
        const userIntent = this.getUserIntent(intent).toLowerCase();

        // Determine action and route through spine
        if (userIntent.includes('search') || userIntent.includes('find') || userIntent.includes('retrieve') || userIntent.includes('get') || userIntent.includes('fetch')) {
            const params = this.parseSearchParams(userIntent);
            const result = await this.spine.handleCall<Execution>('gutenberg_search', params as unknown as Record<string, unknown>);
            if (result.ok) return result;
            return { ok: false, error: result.error };
        } else if (userIntent.includes('ingest') || userIntent.includes('download')) {
            const params = this.parseSearchParams(userIntent);
            const result = await this.spine.handleCall<Execution>('gutenberg_ingest', params as unknown as Record<string, unknown>);
            if (result.ok) return result;
            return { ok: false, error: result.error };
        } else if (userIntent.includes('styles') || userIntent.includes('authors')) {
            const result = await this.spine.handleCall<Execution>('gutenberg_styles', {});
            if (result.ok) return result;
            return { ok: false, error: result.error };
        }

        // Fallback to Sovereign Cognitive Response instead of failing
        return super.execute(intent);
    }

    private async handleListStyles(): Promise<Result<Execution>> {
        const metadata = this.loadMetadataCache();
        const authors = new Set<string>();
        const domains = new Set<string>();

        for (const book of metadata) {
            if (book.domain) domains.add(book.domain);
            if (book.author) authors.add(book.author);
        }

        return {
            ok: true,
            value: {
                output: `Available styles:\nDomains: ${Array.from(domains).join(', ')}\nAuthors: ${Array.from(authors).join(', ')}`,
                data: { domains: Array.from(domains), authors: Array.from(authors) }
            }
        };
    }

    private parseSearchParams(prompt: string): GutenbergSearchRequest {
        const params: GutenbergSearchRequest = {};

        // Extract domains
        const domainMatch = prompt.match(/domains?[:\s]+([a-z,\s]+)/i);
        if (domainMatch && domainMatch[1]) {
            params.domains = domainMatch[1].split(',').map(d => d.trim());
        }

        // Extract authors
        const authorMatch = prompt.match(/authors?[:\s]+([^,\n]+)/i);
        if (authorMatch && authorMatch[1]) {
            params.authors = authorMatch[1].split(',').map(a => a.trim());
        }

        // Extract search terms
        const searchMatch = prompt.match(/search[:\s]+([^\n]+)/i);
        if (searchMatch && searchMatch[1]) {
            params.search = searchMatch[1].trim();
        }

        // Extract limit
        const limitMatch = prompt.match(/limit[:\s]+(\d+)/i);
        if (limitMatch && limitMatch[1]) {
            params.limit = parseInt(limitMatch[1], 10);
        }

        return params;
    }

    private async searchBooks(params: GutenbergSearchRequest): Promise<BookMetadata[]> {
        let query = `${this.GUTENDEX_API}?languages=en`;

        // Build query based on params
        if (params.domains) {
            const keywords = params.domains.flatMap(d => GUTENBERG_DOMAINS[d as keyof typeof GUTENBERG_DOMAINS] || []);
            query += `&search=${keywords.join(' ')}`;
        }

        if (params.authors) {
            query += `&search=${params.authors.join(' ')}`;
        }

        if (params.search) {
            query += `&search=${encodeURIComponent(params.search)}`;
        }

        await this.respectRateLimit();

        const response = await fetch(query);
        if (!response.ok) {
            throw new Error(`Gutendex API error: ${response.statusText}`);
        }

        const data = await response.json() as { results: BookMetadata[] };
        let books = data.results;

        // Apply limit
        if (params.limit) {
            books = books.slice(0, params.limit);
        }

        return books;
    }

    private async ingestBooks(books: BookMetadata[]): Promise<IngestionReport> {
        const results = { total: books.length, success: 0, failed: 0, domains: [] as string[], cacheSizeMB: 0 };

        for (const book of books) {
            try {
                await this.downloadAndCache(book);
                results.success++;
            } catch (error) {
                this.logger.error({ bookId: book.id, error }, 'Failed to ingest book');
                results.failed++;
            }
        }

        results.cacheSizeMB = await this.getCacheSize();
        return results;
    }

    private async downloadAndCache(book: BookMetadata): Promise<void> {
        // Find plain text URL
        const textUrl = book.formats['text/plain; charset=utf-8'] ||
            book.formats['text/plain'] ||
            `https://www.gutenberg.org/files/${book.id}/${book.id}-0.txt`;

        await this.respectRateLimit();

        const response = await fetch(textUrl);
        if (!response.ok) {
            throw new Error(`Failed to download book ${book.id}: ${response.statusText}`);
        }

        const text = await response.text();

        // Infer domain with content awareness
        const domain = this.inferDomain(book, text);

        // Standardize naming: Title_Author_ID.txt
        const sanitizedTitle = book.title.replace(/[^a-z0-9]/gi, '_').replace(/_+/g, '_').slice(0, 50);
        const authorName = book.authors[0]?.name || 'Unknown';
        const sanitizedAuthor = authorName.replace(/[^a-z0-9]/gi, '_').replace(/_+/g, '_').slice(0, 30);
        const fileName = `${sanitizedTitle}_${sanitizedAuthor}_${book.id}.txt`;
        const cachePath = join(this.GUTENBERG_CACHE, 'domains', domain, fileName);

        // Skip if already cached (checking both path and ID in metadata)
        const metadata = this.loadMetadataCache();
        if (metadata.some(m => m.id === book.id && existsSync(m.path))) {
            this.logger.debug({ bookId: book.id }, 'Book already cached');
            return;
        }

        // Cache locally
        mkdirSync(join(this.GUTENBERG_CACHE, 'domains', domain), { recursive: true });
        writeFileSync(cachePath, text);

        // Update metadata cache
        this.updateMetadataCache({
            id: book.id,
            title: book.title,
            author: authorName,
            domain,
            path: cachePath
        });

        this.logger.info({ bookId: book.id, domain, title: book.title, fileName }, 'Book cached with descriptive naming');


        // Integrating Learning Mechanism with Style Analysis
        if (this.vectorDB && typeof this.vectorDB.addLesson === 'function') {
            try {
                const styleProfile = StyleAnalyzer.analyze(text);

                // Generate embedding if Gemini service is available
                let embedding = new Float32Array(0);
                if (this.gemini) {
                    // Truncate text for embedding if too long (Gemini limits)
                    const textForEmbedding = text.slice(0, 10000);
                    const embedResult = await this.gemini.embed(textForEmbedding);
                    if (embedResult.ok) {
                        embedding = new Float32Array(embedResult.value);
                    }
                }

                await this.vectorDB.addLesson({
                    id: `gutenberg-${book.id}`,
                    text: text,
                    embedding: embedding,
                    sessionId: 'gutenberg-ingestion',
                    projectId: 'global',
                    errorType: '',
                    createdAt: Date.now(),
                    metadata: {
                        source: `gutenberg:${book.id}`,
                        category: domain,
                        styleProfile // Inject style data
                    }
                });
                this.logger.info({ bookId: book.id, style: styleProfile }, 'Book ingested with style profile and embedding');
            } catch (err) {
                this.logger.error({ err, bookId: book.id }, 'Failed to index book into VectorDB');
            }
        }
    }

    private inferDomain(book: BookMetadata, content?: string): string {
        const metadataText = `${book.title} ${book.subjects.join(' ')}`.toLowerCase();

        // 1. Keyword Taxonomy Match
        for (const [domain, keywords] of Object.entries(GUTENBERG_DOMAINS)) {
            if (keywords.some(kw => metadataText.includes(kw))) {
                return domain;
            }
        }

        // 2. Content-Aware Fallback
        if (content) {
            const head = content.slice(0, 2000).toLowerCase();
            if (head.includes('chapter i') || head.includes('contents') || head.includes('preface')) {
                return 'literature'; // Likely a novel or structured literary work
            }
            if (head.includes('theorem') || head.includes('q.e.d') || head.includes('equation')) {
                return 'mathematics';
            }
            if (head.includes('experiment') || head.includes('observation') || head.includes('data')) {
                return 'science';
            }
        }

        return 'uncategorized';
    }

    private async respectRateLimit(): Promise<void> {
        const now = Date.now();
        const timeSinceLastRequest = now - this.lastRequestTime;

        if (timeSinceLastRequest < this.RATE_LIMIT_MS) {
            await new Promise(resolve => setTimeout(resolve, this.RATE_LIMIT_MS - timeSinceLastRequest));
        }

        this.lastRequestTime = Date.now();
    }

    // ============================================================
    // RAG PIPELINE IMPLEMENTATION
    // ============================================================

    /**
     * Ingests a book into the vector database for RAG.
     */
    private async ingestBookIntoMemory(bookId: number): Promise<Result<void>> {
        if (!this.vectorDB || !this.gemini) {
            return { ok: false, error: new Error('VectorDB or GeminiService not available') };
        }

        const books = this.loadMetadataCache();
        const book = books.find(b => b.id === bookId);
        if (!book) return { ok: false, error: new Error(`Book ${bookId} not found in local library`) };

        try {
            this.logger.info({ bookId, title: book.title }, 'Starting RAG ingestion...');

            // 1. Read Content
            // Try explicit path first, then fallback to cache pattern
            let contentPath = book.path;
            if (!contentPath || !existsSync(contentPath)) {
                contentPath = join(this.GUTENBERG_CACHE, `top_100_${bookId}.txt`);
            }

            if (!existsSync(contentPath)) {
                return { ok: false, error: new Error(`Content file not found for book ${bookId}`) };
            }

            const content = readFileSync(contentPath, 'utf8');

            // 2. Chunk Content (Sliding Window)
            const chunks = this.chunkText(content, 1000, 100);
            this.logger.info({ chunks: chunks.length }, 'Content chunked');

            // 3. Generate Embeddings (Batch Process)
            const storedChunks = [];
            for (let i = 0; i < chunks.length; i++) {
                const chunkText = chunks[i];
                if (!chunkText) continue;

                // Generate embedding using Gemini
                const embeddingResult = await this.gemini.embed(chunkText);

                if (embeddingResult.ok && embeddingResult.value) {
                    storedChunks.push({
                        id: `${bookId}_${i}`,
                        bookId: bookId,
                        chunkIndex: i,
                        content: chunkText,
                        embedding: new Float32Array(embeddingResult.value),
                        metadata: { title: book.title, author: book.author }
                    });
                }

                // Rate limit protection
                if (i % 10 === 0) await new Promise(r => setTimeout(r, 200));
            }

            // 4. Store in VectorDB
            await this.vectorDB.storeGutenbergChunks(storedChunks);

            this.logger.info({ bookId, count: storedChunks.length }, 'RAG ingestion complete');
            return { ok: true, value: undefined };

        } catch (error) {
            this.logger.error({ error, bookId }, 'RAG ingestion failed');
            return { ok: false, error: error as Error };
        }
    }

    /**
     * Retrieves semantic context from the literary memory.
     */
    private async retrieveLiteraryContext(query: string, limit: number = 5): Promise<Result<string[]>> {
        if (!this.vectorDB || !this.gemini) {
            return { ok: false, error: new Error('VectorDB or GeminiService not available') };
        }

        try {
            // 1. Embed Query
            const queryEmbedding = await this.gemini.embed(query);
            if (!queryEmbedding.ok || !queryEmbedding.value) {
                return { ok: false, error: new Error('Failed to generate query embedding') };
            }

            // 2. Vector Search
            const results = await this.vectorDB.searchGutenberg(new Float32Array(queryEmbedding.value), limit);

            if (!results.ok) return { ok: false, error: results.error };

            // 3. Format Output
            const context = results.value.map((r: any) =>
                `[Source: ${r.metadata.title} by ${r.metadata.author}]\n${r.content}`
            );

            return { ok: true, value: context };

        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    /**
     * Sliding window text chunking.
     */
    private chunkText(text: string, windowSize: number, overlap: number): string[] {
        const words = text.split(/\s+/);
        const chunks = [];
        let index = 0;

        while (index < words.length) {
            const chunk = words.slice(index, index + windowSize).join(' ');
            chunks.push(chunk);
            index += (windowSize - overlap);
        }

        return chunks;
    }

    private loadMetadataCache(): Array<{ id: number; title: string; author: string; domain: string; path: string }> {
        const metadataPath = join(this.GUTENBERG_CACHE, 'metadata.json');
        if (!existsSync(metadataPath)) {
            return [];
        }

        try {
            return JSON.parse(readFileSync(metadataPath, 'utf8'));
        } catch {
            return [];
        }
    }

    private updateMetadataCache(entry: { id: number; title: string; author: string; domain: string; path: string }): void {
        const metadata = this.loadMetadataCache();
        metadata.push(entry);

        const metadataPath = join(this.GUTENBERG_CACHE, 'metadata.json');
        writeFileSync(metadataPath, JSON.stringify(metadata, null, 2));
    }

    private async getCacheSize(): Promise<number> {
        // Simplified: just return 0 for now, can implement proper size calculation later
        return 0;
    }
}

import { BaseLimb } from '../core/BaseLimb.js';
import { z } from 'zod';
import { VibeConfig, ModelAbility as MA } from '../../core/models.js';
import { ModelExecutor } from '../../core/ModelExecutor.js';
import { FreeModelRouter } from '../../core/Router.js';
import { YaoState } from '../../core/HexagramManager.js';

/**
 * MediaForgeLimb - Generative Media Intelligence for Sovereign AI
 * 
 * Migrated to ToolingSpine for standardized orchestration.
 */
export class MediaForgeLimb extends BaseLimb {
    id = 'media_forge';
    type = 'creative' as const;

    constructor(
        config: VibeConfig,
        private readonly modelExecutor: ModelExecutor,
        private readonly router: FreeModelRouter
    ) {
        super(config);
        this.registerMediaTools();
    }

    private registerMediaTools(): void {
        this.registerTools([
            {
                name: 'media_forge_request',
                description: 'Generate images, videos, or audio using specialized neural forges.',
                parameters: {
                    type: 'object',
                    properties: {
                        prompt: { type: 'string', description: 'Detailed visual or auditory description' },
                        targetType: { type: 'string', enum: ['image', 'speech', 'vision', 'model'], description: 'Type of media to forge' }
                    },
                    required: ['prompt', 'targetType']
                },
                schema: z.object({
                    prompt: z.string(),
                    targetType: z.enum(['image', 'speech', 'vision', 'model'])
                }),
                handler: async (args: Record<string, unknown>) => {
                    let ability: MA;
                    const target = (args['targetType'] as string).toLowerCase();

                    if (target === 'vision') ability = MA.Vision;
                    else if (target === 'speech') ability = MA.TTS;
                    else if (target === 'model') ability = 'RSMV' as MA;
                    else ability = MA.ImageGen;

                    this.logger.info({ ability, prompt: (args['prompt'] as string).substring(0, 50) + '...' }, 'Routing media task by ability');
                    const model = this.router.routeByAbility(ability);
                    const result = await this.modelExecutor.callCloudflareAI(model, { prompt: args['prompt'] as string });

                    if (!result.ok) {
                        await this.pinPulse(YaoState.OldYin, `Media Forge Fail: ${target}`);
                        return result;
                    }

                    await this.pinPulse(YaoState.OldYang, `Media Forged: ${target}`);
                    return {
                        ok: true,
                        value: {
                            output: `Successfully forged ${target} media using professional ${ability} tools.`,
                            data: result.value
                        }
                    };
                }
            }
        ]);
    }


    // Override canHandle for backward compatibility and broad detection
    override async canHandle(intent: import('../core/NeuralLimb.js').Intent): Promise<import('../core/NeuralLimb.js').TernaryDecision> {
        if (!this.config.enabledServices.includes('MEDIA_FORGE')) return 'Yin';

        const prompt = intent.prompt.toLowerCase();

        // 'Yang': Explicit creative keywords = optimal
        const highEscalation = ['forge', 'rsmv', 'model', 'visual'];
        if (highEscalation.some(k => prompt.includes(k))) return 'Yang';

        // 'YinYang': General media keywords = maybe
        const keywords = ['generate', 'create', 'image', 'video', 'music', 'sound', 'audio'];
        if (keywords.some(k => prompt.includes(k))) return 'YinYang';

        return 'Yin';
    }

}

import { BaseLimb } from '../core/BaseLimb.js';
import type { Intent, Execution } from '../core/NeuralLimb.js';
import type { Result, VibeConfig } from '../../core/models.js';
import { z } from 'zod';

export interface EntityDefinition {
    id: string;
    type: string;
    position: { x: number; y: number; z: number };
    scale: { x: number; y: number; z: number };
    metadata: Record<string, any>;
}

/**
 * EntityLimb - 3D Scene Management Substrate
 * 
 * Manages the "Bubble World" entity registry and serialization.
 * This is the logic layer for Three.js-powered visualizations.
 */
export class EntityLimb extends BaseLimb {
    readonly id = 'entity_limb';
    readonly type = 'creative';
    private readonly entities: Map<string, EntityDefinition> = new Map();

    constructor(config: VibeConfig) {
        super(config);
        this.registerTools([
            {
                name: 'create_entity',
                description: 'Creates or updates a 3D entity in the current scene context.',
                parameters: {
                    type: 'object',
                    properties: {
                        id: { type: 'string', description: 'Unique identifier' },
                        entityType: { type: 'string', description: 'Type of entity (e.g., cube, model, light)' },
                        position: { type: 'array', items: { type: 'number' }, minItems: 3, maxItems: 3 }
                    },
                    required: ['id', 'entityType']
                },
                schema: z.object({
                    id: z.string(),
                    entityType: z.string(),
                    position: z.array(z.number()).length(3).optional()
                }),
                handler: async (args) => this.createEntity(args)
            },
            {
                name: 'serialize_scene',
                description: 'Returns the current scene as a JSON object for rendering.',
                parameters: { type: 'object', properties: {} },
                handler: async () => this.serializeScene()
            },
            {
                name: 'clear_scene',
                description: 'Removes all entities from the current scene.',
                parameters: { type: 'object', properties: {} },
                handler: async () => {
                    this.entities.clear();
                    return { ok: true, value: 'Scene cleared' };
                }
            }
        ]);
    }

    private async createEntity(args: any): Promise<Result<EntityDefinition>> {
        const entity: EntityDefinition = {
            id: args['id'],
            type: args['entityType'],
            position: { x: args['position']?.[0] || 0, y: args['position']?.[1] || 0, z: args['position']?.[2] || 0 },
            scale: { x: 1, y: 1, z: 1 },
            metadata: {}
        };

        this.entities.set(args['id'], entity);
        this.logger.info({ entityId: args['id'] }, 'Entity manifested in scene');
        return { ok: true, value: entity };
    }

    private async serializeScene(): Promise<Result<string>> {
        const scene = Array.from(this.entities.values());
        return { ok: true, value: JSON.stringify(scene, null, 2) };
    }

    override async execute(intent: Intent): Promise<Result<Execution>> {
        const p = intent.prompt.toLowerCase();

        if (p.includes('scene') || p.includes('render') || p.includes('3d')) {
            const scene = await this.spine.handleCall('serialize_scene', {});
            if (scene.ok) return { ok: true, value: { output: `[SCENE_MANIFEST]\n${JSON.stringify(scene.value, null, 2)}` } };
        }

        return super.execute(intent);
    }
}

import { BaseLimb } from '../core/BaseLimb.js';
import type { Intent, Execution } from '../core/NeuralLimb.js';
import type { Result, VibeConfig } from '../../core/models.js';
import { StateManager } from '../../core/StateManager.js';
import { execSync } from 'child_process';
import { existsSync, mkdirSync, writeFileSync } from 'fs';
import { join } from 'path';
import { z } from 'zod';

/**
 * FileLimb - Advanced File System Substrate
 * 
 * Provides Git, NPM, and Scaffolding capabilities to the Sovereign Supervisor.
 */
export class FileLimb extends BaseLimb {
    readonly id = 'file_limb';
    readonly type = 'maintenance';
    private readonly state = StateManager.getInstance();

    constructor(config: VibeConfig) {
        super(config);
        this.registerTools([
            {
                name: 'git_status',
                description: 'Checks the current Git status of the project root.',
                parameters: { type: 'object', properties: {} },
                handler: async () => this.gitStatus()
            },
            {
                name: 'git_commit',
                description: 'Adds all changes and commits them with a message.',
                parameters: {
                    type: 'object',
                    properties: {
                        message: { type: 'string', description: 'The commit message' }
                    },
                    required: ['message']
                },
                schema: z.object({ message: z.string() }),
                handler: async (args: Record<string, unknown>) => this.gitCommit(args['message'] as string)
            },
            {
                name: 'npm_install',
                description: 'Installs dependencies in the current project root.',
                parameters: {
                    type: 'object',
                    properties: {
                        packages: { type: 'array', items: { type: 'string' }, description: 'Optional list of packages' },
                        saveDev: { type: 'boolean', description: 'Install as dev dependency' }
                    }
                },
                schema: z.object({ packages: z.array(z.string()).optional(), saveDev: z.boolean().optional() }),
                handler: async (args: Record<string, unknown>) => this.npmInstall(args['packages'] as string[], args['saveDev'] as boolean)
            },
            {
                name: 'git_push',
                description: 'Push committed changes to the remote branch (Ternary Orchestration).',
                parameters: { type: 'object', properties: {} },
                handler: async () => this.gitPush()
            },
            {
                name: 'git_pull',
                description: 'Pull and merge changes from the remote branch.',
                parameters: { type: 'object', properties: {} },
                handler: async () => this.gitPull()
            },
            {
                name: 'template_scaffold',
                description: 'Scaffolds a new project component or sub-service based on ultimate templates.',
                parameters: {
                    type: 'object',
                    properties: {
                        name: { type: 'string', description: 'The name of the new directory' },
                        type: { type: 'string', enum: ['worker', 'component', 'minimal'], description: 'The template type' }
                    },
                    required: ['name', 'type']
                },
                schema: z.object({ name: z.string(), type: z.enum(['worker', 'component', 'minimal']) }),
                handler: async (args: Record<string, unknown>) => this.scaffold(args['name'] as string, args['type'] as 'worker' | 'component' | 'minimal')
            }
        ]);
    }

    private async gitStatus(): Promise<Result<string>> {
        try {
            const output = execSync('git status --short', { cwd: this.config.projectRoot, encoding: 'utf-8' });
            return { ok: true, value: output || 'Clean' };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    private async gitCommit(message: string): Promise<Result<string>> {
        try {
            execSync('git add .', {
                cwd: this.config.projectRoot
            });
            const output = execSync(`git commit -m "[Sovereign] ${message}"`, { cwd: this.config.projectRoot, encoding: 'utf-8' });
            this.state.updateMetrics({ turnCount: 1 });
            return { ok: true, value: output };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    private async npmInstall(packages?: string[], saveDev?: boolean): Promise<Result<string>> {
        try {
            const cmd = `npm install ${packages?.join(' ') || ''} ${saveDev ? '--save-dev' : ''}`;
            const output = execSync(cmd, { cwd: this.config.projectRoot, encoding: 'utf-8' });
            return { ok: true, value: output };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    private async scaffold(name: string, type: 'worker' | 'component' | 'minimal'): Promise<Result<string>> {
        const targetDir = join(this.config.projectRoot, name);
        if (existsSync(targetDir)) return { ok: false, error: new Error(`Directory ${name} already exists`) };

        try {
            mkdirSync(targetDir, { recursive: true });

            if (type === 'worker') {
                writeFileSync(join(targetDir, 'package.json'), JSON.stringify({ name, version: '1.0.0', type: 'module' }, null, 2));
                writeFileSync(join(targetDir, 'wrangler.toml'), `name = "${name}"\nmain = "src/index.ts"\ncompatibility_date = "2025-10-11"`);
                mkdirSync(join(targetDir, 'src'));
                writeFileSync(join(targetDir, 'src/index.ts'), `export default { async fetch() { return new Response("Hello from ${name}"); } };`);
            } else if (type === 'minimal') {
                writeFileSync(join(targetDir, 'index.js'), `console.log("Sovereign Minimal [${name}] Active");`);
            }

            return { ok: true, value: `Scaffolded ${type} project in ${name}` };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    private async gitPush(): Promise<Result<string>> {
        try {
            const output = execSync('git push', { cwd: this.config.projectRoot, encoding: 'utf-8' });
            return { ok: true, value: output || 'Pushed successfully' };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    private async gitPull(): Promise<Result<string>> {
        try {
            const output = execSync('git pull', { cwd: this.config.projectRoot, encoding: 'utf-8' });
            return { ok: true, value: output || 'Pulled successfully' };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    override async execute(intent: Intent): Promise<Result<Execution>> {
        const p = intent.prompt.toLowerCase();

        if (p.includes('status') || p.includes('git')) {
            const matchedCap = this.spine.getCapabilities().find(cap => p.includes(cap));
            if (matchedCap) {
                return (this.spine as unknown as { handleCall: (name: string, args: Record<string, unknown>) => Promise<Result<Execution>> }).handleCall(matchedCap, {});
            }
        }

        return super.execute(intent);
    }
}

import { z } from 'zod';
import { BaseLimb } from '../core/BaseLimb.js';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { type Result, type VibeConfig } from '../../core/models.js';
import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import type { Intent, TernaryDecision } from '../core/NeuralLimb.js';

interface MCPServerConfig {
    command: string;
    args: string[];
    env?: Record<string, string>;
}

interface MCPContent {
    type: string;
    text?: string;
    data?: unknown;
}

/**
 * MCPLimb - High-Fidelity Universal Model Context Protocol Substrate.
 * 
 * Leverages the official @modelcontextprotocol/sdk for real, non-mocked
 * integration with any standard MCP server.
 */
export class MCPLimb extends BaseLimb {
    readonly id = 'mcp_extension';
    readonly type = 'action';
    private readonly clients: Map<string, Client> = new Map();

    constructor(config: VibeConfig) {
        super(config);
        this.registerMcpTools();
        this.initializeServers();
    }

    private registerMcpTools(): void {
        this.registerTools([
            {
                name: 'connect_mcp_server',
                description: 'Manually bridge a new MCP server via stdio.',
                parameters: {
                    type: 'object',
                    properties: {
                        name: { type: 'string', description: 'Neural link name.' },
                        command: { type: 'string', description: 'Binary command.' },
                        args: { type: 'array', items: { type: 'string' }, description: 'Args.' }
                    },
                    required: ['name', 'command']
                },
                schema: z.object({
                    name: z.string(),
                    command: z.string(),
                    args: z.array(z.string()).optional()
                }),
                handler: async (args: Record<string, unknown>) => {
                    await this.connectToServer(args['name'] as string, {
                        command: args['command'] as string,
                        args: args['args'] as string[] || []
                    });
                    return { ok: true, value: { status: 'synchronized' } };
                }
            }
        ]);
    }

    private initializeServers(): void {
        const configPath = join(this.config.projectRoot, 'pog-mcp.json');
        if (!existsSync(configPath)) {
            this.logger.info('No pog-mcp.json found. Substrate limited to native organs.');
            return;
        }

        try {
            const mcpConfig = JSON.parse(readFileSync(configPath, 'utf8'));
            const servers = mcpConfig.mcpServers || {};

            for (const [name, config] of Object.entries(servers)) {
                void this.connectToServer(name, config as MCPServerConfig);
            }
        } catch (e) {
            this.logger.error({ error: (e as Error).message }, 'Failed to parse pog-mcp.json');
        }
    }

    private async connectToServer(name: string, config: MCPServerConfig): Promise<void> {
        this.logger.info({ server: name, command: config.command }, '🔌 Engaging MCP Neural Link...');

        try {
            const transport = new StdioClientTransport({
                command: config.command,
                args: config.args,
                env: { ...process.env, ...config.env } as Record<string, string>
            });

            // Using explicit casting for Client options to bypass SDK version strictness
            const client = new Client(
                {
                    name: "pog-coder-vibe",
                    version: "1.0.0"
                },
                {
                    capabilities: {
                        tools: {}
                    }
                } as any
            );

            await client.connect(transport);
            this.clients.set(name, client);

            // 1. Discover Tools (Safe Discovery)
            try {
                const toolsRes = await client.listTools();
                const tools = toolsRes.tools || [];

                const formattedTools = tools.map((t) => ({
                    name: `mcp_${name}_${t.name}`,
                    description: `[MCP:${name}] ${t.description}`,
                    parameters: t.inputSchema as { type: 'object'; properties: Record<string, unknown>; required?: string[] },
                    handler: async (args: Record<string, unknown>): Promise<Result<unknown>> => {
                        try {
                            const result = await client.callTool({
                                name: t.name,
                                arguments: args
                            });

                            if (result.isError) {
                                const errorText = (result.content as MCPContent[]).map((c) => c.text || JSON.stringify(c)).join('\n');
                                return { ok: false, error: new Error(errorText) };
                            }

                            const output = (result.content as MCPContent[]).map((c) => c.text || JSON.stringify(c)).join('\n') || 'Success';
                            return { ok: true, value: output };
                        } catch (err) {
                            return { ok: false, error: err as Error };
                        }
                    }
                }));

                this.registerTools(formattedTools);
                this.logger.info({ server: name, tools: tools.length }, '✅ MCP Tools Bonded');
            } catch (err) {
                this.logger.debug({ server: name, error: (err as Error).message }, 'MCP: Server does not support tools discovery');
            }

            // 2. Discover Resources (Fidelity Upgrade - Optional)
            try {
                const resourcesRes = await client.listResources();
                if (resourcesRes.resources.length > 0) {
                    this.logger.info({ server: name, count: resourcesRes.resources.length }, '📚 MCP Resources Bonded');
                }
            } catch (err) {
                this.logger.debug({ server: name, error: (err as Error).message }, 'MCP: Server does not support resources discovery');
            }

            this.logger.info({ server: name }, '✅ MCP Neural Link Synchronized');

        } catch (err) {
            this.logger.error({ server: name, error: (err as Error).message }, '❌ MCP Neural Link Failure');
        }
    }

    /**
     * Standard canHandle using Ternary logic.
     * Escalates only when MCP-specific tools or the server IDs are mentioned.
     */
    override async canHandle(intent: Intent): Promise<TernaryDecision> {
        const p = this.getUserIntent(intent).toLowerCase();

        // Check if any active server name is mentioned
        for (const name of this.clients.keys()) {
            if (p.includes(name.toLowerCase())) return 'Yang';
        }

        // Standard de-escalation for general queries
        return super.canHandle(intent);
    }

    /**
     * Proper Close: Ensures all MCP Neural Links are cleanly severed.
     */
    public override async close(): Promise<void> {
        this.logger.info({ connections: this.clients.size }, 'Severing MCP Neural Links...');
        for (const [name, client] of this.clients.entries()) {
            try {
                await client.close();
                this.logger.debug({ server: name }, 'Neural link offline');
            } catch (e) {
                this.logger.error({ server: name, error: (e as Error).message }, 'Failed to close neural link');
            }
        }
        this.clients.clear();
    }

    /**
     * Diagnostic hook for Dashboard
     */
    override getStatus(): Record<string, unknown> {
        const status = super.getStatus();
        return {
            ...status,
            activeConnections: this.clients.size,
            servers: Array.from(this.clients.keys())
        };
    }
}

import { execSync } from 'child_process';
import { BaseLimb } from '../core/BaseLimb.js';
import { z } from 'zod';
import type { Result, VibeConfig } from '../../core/models.js';
import { HealthRegistry } from '../../core/HealthRegistry.js';

/**
 * SovereignShellLimb - Robust terminal-based fallback layer.
 * 
 * Provides CLI-level access to Gemini, GCloud, and Cloudflare tools
 * as a redundancy path for programmatic API failures.
 */
export class SovereignShellLimb extends BaseLimb {
    id = 'sovereign-shell';
    type = 'maintenance' as const;

    constructor(config: VibeConfig) {
        super(config);
        this.registerSovereignTools();

        // Register health provider with the central registry
        HealthRegistry.getInstance().registerProvider(this.id, () => this.getHealth());
    }

    private getHealth() {
        // Simple verification for the presence of global binaries
        const bins = ['gemini', 'gcloud', 'wrangler', 'ssh'];
        let availableCount = 0;
        const metadata: Record<string, boolean> = {};

        for (const bin of bins) {
            try {
                // Use 'where' on Windows to locate binary
                execSync(`where ${bin}`, { stdio: 'ignore' });
                availableCount++;
                metadata[bin] = true;
            } catch {
                metadata[bin] = false;
            }
        }

        return {
            state: (availableCount > 0 ? 'READY' : 'CRITICAL_FAILURE') as 'READY' | 'CRITICAL_FAILURE',
            cooldownSeconds: 0,
            metadata
        };
    }

    private registerSovereignTools() {
        this.registerTools([
            {
                name: 'gemini_cli_exec',
                description: 'Execute global gemini CLI code editor command for high-fidelity fallback edits.',
                parameters: {
                    type: 'object',
                    properties: {
                        args: { type: 'string', description: 'Arguments for the gemini command (e.g., "apply --file ...")' }
                    },
                    required: ['args']
                },
                schema: z.object({ args: z.string() }),
                handler: async (args: Record<string, unknown>) => this.runCommand(`gemini ${args['args'] as string}`)
            },
            {
                name: 'gcloud_global_exec',
                description: 'Execute gcloud -g global command for Cloud resource management.',
                parameters: {
                    type: 'object',
                    properties: {
                        args: { type: 'string', description: 'Arguments for gcloud -g' }
                    },
                    required: ['args']
                },
                schema: z.object({ args: z.string() }),
                handler: async (args: Record<string, unknown>) => this.runCommand(`gcloud -g ${args['args'] as string}`)
            },
            {
                name: 'wrangler_global_exec',
                description: 'Execute wrangler -g global command for Cloudflare Worker/Static site orchestration.',
                parameters: {
                    type: 'object',
                    properties: {
                        args: { type: 'string', description: 'Arguments for wrangler -g' }
                    },
                    required: ['args']
                },
                schema: z.object({ args: z.string() }),
                handler: async (args: Record<string, unknown>) => this.runCommand(`wrangler -g ${args['args'] as string}`)
            },
            {
                name: 'github_ssh_exec',
                description: 'Execute ssh github -g global command for secure repository operations.',
                parameters: {
                    type: 'object',
                    properties: {
                        args: { type: 'string', description: 'Arguments for ssh github -g' }
                    },
                    required: ['args']
                },
                schema: z.object({ args: z.string() }),
                handler: async (args: Record<string, unknown>) => this.runCommand(`ssh github -g ${args['args'] as string}`)
            }
        ]);
    }

    private async runCommand(command: string): Promise<Result<string>> {
        try {
            this.logger.info({ command }, 'Executing Sovereign Shell Fallback');
            // Using synchronous execution for simplicity in fallback mode, 
            // but wrapped in an async handler for Spine compatibility.
            const output = execSync(command, { encoding: 'utf8' });
            return { ok: true, value: output };
        } catch (error: unknown) {
            const err = error as { message: string; stdout?: string; stderr?: string };
            this.logger.error({ command, error: err.message }, 'Sovereign Shell Execution Failed');
            return { ok: false, error: new Error(err.stdout || err.stderr || err.message) };
        }
    }
}

import { BaseLimb } from '../core/BaseLimb.js';
import { z } from 'zod';
import { type VibeConfig } from '../../core/models.js';
import { GoogleServices } from '../../services/GoogleServices.js';
import { CloudflareServices } from '../../services/CloudflareServices.js';
import { TaskClassifier } from '../../core/TaskClassifier.js';

/**
 * SubstrateLimb - Unified Sensory & Utility Substrate.
 * 
 * Aggregates GCloud Sensory APIs (Vision, NL, Translation) and 
 * Cloudflare Edge-Utility tools to minimize high-tier LLM consumption.
 */
export class SubstrateLimb extends BaseLimb {
    id = 'substrate_utility';
    type = 'analytical' as const;

    constructor(
        config: VibeConfig,
        private readonly google: GoogleServices,
        private readonly cloudflare: CloudflareServices
    ) {
        super(config);
        this.registerSubstrateTools();
    }

    private registerSubstrateTools() {
        this.registerTools([
            {
                name: 'visual_ocr_analysis',
                description: 'Extract text and labels from an image using high-speed Vision AI. Saves multimodal LLM tokens.',
                parameters: {
                    type: 'object',
                    properties: {
                        imageBase64: { type: 'string', description: 'Base64 encoded image data' }
                    },
                    required: ['imageBase64']
                },
                schema: z.object({ imageBase64: z.string() }),
                handler: async (args: any) => {
                    const buffer = Buffer.from(args['imageBase64'], 'base64');
                    return this.google.analyzeImage(buffer);
                }
            },
            {
                name: 'fast_translation',
                description: 'Translate text rapidly using dedicated Translation API. More cost-effective than LLM translation.',
                parameters: {
                    type: 'object',
                    properties: {
                        text: { type: 'string', description: 'Text to translate' },
                        target: { type: 'string', description: 'Target language code (default: en)' }
                    },
                    required: ['text']
                },
                schema: z.object({ text: z.string(), target: z.string().optional() }),
                handler: async (args: any) => this.google.translateText(args['text'], args['target'] || 'en')
            },
            {
                name: 'entity_intent_extraction',
                description: 'Extract entities and sentiment from text without using an LLM turn.',
                parameters: {
                    type: 'object',
                    properties: {
                        text: { type: 'string', description: 'Text to analyze' }
                    },
                    required: ['text']
                },
                schema: z.object({ text: z.string() }),
                handler: async (args: any) => this.google.analyzeEntities(args['text'])
            },
            {
                name: 'edge_bake_asset',
                description: 'Procedurally generate code, markup, or styles at the edge using Cloudflare Workers AI.',
                parameters: {
                    type: 'object',
                    properties: {
                        prompt: { type: 'string', description: 'Functional core for the asset' },
                        type: { type: 'string', enum: ['style', 'markup', 'logic'], description: 'Category of asset to bake' }
                    },
                    required: ['prompt', 'type']
                },
                schema: z.object({
                    prompt: z.string(),
                    type: z.enum(['style', 'markup', 'logic'])
                }),
                handler: async (args: any) => this.cloudflare.edgeBake(args['prompt'], args['type'])
            }
        ]);
    }

    /**
     * Proactively intercept a sensory task (Image/OCR/Translate) before the main turn.
     * Returns enriched context or null if no interception is needed.
     */
    async interceptSensoryTask(prompt: string, context?: any): Promise<string | null> {
        const lower = prompt.toLowerCase();
        const weights = TaskClassifier.analyzeProbabilities(prompt);

        // 1. OCR interception (Robust weight-based check)
        const isOCRIntent = (weights['esoteric'] || 0) > 0.4 || lower.includes('screenshot') || lower.includes('ocr') || lower.includes('analyze image');
        if (isOCRIntent && context?.['imageBase64']) {
            this.logger.info('Sensory Interception: Triggering proactive OCR pre-processing');
            const result = await this.google.analyzeImage(Buffer.from(context['imageBase64'], 'base64'));
            if (result.ok) {
                return `[SENSORY_DATA: OCR_RESULT]\n${JSON.stringify((result.value as any).fullTextAnnotation?.text || 'No text detected')}\n[/SENSORY_DATA]`;
            }
        }

        // 2. Translation interception (Robust extraction)
        const isTranslateIntent = lower.startsWith('translate') || lower.includes('translation of') || lower.includes('translate this');
        if (isTranslateIntent) {
            this.logger.info('Sensory Interception: Triggering proactive translation');
            // Support multiple patterns: translate "X" to Y, translation of "X" into Y
            const match = prompt.match(/(?:translate|translation of) ["']?(.*?)["']? (?:to|into) (.*)/i);
            if (match?.[1] && match?.[2]) {
                const result = await this.google.translateText(match[1], match[2]);
                if (result.ok) {
                    return `[SENSORY_DATA: TRANSLATION]\n"${match[1]}" -> "${result.value}"\n[/SENSORY_DATA]`;
                }
            }
        }

        return null;
    }
}

