const logger = pino({
    name: 'MonitorAgent',
    base: { hostname: 'POG-VIBE' }
});

export interface MonitorAgentEvents {
    issueDetected: (report: MonitorReport) => void;
    healthCheckPassed: () => void;
    provenanceCandidate: (filePath: string) => void;
    node_discovered: (data: unknown) => void;
}

export interface MonitorReport {
    readonly timestamp: number;
    readonly severity: 'low' | 'medium' | 'high' | 'critical';
    readonly category: 'tsc' | 'file-change' | 'build-failure';
    readonly description: string;
    readonly affectedFiles: string[];
    readonly suggestedAction: string;
    readonly tscErrors?: readonly TSCError[];
}

export class MonitorAgent extends EventEmitter {
    private readonly tscMonitor: TSCMonitor;
    private readonly astWatcher: ASTWatcher;
    private readonly selfHealingEngine: SelfHealingEngine;
    private isRunning: boolean = false;
    private healthCheckInterval?: NodeJS.Timeout;
    private readonly recentChanges: Set<string> = new Set();

    private readonly MONITOR_MODEL: string;
    private readonly SNAPSHOT_MODEL: string;

    constructor(
        config: VibeConfig,
        private readonly executor: ModelExecutor
    ) {
        super();
        this.MONITOR_MODEL = config.monitorModel || process.env['VIBE_MONITOR_MODEL'] || 'tinyllama:latest';
        this.SNAPSHOT_MODEL = config.snapshotModel || process.env['VIBE_SNAPSHOT_MODEL'] || 'qwen2.5-coder:7b-instruct-q4_K_M';
        this.tscMonitor = new TSCMonitor(config.projectRoot);
        this.astWatcher = new ASTWatcher(config);
        this.selfHealingEngine = new SelfHealingEngine(config.projectRoot, executor, this.SNAPSHOT_MODEL);
    }

    /**
     * Get the current set of TSC errors for health monitoring.
     */
    public getCurrentErrors(): readonly TSCError[] {
        return this.tscMonitor.getCurrentErrors();
    }

    override on<K extends keyof MonitorAgentEvents>(
        event: K,
        listener: MonitorAgentEvents[K]
    ): this {
        return super.on(event, listener);
    }

    override emit<K extends keyof MonitorAgentEvents>(
        event: K,
        ...args: Parameters<MonitorAgentEvents[K]>
    ): boolean {
        return super.emit(event, ...args);
    }

    start(): void {
        if (this.isRunning) {
            logger.warn('Monitor Agent already running');
            return;
        }

        logger.info('Starting Monitor Agent with local models');
        this.isRunning = true;

        // Start TSC continuous watch
        this.tscMonitor.start();
        this.tscMonitor.on('errorsDetected', (errors) => {
            this.handleTSCErrors(errors);
        });

        this.tscMonitor.on('buildSuccess', () => {
            this.handleBuildSuccess();
        });

        // Start file system watcher
        this.astWatcher.initialize();
        this.astWatcher.on('fileChanged', ({ filePath, hasStructuralChange }) => {
            if (hasStructuralChange) {
                this.handleFileChange(filePath);
            }
        });

        // Periodic health check (every 5 minutes)
        this.healthCheckInterval = setInterval(() => {
            this.performHealthCheck();
        }, 300000);

        logger.info({
            monitorModel: this.MONITOR_MODEL,
            snapshotModel: this.SNAPSHOT_MODEL
        }, 'Monitor Agent active');
    }

    private async handleTSCErrors(errors: readonly TSCError[]): Promise<void> {
        logger.warn({ errorCount: errors.length }, 'TSC errors detected, analyzing...');

        // Use tinyllama for quick severity classification
        const prompt = `Analyze these TypeScript errors and classify severity (low/medium/high/critical).
Errors:
${errors.map(e => `- ${e.file}:${e.line} [${e.code}] ${e.message}`).join('\n')}

Respond with ONLY: low, medium, high, or critical`;

        const result = await this.executor.callModel(this.MONITOR_MODEL, prompt);

        if (!result.ok) {
            logger.error({ error: result.error }, 'Monitor model failed');
            return;
        }

        const severity = result.value.response.trim().toLowerCase() as MonitorReport['severity'];

        const report: MonitorReport = {
            timestamp: Date.now(),
            severity: severity || 'medium',
            category: 'tsc',
            description: `TypeScript compilation has ${errors.length} error(s)`,
            affectedFiles: [...new Set(errors.map(e => e.file))],
            suggestedAction: 'Review and fix type errors in affected files',
            tscErrors: errors
        };

        this.emit('issueDetected', report);
    }

    private handleBuildSuccess(): void {
        if (this.recentChanges.size > 0) {
            logger.info({ count: this.recentChanges.size }, 'Build success! Processing candidates for Neural Harvest...');
            for (const filePath of this.recentChanges) {
                this.emit('provenanceCandidate', filePath);
            }
            this.recentChanges.clear();
        }
    }

    private async handleFileChange(filePath: string): Promise<void> {
        logger.debug({ filePath }, 'Structural file change detected');
        this.recentChanges.add(filePath);

        // Use qwen2.5-coder:7b for context-aware analysis
        const prompt = `File changed: ${filePath}
This is a structural change. Should we:
1. Re-run TSC to check for new errors?
2. Trigger a full build?
3. Just log and ignore?

Respond with ONLY: tsc, build, or ignore`;

        const result = await this.executor.callModel(this.SNAPSHOT_MODEL, prompt);

        if (result.ok) {
            const action = result.value.response.trim().toLowerCase();

            if (action === 'tsc' || action === 'build') {
                const report: MonitorReport = {
                    timestamp: Date.now(),
                    severity: 'low',
                    category: 'file-change',
                    description: `Structural change in ${filePath}`,
                    affectedFiles: [filePath],
                    suggestedAction: action === 'tsc' ? 'Re-check types' : 'Rebuild project'
                };

                this.emit('issueDetected', report);
            }
        }
    }

    private async performHealthCheck(): Promise<void> {
        // 1. Check TSC Errors
        const currentErrors = this.tscMonitor.getCurrentErrors();
        if (currentErrors.length > 0) {
            logger.debug({ errorCount: currentErrors.length }, 'Health check: TSC issues present');
        }

        // 2. Check Service Health via Registry
        const registry = HealthRegistry.getInstance();
        const services = ['gemini', 'cloudflare', 'sovereign-shell'];

        for (const serviceId of services) {
            const health = registry.getHealth(serviceId);
            // Map ServiceHealthState to ternary HealthStatus
            const serviceHealth = health.state === 'READY'
                ? HealthStatus.Ready
                : health.state === 'CRITICAL_FAILURE'
                    ? HealthStatus.Critical
                    : HealthStatus.Degraded;

            if (serviceHealth !== HealthStatus.Ready) {
                const report: MonitorReport = {
                    timestamp: Date.now(),
                    severity: serviceHealth === HealthStatus.Critical ? 'critical' : 'high',
                    category: 'build-failure',
                    description: `Sovereign Substrate Alert: Service [${serviceId}] is ${health.state}`,
                    affectedFiles: [],
                    suggestedAction: health.cooldownSeconds > 0
                        ? `Wait for cooldown (${health.cooldownSeconds}s) or use local fallback`
                        : 'Check API credentials or PATH configuration'
                };
                this.emit('issueDetected', report);
            }
        }

        // 3. Check CLI Tool Readiness
        const envStatus = await SystemEnvChecker.checkGlobalSettings();
        const missingCLIs = envStatus.filter(s => s.source === 'path' && !s.active);

        if (missingCLIs.length > 0) {
            const report: MonitorReport = {
                timestamp: Date.now(),
                severity: 'medium',
                category: 'build-failure',
                description: `Missing Fallback Tools: ${missingCLIs.map(s => s.key).join(', ')}`,
                affectedFiles: [],
                suggestedAction: 'Install missing CLI tools or verify they are in your system PATH'
            };
            this.emit('issueDetected', report);
        }

        if (currentErrors.length === 0 && missingCLIs.length === 0) {
            this.emit('healthCheckPassed');
            logger.debug('Health check: All systems green');
        }
    }

    /**
     * Proactively diagnose the current substrate state.
     * Returns a semantic decision: 'Yin' (Critical), 'YinYang' (Patch), 'Yang' (Continue)
     */
    async diagnoseState(plan?: ExecutionPlan): Promise<{ decision: CognitiveChoice; reasoning: string }> {
        const errors = this.tscMonitor.getCurrentErrors();
        if (errors.length === 0) {
            return { decision: BuildStatus.Passed, reasoning: 'Substrate healthy. Zero TSC errors detected.' };
        }

        // Diagnosing the first error found (usually the primary blocker)
        return await this.selfHealingEngine.diagnose(errors[0]!, plan);
    }

    /**
     * Internal interference check for the Orchestrator loop.
     */
    async checkInterference(plan?: ExecutionPlan): Promise<{ decision: CognitiveChoice; reasoning: string } | null> {
        const result = await this.diagnoseState(plan);
        if (result.decision === BuildStatus.Passed) return null; // No interference
        return result;
    }

    stop(): void {
        if (!this.isRunning) return;

        logger.info('Stopping Monitor Agent');
        this.isRunning = false;

        this.tscMonitor.stop();
        this.astWatcher.stop();

        if (this.healthCheckInterval) {
            clearInterval(this.healthCheckInterval);
        }

        this.removeAllListeners();
    }

    isActive(): boolean {
        return this.isRunning;
    }
}

import pino from 'pino';
import { TSCError } from './TSCMonitor.js';
import { CognitiveChoice, BuildStatus, HealthStatus } from '../core/models.js';
import { ArchitectureDigest } from '../core/ArchitectureDigest.js';
import { ModelExecutor } from '../core/ModelExecutor.js';
import { existsSync, readdirSync, readFileSync as fsReadFileSync } from 'fs';
import { join } from 'path';

const logger = pino({
    name: 'SelfHealingEngine',
    base: { hostname: 'POG-VIBE' }
});

export interface ExecutionStep {
    readonly tool: string;
    readonly args: string[];
    readonly reasoning: string;
}

export interface ExecutionPlan {
    readonly goal: string;
    readonly steps: ReadonlyArray<ExecutionStep>;
}

/**
 * SelfHealingEngine - Codifies ternary diagnostic logic for project errors.
 * 
 * -1 (CRITICAL): Stop and notify user
 * 0 (PATCH): Trigger correction handler (Ollama)
 * 1 (CONTINUE): Planned drift or valid state
 */
export class SelfHealingEngine {
    private readonly architectureDigest: ArchitectureDigest;

    constructor(
        projectRoot: string,
        private readonly executor: ModelExecutor,
        private readonly correctionModel: string = 'qwen2.5-coder:7b-instruct-q4_K_M'
    ) {
        this.architectureDigest = new ArchitectureDigest(projectRoot);
    }

    /**
     * Diagnose an error in context of the current execution plan.
     */
    async diagnose(error: TSCError, plan?: ExecutionPlan): Promise<{ decision: CognitiveChoice; reasoning: string }> {
        logger.info({ code: error.code, file: error.file }, 'Diagnosing error');

        // 0. Sense Test Outputs (Phase 16)
        const testInsights = this.senseTestOutputs();
        if (testInsights) {
            logger.info({ insights: testInsights.substring(0, 100) }, 'Sensed test insights');
        }

        // 1. Check for Planned Drift (Any Error)
        // If the file causing the error is part of the current plan, we assume the agent is fixing it.
        const isPlanned = this.isFilePlanned(error.file, plan) || this.isModulePlanned(error.message, plan);
        if (isPlanned) {
            return {
                decision: BuildStatus.Passed,
                reasoning: `Planned Drift: File/Module related to [${error.file}] is referenced in future plan steps. Proceeding.`
            };
        }

        // 2. Perform AI-powered "Sense" check using Correction Handler (Ollama)
        const senseCheck = await this.performSenseCheck(error);

        // 3. Structural Compliance Check
        const manifesto = this.architectureDigest.getManifest();
        const domainFiles = Object.values(manifesto.domainModel);
        const isStructural = domainFiles.some(m => error.file.includes(m.file));

        if (isStructural && senseCheck.severity === 'critical') {
            return {
                decision: HealthStatus.Critical,
                reasoning: `Critical Structural Break: ${error.message} in core manifest file [${error.file}]. Escalation required.`
            };
        }

        return {
            decision: BuildStatus.Warning,
            reasoning: `Correction Needed: ${senseCheck.analysis}. Triggering auto-patch turn via ${this.correctionModel}.`
        };
    }

    private isFilePlanned(filePath: string, plan?: ExecutionPlan): boolean {
        if (!plan) return false;
        const parts = filePath.split(/[\\/]/);
        const fileName = parts.pop();
        const baseName = fileName?.split('.')[0];
        if (!baseName) return false;

        return plan.steps.some(step =>
            JSON.stringify(step.args).includes(baseName) ||
            step.reasoning.includes(baseName)
        );
    }

    private isModulePlanned(errorMessage: string, plan?: ExecutionPlan): boolean {
        if (!plan) return false;
        const match = errorMessage.match(/module '(.+?)'/);
        if (!match) return false;
        const moduleName = match[1] as string;

        return plan.steps.some(step =>
            JSON.stringify(step.args).includes(moduleName) ||
            step.reasoning.includes(moduleName)
        );
    }

    private async performSenseCheck(error: TSCError): Promise<{ severity: string; analysis: string }> {
        const prompt = `Analyze this TSC error as a designated correction handler.
Error: ${error.file}:${error.line} - [${error.code}] ${error.message}

Task: Determine if this is a minor type fix or a major structural break.
Format: JSON { "severity": "low|medium|high|critical", "analysis": "concise explanation" }`;

        const result = await this.executor.callModel(this.correctionModel, prompt);
        if (!result.ok) {
            return { severity: 'medium', analysis: 'Correction handler unavailable, assuming medium severity.' };
        }

        try {
            const json = JSON.parse(result.value.response.match(/\{[\s\S]*\}/)?.[0] || '{}');
            return {
                severity: json.severity || 'medium',
                analysis: json.analysis || 'Generic type mismatch suspected.'
            };
        } catch {
            return { severity: 'medium', analysis: 'Failed to parse correction analysis.' };
        }
    }

    /**
     * Senses the tests/outputs directory for recent success/failure signals.
     */
    private senseTestOutputs(): string | undefined {
        const outputsDir = join(this.architectureDigest.getManifest().domainModel['Tests']?.file.split('/')[0] || 'tests', 'outputs');
        if (!existsSync(outputsDir)) return undefined;

        try {
            const files = readdirSync(outputsDir);
            const recentLogs = files.filter(f => f.endsWith('.log') || f.endsWith('.txt')).slice(-5);

            return recentLogs.map(f => {
                const content = fsReadFileSync(join(outputsDir, f), 'utf-8').slice(-500);
                return `[${f}]: ${content}`;
            }).join('\n---\n');
        } catch (err) {
            logger.error({ err }, 'Failed to sense test outputs');
            return undefined;
        }
    }
}

/**
 * TSC Monitor - Continuous TypeScript Compiler Watcher
 * 
 * Runs `tsc --watch --noEmit` and reports errors to the MonitorAgent
 */

import { spawn, ChildProcess } from 'child_process';
import { EventEmitter } from 'events';
import pino from 'pino';

const logger = pino({
    name: 'TSCMonitor',
    base: { hostname: 'POG-VIBE' }
});

export interface TSCError {
    readonly file: string;
    readonly line: number;
    readonly column: number;
    readonly code: string;
    readonly message: string;
    readonly severity: 'error' | 'warning';
}

export interface TSCMonitorEvents {
    errorsDetected: (errors: TSCError[]) => void;
    buildSuccess: () => void;
    watchStarted: () => void;
}

export class TSCMonitor extends EventEmitter {
    private tscProcess: ChildProcess | undefined;
    private currentErrors: TSCError[] = [];

    constructor(private readonly projectRoot: string) {
        super();
    }

    override on<K extends keyof TSCMonitorEvents>(
        event: K,
        listener: TSCMonitorEvents[K]
    ): this {
        return super.on(event, listener);
    }

    override emit<K extends keyof TSCMonitorEvents>(
        event: K,
        ...args: Parameters<TSCMonitorEvents[K]>
    ): boolean {
        return super.emit(event, ...args);
    }

    start(): void {
        logger.info({ projectRoot: this.projectRoot }, 'Starting TSC Watch Mode');

        this.tscProcess = spawn('tsc', ['--watch', '--noEmit'], {
            cwd: this.projectRoot,
            shell: true
        });

        let buffer = '';

        this.tscProcess.stdout?.on('data', (data) => {
            buffer += data.toString();

            // TSC outputs a compilation summary after each check
            if (buffer.includes('Found 0 errors')) {
                this.currentErrors = [];
                this.emit('buildSuccess');
                buffer = '';
            } else if (buffer.includes('Found') && buffer.includes('error')) {
                this.parseErrors(buffer);
                buffer = '';
            }
        });

        this.tscProcess.stderr?.on('data', (data) => {
            logger.warn({ stderr: data.toString() }, 'TSC stderr');
        });

        this.tscProcess.on('error', (error) => {
            logger.error({ error }, 'TSC process error');
        });

        this.emit('watchStarted');
    }

    private parseErrors(output: string): void {
        const errors: TSCError[] = [];
        const errorRegex = /(.+?)\((\d+),(\d+)\):\s+(error|warning)\s+TS(\d+):\s+(.+)/g;

        let match;
        while ((match = errorRegex.exec(output)) !== null) {
            errors.push({
                file: match[1]!.trim(),
                line: parseInt(match[2]!, 10),
                column: parseInt(match[3]!, 10),
                code: `TS${match[5]}`,
                message: match[6]!.trim(),
                severity: match[4] as 'error' | 'warning'
            });
        }

        if (errors.length > 0) {
            this.currentErrors = errors;
            this.emit('errorsDetected', errors);
            logger.debug({ errorCount: errors.length }, 'TSC errors detected');
        }
    }

    getCurrentErrors(): readonly TSCError[] {
        return this.currentErrors;
    }

    stop(): void {
        if (this.tscProcess) {
            this.tscProcess.kill();
            this.tscProcess = undefined;
            logger.info('TSC Monitor stopped');
        }
    }
}

/// <reference types="@cloudflare/workers-types" />
import { SpeechClient } from '@google-cloud/speech';
import { TextToSpeechClient } from '@google-cloud/text-to-speech';
import { GoogleGenerativeAI } from "@google/generative-ai";
import { Buffer } from 'buffer'; // Cloudflare Workers provide a Node.js-compatible Buffer

export interface Env {
  GOOGLE_APPLICATION_CREDENTIALS_JSON: string;
  GEMINI_API_KEY: string;
  AI: any; // Cloudflare Workers AI binding
  RATE_LIMITER: DurableObjectNamespace; // Durable Object for rate limiting
}

interface RateLimitResult {
  allowed: boolean;
  message?: string;
  count?: number;
  limit?: number;
  window?: number;
  firstRequestTime?: number;
}

interface RateLimitState {
  count: number;
  firstRequestTime: number;
}

export default {
  async checkRateLimit(request: Request, env: Env, key: string, limit: number = 5, window: number = 60000): Promise<Response | null> {
    const id = env.RATE_LIMITER.idFromName(key);
    const stub = env.RATE_LIMITER.get(id);
    const response = await stub.fetch(`http://rate-limiter/${key}?limit=${limit}&window=${window}`);
    const result = (await response.json()) as RateLimitResult;
    if (!result.allowed) {
      return new Response(JSON.stringify({ error: result.message }), { status: 429, headers: { 'Content-Type': 'application/json' } });
    }
    return null; // Request allowed
  },

  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === '/live-audio') {
      return this.handleLiveAudio(request, env, ctx);
    }

    if (url.pathname === '/generate-video') {
      return this.handleGenerateVideo(request, env, ctx);
    }

    if (url.pathname === '/generate-image') {
      return this.handleGenerateImage(request, env, ctx);
    }

    if (url.pathname === '/synthesize-speech') {
      return this.handleSynthesizeSpeech(request, env, ctx);
    }

    if (url.pathname === '/api/refactor') {
      return this.handleRefactor(request, env, ctx);
    }

    if (url.pathname.startsWith('/api/extensions')) {
      return this.handleExtensions(request, env, ctx);
    }

    if (url.pathname.startsWith('/api/behavior-trees')) {
      return this.handleBehaviorTrees(request, env, ctx);
    }

    if (url.pathname === '/api/vision') {
      return this.handleVision(request, env, ctx);
    }

    if (url.pathname.startsWith('/api/assets')) {
      return this.handleAssets(request, env, ctx);
    }

    if (url.pathname.startsWith('/api/build')) {
