import type { RoutingContext, RoutingDecision, RoutingStrategy } from '../types.js';
import type { Logger } from 'pino';
import pino from 'pino';

/**
 * A strategy that handles model failures by routing to an available fallback.
 * Uses actual model names from RoutingContext.availableModels, not abstract tiers.
 */
export class FallbackStrategy implements RoutingStrategy {
  readonly name = 'fallback';
  private readonly logger: Logger;
  private readonly failedModels: Set<string> = new Set();

  constructor() {
    this.logger = pino({ name: 'FallbackStrategy' });
  }

  /**
   * Track a model failure for fallback consideration.
   */
  public markModelFailed(model: string): void {
    this.failedModels.add(model);
    this.logger.warn({ model, failureCount: this.failedModels.size }, 'Model marked as failed in fallback registry');
  }

  /**
   * Clear failure status for a model (e.g., after successful recovery).
   */
  public clearModelFailure(model: string): void {
    if (this.failedModels.has(model)) {
      this.failedModels.delete(model);
      this.logger.info({ model }, 'Model failure state cleared successfully');
    }
  }

  async route(context: RoutingContext): Promise<RoutingDecision | null> {
    const startTime = performance.now();

    // No fallback needed if no models have failed or no context provided
    if (this.failedModels.size === 0 || !context.availableModels) {
      return null;
    }

    // Get available models that haven't failed and are healthy
    const healthyAvailable = context.availableModels.filter(
      m => m.health?.isAvailable && !this.failedModels.has(m.name)
    );

    if (healthyAvailable.length === 0) {
      this.logger.error({
        failedCount: this.failedModels.size,
        failedList: Array.from(this.failedModels)
      }, 'Critical: No healthy models available for fallback routing');
      return null;
    }

    // Sort by priority (highest first) and select best fallback
    const sorted = [...healthyAvailable].sort((a, b) => b.priority - a.priority);
    const fallback = sorted[0];

    const latency = Math.round(performance.now() - startTime);
    this.logger.info({
      failedModels: Array.from(this.failedModels),
      selectedFallback: fallback.name,
      latencyMs: latency
    }, 'Fallback model successfully selected');

    return {
      model: fallback.name,
      metadata: {
        source: 'fallback',
        latencyMs: latency,
        reasoning: `Falling back to ${fallback.name} (priority: ${fallback.priority}) because [${Array.from(this.failedModels).join(', ')}] are currently offline or failed.`,
      },
    };
  }
}

import type { RoutingContext, RoutingDecision, RoutingStrategy } from '../types.js';
import { IntentMap } from '../../api/ai/IntentMap.js';

/**
 * A strategy that identifies specific intents (DevOps, Security, Health)
 * and overrides the standard routing with high-certainty specific models.
 */
export class OverrideStrategy implements RoutingStrategy {
    readonly name = 'override';

    async route(context: RoutingContext): Promise<RoutingDecision | null> {
        const startTime = performance.now();
        const prompt = context.prompt.toLowerCase();
        const { weightedTasks, metadata } = context;
        const availableModels = context.availableModels || [];

        // 0. GHOST FAILOVER (Highest Priority)
        // If the Ghost has taken control (HealthStatus.Ready / +1), all intents are diverted
        // to the deterministic terminator to bypass cloud heuristics entirely.
        if (metadata?.['ghostEngagementLevel'] === 1) {
            return {
                model: 'ghost-terminator',
                metadata: {
                    source: 'ghost-override',
                    latencyMs: Math.round(performance.now() - startTime),
                    reasoning: 'GHOST_CONTROL_ACTIVE: Deterministic failover engaged. Bypassing cloud heuristics.',
                },
            };
        }

        // 0.1 ESOTERIC ESCALATION (Reasoning Forge)
        // If we are "stuck" (turn > 2) or explicit esoteric intent is detected, escalate to Kimi.
        const isStuck = metadata?.['isStuck'] === true;
        const esotericWeight = weightedTasks?.['esoteric'] || 0;

        if (isStuck || esotericWeight > 0.8 || prompt.includes('kimi') || prompt.includes('esoteric')) {
            // Only escalate if Ghost is NOT in control
            const reasoning = isStuck
                ? 'SYSTEM_STUCK: Cloud loops repeating without progress. Escalating to Kimi Reasoning Forge.'
                : 'ESOTERIC_INTENT: High-complexity mental model detected. Routing to Kimi.';

            return {
                model: 'gold_huggingface_kimi',
                metadata: {
                    source: 'esoteric-escalation',
                    latencyMs: Math.round(performance.now() - startTime),
                    reasoning: reasoning
                }
            };
        }

        // 0. Respect Sovereign User Preference (Explicit Model Request)
        // If the user explicitly names a model, we yield to the Analytical/Selection strategies
        // to avoid overriding their specific command with a general intent override.
        const explicitRequest = availableModels.find(m => prompt.includes(m.name.toLowerCase()) || prompt.includes(m.id.toLowerCase()));
        if (explicitRequest) {
            return null;
        }

        // 1. Layer 2: Elite Intent Pathing (Short-Circuit)
        for (const category of Object.values(IntentMap)) {
            for (const path of category) {
                if (path.keywords.some(kw => prompt.includes(kw.toLowerCase()))) {
                    const targetModel = path.targetCapabilityId;
                    if (availableModels.some(m => m.name === targetModel && m.health?.isAvailable)) {
                        return {
                            model: targetModel,
                            metadata: {
                                source: 'override-elite',
                                latencyMs: Math.round(performance.now() - startTime),
                                reasoning: `Elite Path Match: ${path.description}. ${path.reasoning}`,
                            },
                        };
                    }
                }
            }
        }

        // 2. Health & Status Override (Local/Edge)
        if (prompt.length < 50 && /\b(health|status|audit|check|verify|ping)\b/.test(prompt)) {
            return {
                model: 'gemini-2.0-flash', // Flash is the standard for rapid health
                metadata: {
                    source: 'override',
                    latencyMs: Math.round(performance.now() - startTime),
                    reasoning: 'Intention: Rapid health/status check - Routing to high-availability edge',
                },
            };
        }

        // 3. DevOps & High-Stakes Override (Cloud)
        const isDevOps = /\b(wrangler|gcloud|deploy|production|critical|security|auth|secrets|env|ci|cd)\b/.test(prompt);
        if (isDevOps || (weightedTasks?.['api-orchestration'] || 0) > 0.8) {
            return {
                model: 'gemini-3-pro-preview', // Pro for high-stakes
                metadata: {
                    source: 'override',
                    latencyMs: Math.round(performance.now() - startTime),
                    reasoning: 'Intention: DevOps/Security/Orchestration - Routing to cloud-tier reasoning',
                },
            };
        }

        // 4. Architecture & Structural Override (Cloud Thinking)
        if ((weightedTasks?.['architecture'] || 0) > 0.8) {
            return {
                model: 'gemini-3-pro-preview', // Ideally gemini-thinking-experimental if available
                metadata: {
                    source: 'override',
                    latencyMs: Math.round(performance.now() - startTime),
                    reasoning: 'Intention: Deep Architecture - Routing to cloud-tier thinking powerhouse',
                },
            };
        }

        return null;
    }
}

import type { RoutingContext, RoutingDecision, RoutingStrategy } from '../types.js';
import type { Logger } from 'pino';
import pino from 'pino';

/**
 * A routing strategy that classifies requests into ternary tiers based on task weights.
 * Returning specific models mapped from tiers.
 */
export class TernaryClassifierStrategy implements RoutingStrategy {
    readonly name = 'ternary-classifier';
    private readonly logger: Logger;

    constructor() {
        this.logger = pino({ name: 'TernaryClassifierStrategy' });
    }

    async route(context: RoutingContext): Promise<RoutingDecision | null> {
        const startTime = performance.now();
        const { prompt, weightedTasks = {}, availableModels = [] } = context;

        try {
            const classification = this.classifyPrompt(prompt, weightedTasks);
            const targetModel = this.selectModelFromTier(classification.tier, availableModels);

            if (!targetModel) return null;

            const latencyMs = Math.round(performance.now() - startTime);
            return {
                model: targetModel,
                metadata: {
                    source: 'ternary-classifier',
                    latencyMs,
                    reasoning: `${classification.reasoning} -> Selected: ${targetModel}`,
                },
            };
        } catch (error) {
            this.logger.warn({ error }, 'Classification failed');
            return null;
        }
    }

    private selectModelFromTier(tier: string, available: any[]): string | null {
        const tierFilter = (m: any) => {
            if (tier === 'reasoning') return m.name.includes('Kimi') || m.id.includes('kimi');
            if (tier === 'cloud') return m.type === 'cloud-free' || m.type === 'cloudflare';
            if (tier === 'edge') return m.name.includes('llama-3.1-8b') || m.name.includes('yi-coder') || m.type === 'cloudflare';
            return m.type === 'local';
        };

        const candidates = available
            .filter(m => m.health?.isAvailable && (m.health?.circuitLevel !== 'Yin'))
            .filter(tierFilter);

        return [...candidates].sort((a, b) => b.priority - a.priority)[0]?.name || null;
    }

    private classifyPrompt(prompt: string, weights: Record<string, number>): {
        tier: string;
        reasoning: string;
    } {
        const lowerPrompt = prompt.toLowerCase();

        // 1. Esoteric / High-Intel Reasoning (Ternary +1: Reasoning)
        if ((weights['esoteric'] || 0) > 0.6 || lowerPrompt.includes('esoteric') || lowerPrompt.includes('kimi')) {
            return { tier: 'reasoning', reasoning: 'Esoteric/High-intel reasoning task detected' };
        }

        // 2. Sensory/Utility detection (Ternary 0: Edge)
        if (/\b(screenshot|image|ocr|translate|vision|analyze)\b/.test(lowerPrompt)) {
            return { tier: 'edge', reasoning: 'Sensory intent detected' };
        }

        // 3. High-Complexity detection (Standard +1: Cloud)
        if ((weights['architecture'] || 0) > 0.4 || (weights['api-orchestration'] || 0) > 0.5) {
            return { tier: 'cloud', reasoning: 'High complexity architecture/orchestration' };
        }

        // 4. Low-Complexity detection (Ternary -1: Local)
        if (/\b(list|read|view|find)\b/.test(lowerPrompt) && (weights['generate'] || 0) < 0.3) {
            return { tier: 'local', reasoning: 'Low-complexity informational task' };
        }

        // 5. Generative weights
        const genWeight = weights['generate'] || 0;
        if (genWeight > 0.8) return { tier: 'cloud', reasoning: 'High generative weight' };
        if (genWeight > 0.4) return { tier: 'edge', reasoning: 'Moderate generative weight' };

        return { tier: 'local', reasoning: 'Defaulting to local efficiency' };
    }
}

/**
 * @license
 * POG-CODER-VIBE
 * Routing Decision Types
 * Adapted from Google's gemini-cli routing patterns for ternary architecture
 */

// Types are defined locally - no external imports needed for RoutingDecision

/**
 * The output of a routing decision. Specifies which model identifier to use and why.
 */
export interface RoutingDecision {
    /** The specific model name (e.g., 'gemini-2.0-flash', 'qwen2.5-coder:7b') */
    model: string;

    /**
     * Metadata about the routing decision for telemetry and debugging.
     */
    metadata: {
        /** Source of the routing decision (e.g., 'override', 'analytical', 'default') */
        source: string;

        /** Time taken to make the routing decision in milliseconds */
        latencyMs: number;

        /** Human-readable reasoning for why this model was selected */
        reasoning: string;

        /** Optional path taken through the ternary tree */
        path?: number[];

        /** Optional error message if the decision was made due to a failure */
        error?: string;
    };
}

import type { CognitiveChoice } from '../core/models.js';

/**
 * Context provided to routing strategies for making decisions.
 */
export interface RoutingContext {
    /** The user's prompt/request */
    prompt: string;

    /** Task weights derived from classification */
    weightedTasks?: Record<string, number>;

    /** Primary file extension for context */
    extension?: string;

    /** File size in bytes */
    fileSize?: number;

    /** Ternary complexity score ('Yin', 'YinYang', 'Yang') */
    complexity?: CognitiveChoice;

    /** Cloudflare and Ollama model health grid */
    availableModels?: any[];

    /** Architecture alignment patterns */
    architectureAlignment?: string[];

    /** Golden templates identified for the task */
    goldenTemplates?: string[];

    /** Historical performance logs */
    historicalPerformance?: any[];

    /** Past lessons/regrets identified */
    lessons?: any[];

    /** Conversation history for context-aware routing */
    history?: any[];

    /** Optional abort signal */
    signal?: AbortSignal;

    /** Additional metadata */
    metadata?: Record<string, any>;
}

/**
 * The core interface that all routing strategies must implement.
 * Strategies can decline a request by returning null, allowing the next strategy to try.
 */
export interface RoutingStrategy {
    /** The name of the strategy (e.g., 'fallback', 'override', 'classifier') */
    readonly name: string;

    /**
     * Determines which model to use for a given request context.
     * 
     * @param context The full context of the request
     * @returns A promise that resolves to a RoutingDecision, or null if the strategy cannot handle this request
     */
    route(context: RoutingContext): Promise<RoutingDecision | null>;
}

/**
 * A strategy that is guaranteed to return a decision (never returns null).
 * This is used as the final strategy in a composite chain to ensure termination.
 */
export interface TerminalStrategy extends RoutingStrategy {
    /**
     * Determines which model to use for a given request context.
     * Terminal strategies MUST return a decision (cannot return null).
     * 
     * @param context The full context of the request
     * @returns A promise that resolves to a RoutingDecision (never null)
     */
    route(context: RoutingContext): Promise<RoutingDecision>;
}

/**
 * Model tier classification for ternary routing.
 */
export enum ModelTier {
    /** Local Ollama models for simple, fast operations (1-3 tool calls) */
    Local = 'local',

    /** Edge/Hybrid for medium complexity (4-6 tool calls, writes + reasoning) */
    Edge = 'edge',

    /** Cloud Gemini for complex operations (7+ tool calls, architecture, debugging) */
    Cloud = 'cloud',
}

/**
 * Classification result from the ternary classifier.
 */
export interface TernaryClassification {
    /** The recommended tier for this request */
    tier: ModelTier;

    /** Estimated number of tool calls required */
    estimatedToolCalls: number;

    /** Human-readable reasoning for the classification decision */
    reasoning: string;

    /** Complexity factors that influenced the decision */
    complexityFactors: {
        hasStrategicPlanning: boolean;
        hasDebugging: boolean;
        hasMultipleFiles: boolean;
        hasHighAmbiguity: boolean;
    };

    /** Confidence score (0-1) in this classification */
    confidence: number;
}

/**
 * Sandbox - Safe execution environment
 * 
 * Responsibilities:
 * - Execute generated commands safely
 * - Create snapshots before execution (using Git or File Copy)
 * - Manage rollbacks on failure
 * - Extract and validate commands from AI output
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import { join } from 'path';
import { existsSync, mkdirSync, cpSync, rmSync } from 'fs';
import pino from 'pino';
import type { Result, VibeConfig } from '../core/models.js';

const execAsync = promisify(exec);
const logger = pino({
  name: 'Sandbox',
  base: { hostname: 'POG-VIBE' }
});

export interface ExecutionResult {
  readonly stdout: string;
  readonly stderr: string;
  readonly exitCode: number;
}

export class Sandbox {
  private readonly snapshotsDir: string;

  constructor(private readonly config: VibeConfig) {
    this.snapshotsDir = join(config.pogDir, 'snapshots');
    if (!existsSync(this.snapshotsDir)) {
      mkdirSync(this.snapshotsDir, { recursive: true });
    }
  }

  async execute(command: string): Promise<Result<ExecutionResult>> {
    try {
      logger.info({ command }, 'Executing command in sandbox');

      // 1. Create snapshot before execution
      const snapshotResult = await this.createSnapshot('Before: ' + command);
      if (!snapshotResult.ok) {
        return { ok: false, error: snapshotResult.error };
      }

      const snapshotId = snapshotResult.value;

      try {
        // 2. Run the command
        const { stdout, stderr } = await execAsync(command, {
          cwd: this.config.projectRoot,
          timeout: 60000 // 60s timeout
        });

        return {
          ok: true,
          value: { stdout, stderr, exitCode: 0 }
        };
      } catch (error: any) {
        // 3. Rollback on failure
        logger.warn({ command, error: error.message }, 'Command failed, rolling back...');
        await this.rollback(snapshotId);

        return {
          ok: true, // Still returning ok: true because the sandbox handled the failure
          value: {
            stdout: error.stdout || '',
            stderr: error.stderr || (error as Error).message,
            exitCode: error.code || 1
          }
        };
      }
    } catch (error) {
      return { ok: false, error: error as Error };
    }
  }

  /**
   * Create a project snapshot
   * Uses git stash if in a git repo, otherwise copies files
   */
  async createSnapshot(reason: string): Promise<Result<string>> {
    try {
      const isGit = existsSync(join(this.config.projectRoot, '.git'));
      const snapshotId = `snap_${Date.now()}`;

      if (isGit) {
        try {
          await execAsync(`git add . && git stash push -m "${snapshotId}: ${reason}"`, {
            cwd: this.config.projectRoot
          });
          logger.debug({ snapshotId, method: 'git' }, 'Snapshot created via git stash');
          return { ok: true, value: snapshotId };
        } catch (gitError) {
          logger.warn({ gitError }, 'Git stash failed, falling back to file copy');
        }
      }

      // Fallback: File Copy (Limited to source files for performance)
      const dest = join(this.snapshotsDir, snapshotId);
      mkdirSync(dest, { recursive: true });

      // Copy key project areas
      ['src', 'cli', 'tests', 'package.json', 'tsconfig.json'].forEach(item => {
        const srcPath = join(this.config.projectRoot, item);
        if (existsSync(srcPath)) {
          try {
            cpSync(srcPath, join(dest, item), { recursive: true });
          } catch (err) {
            logger.error({ item, err }, 'Failed to copy item to snapshot');
          }
        }
      });

      logger.debug({ snapshotId, method: 'copy' }, 'Snapshot created via file copy');
      return { ok: true, value: snapshotId };
    } catch (error) {
      return { ok: false, error: error as Error };
    }
  }

  /**
   * Rollback project to a specific snapshot
   */
  async rollback(snapshotId: string): Promise<Result<void>> {
    try {
      logger.info({ snapshotId }, 'Rolling back project');

      const isGit = existsSync(join(this.config.projectRoot, '.git'));

      if (isGit) {
        try {
          // Find stash index
          const { stdout } = await execAsync('git stash list', { cwd: this.config.projectRoot });
          const lines = stdout.split('\n');
          const stashIndex = lines.findIndex(l => l.includes(snapshotId));

          if (stashIndex !== -1) {
            await execAsync(`git reset --hard HEAD && git stash pop stash@{${stashIndex}}`, {
              cwd: this.config.projectRoot
            });
            return { ok: true, value: undefined };
          }
        } catch (gitError) {
          logger.warn({ gitError }, 'Git rollback failed');
        }
      }

      // File Copy Rollback
      const snapshotPath = join(this.snapshotsDir, snapshotId);
      if (existsSync(snapshotPath)) {
        ['src', 'cli', 'tests', 'package.json', 'tsconfig.json'].forEach(item => {
          const destPath = join(this.config.projectRoot, item);
          const srcPath = join(snapshotPath, item);
          if (existsSync(srcPath)) {
            try {
              rmSync(destPath, { recursive: true, force: true });
              cpSync(srcPath, destPath, { recursive: true });
            } catch (err) {
              logger.error({ item, err }, 'Failed to restore item during rollback');
            }
          }
        });
        return { ok: true, value: undefined };
      }

      return { ok: false, error: new Error(`Snapshot ${snapshotId} not found`) };
    } catch (error) {
      return { ok: false, error: error as Error };
    }
  }

  extractCommands(text: string): string[] {
    const commands: string[] = [];
    // Only extract blocks explicitly marked as shell/bash/sh/powershell/cmd
    // If no language is specified, we check if it looks like a command.
    const codeBlockRegex = /```(bash|sh|shell|powershell|ps1|batch|cmd|)\n([\s\S]*?)```/gi;
    let match;

    while ((match = codeBlockRegex.exec(text)) !== null) {
      const lang = (match[1] || '').toLowerCase();
      const block = match[2]?.trim();

      if (!block) continue;

      // If language specified and NOT a shell type, ignore it
      const shellLangs = ['bash', 'sh', 'shell', 'powershell', 'ps1', 'batch', 'cmd', ''];
      if (lang && !shellLangs.includes(lang)) {
        continue;
      }

      // If no language, and it contains common programming keywords, ignore it (likely a code snippet)
      if (!lang && /\b(function|class|export|import|const|let|interface|types|from)\b/.test(block)) {
        continue;
      }

      const lines = block.split('\n')
        .map(l => l.trim())
        .filter(l => l && !l.startsWith('#') && !l.startsWith('//'));
      commands.push(...lines);
    }

    return commands;
  }
}

import { execSync } from 'child_process';
import pino from 'pino';
import { Result } from '../core/models.js';
import { HexagramManager, YaoState } from '../core/HexagramManager.js';

const logger = pino({
    name: 'CloudflareServices',
    base: { hostname: 'POG-VIBE' }
});

export interface CloudflareConfig {
    accountId?: string;
    apiToken?: string;
    authEmail?: string | undefined;
    gatewayUrl?: string | undefined;
    bindingUrl?: string | undefined;
    hexagramManager?: HexagramManager | undefined;
}

/**
 * CloudflareServices - "Packed" Workers AI & Substrate Layer
 * Supports automated account detection and free-tier optimization.
 */
export class CloudflareServices {
    private accountId: string | undefined;
    private readonly apiToken: string | undefined;
    private authEmail: string | undefined;
    private readonly baseUrl: string = 'https://api.cloudflare.com/client/v4/accounts';

    private readonly config: CloudflareConfig;
    private readonly hexagramManager: HexagramManager | undefined;

    constructor(config: CloudflareConfig) {
        this.config = config;
        this.accountId = (config.accountId || process.env['CLOUDFLARE_ACCOUNT_ID'] || '').trim();
        this.apiToken = (config.apiToken || process.env['CLOUDFLARE_API_TOKEN'] || process.env['CLOUDFLARE_API_KEY'] || '').trim();
        this.authEmail = (config.authEmail || process.env['CLOUDFLARE_AUTH_EMAIL'] || '').trim();
        this.hexagramManager = config.hexagramManager;
    }

    public getAccountId(): string | undefined {
        return this.accountId;
    }

    /**
     * Auto-detect Cloudflare account ID from local wrangler context if not provided
     * Now returns a ternary status: 1 (Global), 0 (Token), -1 (Unauth)
     */
    async auditAbilities(): Promise<Result<{ accountId?: string; status: number }>> {
        try {
            // If missing accountId or email, try to get it from wrangler
            if (!this.accountId || !this.authEmail) {
                logger.info('Attempting to complete Cloudflare context via wrangler...');
                const output = execSync('wrangler whoami').toString();

                const match = output.match(/Account ID:\s+([a-f0-9]+)/i);
                if (match && match[1]) {
                    this.accountId = match[1].trim();
                }

                const emailMatch = output.match(/associated with the email\s+([^\s]+)/i);
                if (emailMatch && emailMatch[1]) {
                    // Remove trailing dot if present (common in "email@domain.com.")
                    this.authEmail = emailMatch[1].trim().replace(/\.$/, '');
                }
            }

            // Verify Token
            const verification = await this.verifyToken();
            if (!verification.ok) {
                return { ok: false, error: new Error(`Token verification failed: ${verification.error.message}`) };
            }

            // Determine Ternary Status
            const ternaryStatus = this.useGlobalKey ? 1 : 0;

            // Pin Auth Hex Card (Line 4: Environment)
            if (this.hexagramManager) {
                void this.hexagramManager.pinCard(4, 'Cloudflare Auth State',
                    this.useGlobalKey ? 'Sovereign Global Key active' : 'Standard API Token active',
                    this.useGlobalKey ? YaoState.OldYang : YaoState.YoungYang);
            }

            const result: { accountId?: string; status: number } = { status: ternaryStatus };
            if (this.accountId) {
                result.accountId = this.accountId;
            }
            return { ok: true, value: result };
        } catch (error) {
            logger.error({ error }, 'Cloudflare ability audit failed');
            return { ok: false, error: error as Error };
        }
    }

    async verifyToken(): Promise<Result<void>> {
        if (!this.apiToken) return { ok: false, error: new Error('No API Token provided') };

        try {
            // 1. Attempt Bearer Token against Core API
            const response = await fetch('https://api.cloudflare.com/client/v4/user/tokens/verify', {
                method: 'GET',
                headers: {
                    'Authorization': `Bearer ${this.apiToken}`,
                    'Content-Type': 'application/json'
                }
            });

            let bearerError = 'Bearer Auth Failed';

            if (response.ok) {
                const data = await response.json() as any;
                if (data.success && data.result.status === 'active') {
                    return { ok: true, value: undefined };
                }
                bearerError = data.errors?.[0]?.message || 'Invalid Token Status';
            } else {
                bearerError = `HTTP ${response.status}`;
            }

            // 2. Fallback: Global Key
            if (this.authEmail) {
                const globalResponse = await fetch('https://api.cloudflare.com/client/v4/user', {
                    method: 'GET',
                    headers: {
                        'X-Auth-Email': this.authEmail,
                        'X-Auth-Key': this.apiToken,
                        'Content-Type': 'application/json'
                    }
                });

                if (globalResponse.ok) {
                    const gData = await globalResponse.json() as any;
                    if (gData.success) {
                        this.useGlobalKey = true;
                        return { ok: true, value: undefined };
                    }
                }
            }

            // 3. Gateway Token Bypass
            // If we have a Gateway URL, the token might be a Gateway-Scoped token (not a Global User token).
            // In this case, standard verification fails, but the Gateway request might succeed.
            if (this.config.gatewayUrl) {
                logger.warn('Standard auth failed, but Gateway URL is present. Assuming Gateway-Scoped Token and proceeding.');
                return { ok: true, value: undefined };
            }

            return { ok: false, error: new Error(`Authentication failed. Bearer error: "${bearerError}". Global Key fallback also failed.`) };
        } catch (e) {
            return { ok: false, error: e as Error };
        }
    }

    private useGlobalKey: boolean = false;

    private getHeaders(contentType: string = 'application/json'): Record<string, string> {
        if (this.useGlobalKey && this.authEmail && this.apiToken) {
            return {
                'X-Auth-Email': this.authEmail,
                'X-Auth-Key': this.apiToken,
                'Content-Type': contentType
            };
        }
        return {
            'Authorization': `Bearer ${this.apiToken}`,
            'Content-Type': contentType
        };
    }

    /**
     * Run a Workers AI model with ternary prioritization logic
     */
    async runAi<T = any>(model: string, input: any): Promise<Result<T>> {
        // Ternary Decision Pathing
        // 1:  Local Binding (Priority)
        // 0:  Gateway (Middle)
        // -1: Direct API (Fallback)

        const routingPreference = this.config.bindingUrl ? 1 : (this.config.gatewayUrl ? 0 : -1);
        logger.debug({ model, routingPreference }, 'Cloudflare AI routing decision');

        // Pin Routing Hex Card (Line 5: Authority)
        if (this.hexagramManager) {
            const stateMap: Record<number, YaoState> = {
                1: YaoState.OldYang,   // Moving towards edge
                0: YaoState.YoungYang, // Balanced
                [-1]: YaoState.YoungYin // Low resource/fallback
            };
            void this.hexagramManager.pinCard(5, 'Cognitive Routing',
                `Routed to ${routingPreference === 1 ? 'Local Proxy' : (routingPreference === 0 ? 'Gateway' : 'Direct API')}`,
                stateMap[routingPreference] || YaoState.YoungYang);
        }

        // Execute 1: Local Binding Proxy
        if (routingPreference === 1) {
            try {
                // Post to local worker: { model, input }
                const response = await fetch(`${this.config.bindingUrl}/run`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ model, input })
                });

                if (!response.ok) {
                    const text = await response.text();
                    logger.warn({ status: response.status, error: text }, 'Local Binding failed, dropping to Binary Fallback (Gateway/Direct)');
                    // Drop to cascade if local fails
                } else {
                    const contentType = response.headers.get('content-type');
                    if (contentType?.includes('application/json')) {
                        return { ok: true, value: await response.json() as T };
                    }
                    const arrayBuffer = await response.arrayBuffer();
                    return { ok: true, value: Buffer.from(arrayBuffer) as unknown as T };
                }
            } catch (e) {
                logger.warn({ error: e }, 'Local Binding network error, dropping to Binary Fallback');
            }
        }

        if (!this.accountId || !this.apiToken) {
            return { ok: false, error: new Error('Cloudflare credentials missing') };
        }

        const directUrl = `${this.baseUrl}/${this.accountId}/ai/run/${model}`;
        let gatewayUrl: string | undefined;

        // Gateway Injection
        if (this.config.gatewayUrl) {
            // Heuristic: strip '/compat' if present to find root gateway base
            const gatewayBase = this.config.gatewayUrl.replace(/\/compat\/?$/, '');
            // Construct Workers AI path: {gatewayBase}/workers-ai/{model}
            gatewayUrl = `${gatewayBase}/workers-ai/${model}`;
            logger.debug({ gatewayUrl }, 'Using Cloudflare AI Gateway URL');
        }

        // Attempt Gateway First
        if (gatewayUrl) {
            try {
                const response = await fetch(gatewayUrl, {
                    method: 'POST',
                    headers: this.getHeaders(),
                    body: JSON.stringify(input)
                });

                if (response.ok) {
                    const contentType = response.headers.get('content-type');
                    if (contentType?.includes('application/json')) {
                        const data = await response.json() as any;
                        // Gateway results are typically wrapped in { result: T } if using AI Gateway
                        return { ok: true, value: (data.result !== undefined ? data.result : data) as T };
                    }
                    const arrayBuffer = await response.arrayBuffer();
                    return { ok: true, value: Buffer.from(arrayBuffer) as unknown as T };
                } else {
                    const errText = await response.text();
                    logger.warn({
                        status: response.status,
                        error: errText,
                        url: gatewayUrl
                    }, 'Gateway request failed, falling back to Direct API');
                }
            } catch (gwError) {
                logger.warn({ error: (gwError as Error).message, url: gatewayUrl }, 'Gateway network error, falling back to Direct API');
            }
        }

        // Fallback / Direct API
        try {
            const response = await fetch(directUrl, {
                method: 'POST',
                headers: this.getHeaders(),
                body: JSON.stringify(input)
            });

            if (!response.ok) {
                const text = await response.text();
                return { ok: false, error: new Error(`AI Run failed: ${response.status} - ${text}`) };
            }

            const contentType = response.headers.get('content-type');
            if (contentType?.includes('application/json')) {
                const data = await response.json() as any;
                // Direct API result format might be wrapped in { result: T, success: boolean }
                // OR it might be direct result depending on endpoint.
                // Workers AI REST API returns { result: ..., success: true }
                if (data.success !== undefined && !data.success) {
                    return { ok: false, error: new Error(data.errors?.[0]?.message || 'AI Execution failed') };
                }

                // If data has result property, return it.
                if (data.result) return { ok: true, value: data.result as T };

                return { ok: true, value: data as T };
            }

            const arrayBuffer = await response.arrayBuffer();
            return { ok: true, value: Buffer.from(arrayBuffer) as unknown as T };

        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }

    /**
     * Run a logic component via GhostLimb (Substrate) pattern
     */
    async runGhostLimb<T = any>(_name: string, _args: any): Promise<Result<T>> {
        // Implementation for calling a specialized worker scripting logic
        // For CLI, this might map to a specific worker script deployment
        return { ok: false, error: new Error('GhostLimb execution not yet implemented in direct CLI mode') };
    }

    /**
     * Edge Bake - Procedural generation via Workers AI
     */
    async edgeBake(prompt: string, type: 'style' | 'markup' | 'logic'): Promise<Result<string>> {
        const systemPrompt = `You are a high-performance edge generator. Generate only the ${type} asked for. No markdown fences.`;
        return this.runAi<string>('@cf/meta/llama-3-8b-instruct', {
            messages: [
                { role: 'system', content: systemPrompt },
                { role: 'user', content: prompt }
            ]
        });
    }

    // R2 Object Storage Methods - Using Shell-Ops for robustness (Dominant Decision)
    async putObject(bucket: string, key: string, data: string | Buffer, contentType?: string): Promise<Result<void>> {
        try {
            const contentTypeFlag = contentType ? ` --content-type "${contentType}"` : '';
            // Dominant Decision: Use shell execution to bypass project scope .env conflicts
            // Pattern: wrangler --global pattern (SovereignShell fallback style)
            const command = `wrangler r2 object put ${bucket}/${key}${contentTypeFlag} --file -`;

            logger.info({ bucket, key, command }, 'Executing Dominant Shell-Op for R2');

            // Note: In a real POG setup, we use execSync with specific env or child_process for --global effect
            execSync(command, { input: data, stdio: 'pipe' });

            // Pin Storage Hex Card (Line 6: Culmination)
            if (this.hexagramManager) {
                void this.hexagramManager.pinCard(6, 'R2 Storage Update', `Stored ${key} in ${bucket}`, YaoState.YoungYang);
            }

            return { ok: true, value: undefined };
        } catch (e) {
            logger.error({ error: e }, 'Cloudflare R2 Shell-Op failed');
            if (this.hexagramManager) {
                void this.hexagramManager.pinCard(6, 'R2 Storage Failure', `Failed to store ${key}`, YaoState.OldYin);
            }
            return { ok: false, error: e as Error };
        }
    }

    async getObject(bucket: string, key: string): Promise<Result<string>> {
        try {
            const command = `wrangler r2 object get ${bucket}/${key}`;
            logger.info({ bucket, key, command }, 'Executing Dominant Shell-Op for R2');
            const output = execSync(command).toString();

            if (this.hexagramManager) {
                void this.hexagramManager.pinCard(6, 'R2 Storage Retrieval', `Retrieved ${key} from ${bucket}`, YaoState.YoungYang);
            }

            return { ok: true, value: output };
        } catch (e) {
            logger.error({ error: e }, 'Cloudflare R2 Shell-Op failed');
            if (this.hexagramManager) {
                void this.hexagramManager.pinCard(6, 'R2 Storage Retrieval Failure', `Failed to get ${key}`, YaoState.OldYin);
            }
            return { ok: false, error: e as Error };
        }
    }
}

import pino from 'pino';
import { Result } from '../core/models.js';

const logger = pino({
    name: 'GoogleServices',
    base: { hostname: 'POG-VIBE' }
});

export interface GoogleServiceConfig {
    apiKey: string;
    projectId?: string;
    region?: string;
}

import { ImageAnnotatorClient } from '@google-cloud/vision';
import { v2 } from '@google-cloud/translate';
const { Translate } = v2;
import { LanguageServiceClient } from '@google-cloud/language';

/**
 * GoogleServices - Unified Google API Substrate
 */
export class GoogleServices {
    protected readonly config: GoogleServiceConfig;
    private readonly visionClient?: ImageAnnotatorClient;
    private readonly translateClient?: unknown;
    private readonly nlClient?: LanguageServiceClient;

    constructor(config: GoogleServiceConfig) {
        this.config = config;

        const authOptions = config.apiKey ? { apiKey: config.apiKey } : {};

        // 1. Vision Client (gRPC)
        try {
            this.visionClient = new ImageAnnotatorClient(authOptions);
        } catch (e) {
            logger.warn({ error: (e as Error).message, client: 'Vision' }, 'GCloud Sensory Client failure - Fallback active');
        }

        // 2. Translate Client (REST v2)
        try {
            this.translateClient = new Translate(authOptions);
        } catch (e) {
            logger.warn({ error: (e as Error).message, client: 'Translate' }, 'GCloud Sensory Client failure - Fallback active');
        }

        // 3. NL Client (gRPC)
        try {
            this.nlClient = new LanguageServiceClient(authOptions);
        } catch (e) {
            logger.warn({ error: (e as Error).message, client: 'NL' }, 'GCloud Sensory Client failure - Fallback active');
        }
    }

    /**
     * Standardized error classification for Google APIs
     */
    protected classifyError(error: unknown): { isQuota: boolean; isAuth: boolean; message: string } {
        const message = error instanceof Error ? error.message : String(error);
        const lowerMessage = message.toLowerCase();

        return {
            isQuota: lowerMessage.includes('429') || lowerMessage.includes('quota'),
            isAuth: lowerMessage.includes('401') || lowerMessage.includes('403') || lowerMessage.includes('unauthorized'),
            message
        };
    }

    /**
     * Analyze image using Google Vision API
     */
    async analyzeImage(buffer: Buffer): Promise<Result<unknown>> {
        if (!this.visionClient) return { ok: false, error: new Error('Vision Client not initialized') };

        try {
            const [result] = await this.visionClient.annotateImage({
                image: { content: buffer },
                features: [
                    { type: 'TEXT_DETECTION' },
                    { type: 'LABEL_DETECTION' },
                    { type: 'OBJECT_LOCALIZATION' }
                ]
            });
            return { ok: true, value: result };
        } catch (error) {
            logger.error({ error }, 'Vision API call failed');
            return { ok: false, error: error as Error };
        }
    }

    /**
     * Translate text using Google Translation API
     */
    async translateText(text: string, target: string): Promise<Result<string>> {
        if (!this.translateClient) return { ok: false, error: new Error('Translate Client not initialized') };

        try {
            const [translation] = await (this.translateClient as any).translate(text, target);
            return { ok: true, value: translation };
        } catch (error) {
            logger.error({ error }, 'Translation API call failed');
            return { ok: false, error: error as Error };
        }
    }

    /**
     * Analyze entities using Google Natural Language API
     */
    async analyzeEntities(text: string): Promise<Result<unknown>> {
        if (!this.nlClient) return { ok: false, error: new Error('NL Client not initialized') };

        try {
            const [result] = await this.nlClient.analyzeEntities({
                document: {
                    content: text,
                    type: 'PLAIN_TEXT'
                }
            });
            return { ok: true, value: result };
        } catch (error) {
            logger.error({ error }, 'Natural Language API call failed');
            return { ok: false, error: error as Error };
        }
    }

    /**
     * Placeholder for future cross-service Google discovery
     */
    async auditAbilities(): Promise<Result<{ services: string[] }>> {
        try {
            logger.info('Auditing Google services abilities via environment...');
            const services: string[] = [];

            // 1. Storage & CloudBuild rely on Application Credentials
            if (process.env['GOOGLE_APPLICATION_CREDENTIALS']) {
                services.push('storage', 'cloudbuild', 'pubsub');
            }

            // 2. Generative Language (Gemini) relies on API Key
            if (this.config.apiKey) {
                services.push('generativelanguage');
            }

            // 3. Region awareness
            if (this.config.region) {
                services.push(`region:${this.config.region}`);
            }

            return { ok: true, value: { services } };
        } catch (error) {
            return { ok: false, error: error as Error };
        }
    }
}

/**
 * TestRunner - Execute tests and typecheck after code edits
 * Detects errors and reports to supervisor for re-planning
 */

import { exec } from 'child_process';
import { promisify } from 'util';
import pino from 'pino';

const execAsync = promisify(exec);
const logger = pino({
    name: 'TestRunner',
    base: { hostname: 'POG-VIBE' }
});

export interface TestResult {
    passed: boolean;
    output: string;
    errors?: string[];
    duration?: number;
}

export class TestRunner {
    private readonly projectRoot: string;

    constructor(projectRoot: string) {
        this.projectRoot = projectRoot;
    }

    /**
     * Run npm test
     */
    async runTests(): Promise<TestResult> {
        logger.info('Running tests...');
        const startTime = Date.now();

        try {
            const { stdout, stderr } = await execAsync('npm test', {
                cwd: this.projectRoot,
                timeout: 60000, // 1 minute max
                env: { ...process.env, CI: 'true' } // Suppress interactive prompts
            });

            const duration = Date.now() - startTime;

            return {
                passed: true,
                output: stdout + stderr,
                duration
            };
        } catch (error: any) {
            const errorOutput = (error.stdout || '') + (error.stderr || '');
            const errors = this.parseTestErrors(errorOutput);
            const duration = Date.now() - startTime;

            return {
                passed: false,
                output: errorOutput,
                errors,
                duration
            };
        }
    }

    /**
     * Run TypeScript type checking
     */
    async runTypeCheck(): Promise<TestResult> {
        logger.info('Running typecheck...');
        const startTime = Date.now();

        try {
            const { stdout, stderr } = await execAsync('npm run typecheck', {
                cwd: this.projectRoot,
                timeout: 30000 // 30 seconds max
            });

            const duration = Date.now() - startTime;

            return {
                passed: true,
                output: stdout + stderr,
                duration
            };
        } catch (error: any) {
            const errorOutput = (error.stdout || '') + (error.stderr || '');
            const errors = this.parseTsErrors(errorOutput);
            const duration = Date.now() - startTime;

            logger.warn({ errorCount: errors.length }, 'TypeScript errors detected');

            return {
                passed: false,
                output: errorOutput,
                errors,
                duration
            };
        }
    }

    /**
     * Run both tests and typecheck
     */
    async runAll(): Promise<{ tests: TestResult; typecheck: TestResult }> {
        const [tests, typecheck] = await Promise.all([
            this.runTests().catch(e => ({
                passed: false,
                output: e.message,
                errors: [e.message]
            })),
            this.runTypeCheck()
        ]);

        return { tests, typecheck };
    }

    /**
     * Parse test errors from output
     */
    private parseTestErrors(output: string): string[] {
        const errors: string[] = [];

        // Jest/Vitest patterns
        const jestFailRegex = /FAIL\s+.*?\.test\.(ts|js|tsx|jsx)/g;
        const vitestFailRegex = /❯.*?FAIL/g;

        // Extract failing test files
        const jestMatches = output.match(jestFailRegex) || [];
        const vitestMatches = output.match(vitestFailRegex) || [];

        errors.push(...jestMatches, ...vitestMatches);

        // Also look for error messages
        const errorLines = output.split('\n').filter(line =>
            line.includes('Error:') || line.includes(' ✖ ') || line.includes(' ✗ ')
        );

        errors.push(...errorLines);

        return errors.slice(0, 10); // Limit to first 10 errors
    }

    /**
     * Parse TypeScript errors from output
     */
    private parseTsErrors(output: string): string[] {
        const errors: string[] = [];

        // TypeScript error pattern: "file.ts(line,col): error TS1234: message"
        const tsErrorRegex = /(.+?)\((\d+),(\d+)\):\s+error\s+(TS\d+):\s+(.+)/g;

        let match;
        while ((match = tsErrorRegex.exec(output)) !== null) {
            const [, file, line, col, code, message] = match;
            errors.push(`${file}:${line}:${col} - ${code}: ${message}`);
        }

        // Fallback: simple "error TS" pattern
        if (errors.length === 0) {
            const simpleRegex = /error TS\d+:.+/g;
            const matches = output.match(simpleRegex) || [];
            errors.push(...matches);
        }

        return errors.slice(0, 20); // Limit to first 20 errors
    }

    /**
     * Check if package.json has test script
     */
    hasTestScript(): boolean {
        try {
            const packageJson = require(`${this.projectRoot}/package.json`);
            return !!packageJson.scripts?.test;
        } catch {
            return false;
        }
    }

    /**
     * Check if package.json has typecheck script
     */
    hasTypecheckScript(): boolean {
        try {
            const packageJson = require(`${this.projectRoot}/package.json`);
            return !!packageJson.scripts?.typecheck;
        } catch {
            return false;
        }
    }
}

import * as fs from 'fs';
import { join } from 'path';
import pino from 'pino';

const logger = pino({
    name: 'ProjectPulse',
    base: { hostname: 'POG-VIBE' }
});

export interface ProjectManifest {
    name: string;
    description: string;
    lastActive: number;
    inventory: string[];
    mood: string;
    customData: Record<string, any>;
}

/**
 * ProjectPulse - Manages the 'pog.md' manifest file for each project.
 * This ensures the agent has disk-bound, persistent awareness of its work per directory.
 */
export class ProjectPulse {
    private static readonly FILENAME = 'pog.md';

    /**
     * Ensures a pog.md exists in the project root.
     */
    public static initManifest(projectRoot: string, projectName: string): void {
        const path = join(projectRoot, this.FILENAME);
        if (!fs.existsSync(path)) {
            const content = `# 📁 Pog Manifest: [${projectName}]

This manifest serves as the persistent memory substrate for the **POG-VIBE** agent in this directory.

## 🚀 Active Context
- **Last Sync**: ${new Date().toISOString()}
- **Current Objective**: Initialization
- **System Mood**: Stable

## 📄 Core Inventory
- [x] manifest created

---
*Generated by POG-VIBE Project Pulse.*`;
            fs.writeFileSync(path, content);
            logger.info({ projectName, path }, 'Project manifest initialized');
        }
    }

    /**
     * Updates the manifest with new context.
     */
    public static updatePulse(projectRoot: string, delta: { objective?: string; mood?: string; inventoryItem?: string }): void {
        const path = join(projectRoot, this.FILENAME);
        if (!fs.existsSync(path)) return;

        try {
            let content = fs.readFileSync(path, 'utf8');

            if (delta.objective) {
                content = content.replace(/- \*\*Current Objective\*\*: .*/, `- **Current Objective**: ${delta.objective}`);
            }
            if (delta.mood) {
                content = content.replace(/- \*\*System Mood\*\*: .*/, `- **System Mood**: ${delta.mood}`);
            }
            if (delta.inventoryItem) {
                const marker = '## 📄 Core Inventory';
                if (!content.includes(`- [x] ${delta.inventoryItem}`)) {
                    content = content.replace(marker, `${marker}\n- [x] ${delta.inventoryItem}`);
                }
            }

            content = content.replace(/- \*\*Last Sync\*\*: .*/, `- **Last Sync**: ${new Date().toISOString()}`);

            fs.writeFileSync(path, content);
            logger.debug({ projectRoot }, 'Project pulse updated on disk');
        } catch (e) {
            logger.error({ error: e }, 'Failed to update project pulse');
        }
    }

    /**
     * Reads the current manifest for prompt enrichment.
     */
    public static getManifestContext(projectRoot: string): string {
        const path = join(projectRoot, this.FILENAME);
        if (!fs.existsSync(path)) return 'No project manifest (pog.md) found.';

        try {
            return fs.readFileSync(path, 'utf8');
        } catch (e) {
            return 'Failed to read project manifest.';
        }
    }
}

import { existsSync, readdirSync } from 'fs';
import { execSync } from 'child_process';
import { join } from 'path';
import { homedir } from 'os';
import pino from 'pino';

const logger = pino({ name: 'SystemEnvChecker' });

export interface EnvStatus {
    key: string;
    value: string | boolean;
    active: boolean;
    source: 'env' | 'fs' | 'config' | 'path';
}

export class SystemEnvChecker {
    private static readonly SENSITIVE_KEYS = [
        'GOOGLE_API_KEY',
        'GEMINI_API_KEY',
        'CLOUDFLARE_API_TOKEN',
        'FIREWORKS_API_KEY',
        'ANTHROPIC_API_KEY'
    ];

    static async checkGlobalSettings(): Promise<EnvStatus[]> {
        const status: EnvStatus[] = [];

        // 1. Check Process Environment
        for (const key of this.SENSITIVE_KEYS) {
            const val = process.env[key];
            status.push({
                key,
                value: val ? `${val.substring(0, 4)}...${val.substring(val.length - 4)}` : 'NOT_SET',
                active: !!val,
                source: 'env'
            });
        }

        // 2. Check for SSH Keys
        const sshDir = join(homedir(), '.ssh');
        if (existsSync(sshDir)) {
            try {
                const files = readdirSync(sshDir);
                const hasKeys = files.some(f => f.startsWith('id_') && !f.endsWith('.pub'));
                status.push({
                    key: 'SSH_KEYS',
                    value: hasKeys ? `${files.filter(f => !f.endsWith('.pub')).length} keys found` : 'None',
                    active: hasKeys,
                    source: 'fs'
                });
            } catch (err) {
                logger.warn({ err }, 'Failed to read .ssh directory');
            }
        }

        // 3. Check for Gemini/Ollama/Wrangler/GCloud CLI Readiness via Path Lookup
        const geminiReady = this.commandExists('gemini');
        const ollamaReady = this.commandExists('ollama');
        const wranglerReady = this.commandExists('wrangler');
        const gcloudReady = this.commandExists('gcloud');
        const sshReady = this.commandExists('ssh');

        status.push({
            key: 'GEMINI_CLI_READY',
            value: geminiReady,
            active: geminiReady,
            source: 'path'
        });

        status.push({
            key: 'OLLAMA_CLI_READY',
            value: ollamaReady,
            active: ollamaReady,
            source: 'path'
        });

        status.push({
            key: 'WRANGLER_CLI_READY',
            value: wranglerReady,
            active: wranglerReady,
            source: 'path'
        });

        status.push({
            key: 'GCLOUD_CLI_READY',
            value: gcloudReady,
            active: gcloudReady,
            source: 'path'
        });

        status.push({
            key: 'SSH_READY',
            value: sshReady,
            active: sshReady,
            source: 'path'
        });

        return status;
    }

    private static commandExists(command: string): boolean {
        try {
            const cmd = process.platform === 'win32' ? 'where' : 'which';
            execSync(`${cmd} ${command}`, { stdio: 'ignore' });
            return true;
        } catch {
            return false;
        }
    }



    static async getActiveSettingsMap(): Promise<Record<string, any>> {
        const statuses = await this.checkGlobalSettings();
        return statuses.reduce((acc, s) => {
            acc[s.key] = s.active;
            return acc;
        }, {} as Record<string, any>);
    }
}

/**
 * Configuration management with environment variable support and validation
 */

import { homedir } from 'os';
import { join } from 'path';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { z } from 'zod';
import type { VibeConfig } from '../core/models.js';

const ConfigSchema = z.object({
  pogDir: z.string().min(1),
  projectRoot: z.string().min(1),
  agentName: z.string().min(1).default('POG-VIBE-AGENT'),
  wsPort: z.number().int().min(1024).max(65535).default(8765),
  maxSnapshotAge: z.number().int().positive().default(86400000), // 24 hours
  circuitBreakerThreshold: z.number().int().positive().default(3),
  circuitBreakerCooldown: z.number().int().positive().default(30000), // 30 seconds
  embeddingDimensions: z.number().int().positive().default(768),
  logLevel: z.enum(['trace', 'debug', 'info', 'warn', 'error']).default('info'),
  projectId: z.string().default('pog-vibe-session'),
  workspaces: z.array(z.string()).default([]),
  errorTrackerModelPath: z.string().optional(),
  ollamaModelsPath: z.string().optional(),
  gutenbergPath: z.string().optional(),
  enabledServices: z.array(z.string()).default(['gemini', 'ollama', 'cloudflare', 'mcp_gitkraken', 'healthcare', 'documentai', 'vision', 'mediaforge', 'gutenberg', 'dashboard']),
  cloudflareGatewayUrl: z.string().url().optional(),
  monitorModel: z.string().optional(),
  snapshotModel: z.string().optional(),
  criticModel: z.string().optional(),
  planningModel: z.string().optional(),
  codingModel: z.string().optional(),
  healThreshold: z.enum(['low', 'medium', 'high', 'critical']).optional(),
  sovereignRoot: z.string().optional(),
  pogApiUrl: z.string().url().optional(),
  aiContextPath: z.string().optional()
});

type ConfigInput = z.input<typeof ConfigSchema>;

const DEFAULT_POG_DIR = join(homedir(), '.pog-coder-vibe');
const CONFIG_FILE_NAME = 'config.json';

export class ConfigManager {
  private config: VibeConfig;
  private readonly configPath: string;

  constructor(projectRoot: string, overrides?: Partial<ConfigInput>) {
    // 1. Detect Sovereign Root (High Priority D: Drive)
    const SOVEREIGN_CANDIDATE = 'D:\\pog-coder-vibe';
    const hasSovereign = existsSync(SOVEREIGN_CANDIDATE);

    // 2. Check for local .pog directory preference
    const localPogDir = join(projectRoot, '.pog');
    const useLocal = process.env['POG_USE_LOCAL'] === 'true' || existsSync(localPogDir);

    const resolvedDefault = hasSovereign ? SOVEREIGN_CANDIDATE : (useLocal ? localPogDir : DEFAULT_POG_DIR);
    const pogDir = process.env['POG_DIR'] ?? overrides?.pogDir ?? resolvedDefault;

    this.configPath = join(pogDir, CONFIG_FILE_NAME);
    const sovereignRoot = hasSovereign ? SOVEREIGN_CANDIDATE : undefined;

    // Ensure POG directory exists (if not sovereign, we might need to create it)
    if (!existsSync(pogDir)) {
      mkdirSync(pogDir, { recursive: true });
    }

    // Load or create config
    this.config = this.loadConfig(projectRoot, pogDir, { ...overrides, sovereignRoot });
  }

  private loadConfig(
    projectRoot: string,
    pogDir: string,
    overrides?: Partial<ConfigInput>
  ): VibeConfig {
    let fileConfig: Partial<ConfigInput> = {};

    // Try to load existing config
    if (existsSync(this.configPath)) {
      try {
        const raw = readFileSync(this.configPath, 'utf-8');
        fileConfig = JSON.parse(raw) as Partial<ConfigInput>;
      } catch (error) {
        // eslint-disable-next-line no-console
        console.warn('Failed to parse config file, using defaults:', error);
      }
    }

    // Merge: defaults < file < env vars < overrides
    const merged: ConfigInput = {
      pogDir,
      projectRoot,
      agentName: process.env['VIBE_AGENT_NAME'] || overrides?.agentName || fileConfig.agentName || 'POG-VIBE-AGENT',
      wsPort: Number(process.env['VIBE_WS_PORT']) || overrides?.wsPort || fileConfig.wsPort || 8765,
      maxSnapshotAge: Number(process.env['VIBE_MAX_SNAPSHOT_AGE']) || overrides?.maxSnapshotAge || fileConfig.maxSnapshotAge || 86400000,
      circuitBreakerThreshold: Number(process.env['VIBE_CB_THRESHOLD']) || overrides?.circuitBreakerThreshold || fileConfig.circuitBreakerThreshold || 3,
      circuitBreakerCooldown: Number(process.env['VIBE_CB_COOLDOWN']) || overrides?.circuitBreakerCooldown || fileConfig.circuitBreakerCooldown || 30000,
      embeddingDimensions: Number(process.env['VIBE_EMBEDDING_DIM']) || overrides?.embeddingDimensions || fileConfig.embeddingDimensions || 768,
      logLevel: (process.env['VIBE_LOG_LEVEL'] as VibeConfig['logLevel']) || overrides?.logLevel || fileConfig.logLevel || 'info',
      projectId: process.env['POG_PROJECT_ID'] || overrides?.projectId || fileConfig.projectId || projectRoot.split(/[\\/]/).pop() || 'default-project',
      ollamaModelsPath: process.env['OLLAMA_MODELS_PATH'] || overrides?.ollamaModelsPath || fileConfig.ollamaModelsPath || fileConfig.errorTrackerModelPath || '',
      gutenbergPath: (() => {
        const raw = process.env['POG_GUTENBERG_PATH'] || overrides?.gutenbergPath || fileConfig.gutenbergPath || '';
        // Resolve relative paths against pogDir
        if (raw && !/^[a-zA-Z]:/.test(raw) && !raw.startsWith('/') && !raw.startsWith('\\')) {
          return join(pogDir, raw);
        }
        return raw;
      })(),
      errorTrackerModelPath: process.env['POG_ERROR_TRACKER_PATH'] || overrides?.errorTrackerModelPath || fileConfig.errorTrackerModelPath || '',
      enabledServices: overrides?.enabledServices || fileConfig.enabledServices || ['gemini', 'ollama', 'cloudflare', 'mcp_gitkraken', 'healthcare', 'documentai', 'vision', 'mediaforge', 'gutenberg', 'dashboard'],
      cloudflareGatewayUrl: process.env['CLOUDFLARE_GATEWAY_URL'] || overrides?.cloudflareGatewayUrl || fileConfig.cloudflareGatewayUrl,
      monitorModel: process.env['VIBE_MONITOR_MODEL'] || overrides?.monitorModel || fileConfig.monitorModel,
      snapshotModel: process.env['VIBE_SNAPSHOT_MODEL'] || overrides?.snapshotModel || fileConfig.snapshotModel,
      criticModel: process.env['VIBE_CRITIC_MODEL'] || overrides?.criticModel || fileConfig.criticModel,
      planningModel: process.env['VIBE_PLANNING_MODEL'] || overrides?.planningModel || fileConfig.planningModel,
      codingModel: process.env['VIBE_CODING_MODEL'] || overrides?.codingModel || fileConfig.codingModel,
      healThreshold: (process.env['VIBE_HEAL_THRESHOLD'] as VibeConfig['healThreshold']) || overrides?.healThreshold || fileConfig.healThreshold,
      sovereignRoot: overrides?.sovereignRoot || fileConfig.sovereignRoot,
      pogApiUrl: process.env['POG_API_URL'] || overrides?.pogApiUrl || fileConfig.pogApiUrl,
      aiContextPath: process.env['POG_AI_CONTEXT_PATH'] || overrides?.aiContextPath || fileConfig.aiContextPath || join(projectRoot, 'docs', 'ai-context')
    } as any; // Cast for now to satisfy strict Zod vs Interface drift

    // Validate
    const result = ConfigSchema.safeParse(merged);

    if (!result.success) {
      throw new Error(`Invalid configuration: ${result.error.message}`);
    }

    // Save validated config back to file
    this.saveConfig(result.data as VibeConfig);

    return result.data;
  }

  private saveConfig(config: VibeConfig): void {
    try {
      writeFileSync(this.configPath, JSON.stringify(config, null, 2));
    } catch (error) {
      // eslint-disable-next-line no-console
      console.warn('Failed to save config file:', error);
    }
  }

  getConfig(): Readonly<VibeConfig> {
    return this.config;
  }

  updateConfig(updates: Partial<ConfigInput>): void {
    const merged = { ...this.config, ...updates };
    const result = ConfigSchema.safeParse(merged);

    if (!result.success) {
      throw new Error(`Invalid config update: ${result.error.message}`);
    }

    this.config = result.data as VibeConfig;
    this.saveConfig(this.config);
  }
}

/**
 * Terminal Utility - Descriptive Selection & Ternary Logic
 * 
 * Implements high-fidelity terminal interactions using raw readline.
 * Follows the POG project's ternary decision pattern (-1, 0, +1).
 */

import readline from 'readline';
import chalk from 'chalk';

export interface SelectionItem<T> {
    readonly value: T;
    readonly label: string;
    readonly description?: string;
}

/**
 * Descriptive Radio Button Selection
 * 
 * Uses ternary logic for state management:
 * - -1: Selection Cancelled
 * -  0: Active Selection In Progress
 * - +1: Selection Confirmed
 */
export async function select<T>(
    title: string,
    items: SelectionItem<T>[],
    initialIndex = 0
): Promise<T | null> {
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
        terminal: true
    });

    let activeIndex = initialIndex;
    let state: -1 | 0 | 1 = 0; // Ternary state
    void state; // Mark as used for TSC

    return new Promise((resolve) => {
        const render = () => {
            // Move cursor to start of section
            readline.cursorTo(process.stdout, 0);
            readline.clearScreenDown(process.stdout);

            process.stdout.write(`${chalk.bold(title)}\n\n`);

            items.forEach((item, index) => {
                const isSelected = index === activeIndex;
                const prefix = isSelected ? chalk.green(' ● ') : ' ○ ';
                const label = isSelected ? chalk.green(item.label) : item.label;

                process.stdout.write(`${prefix}${label}\n`);
                if (item.description) {
                    process.stdout.write(`    ${chalk.gray(item.description)}\n`);
                }
            });

            process.stdout.write(`\n${chalk.gray('(Use arrow keys to navigate, Enter to select, Esc/q to cancel)')}\n`);
        };

        const cleanup = () => {
            rl.close();
            process.stdin.removeListener('keypress', handleKey);
            if (process.stdin.isTTY) process.stdin.setRawMode(false);
        };

        const handleKey = (_str: string, key: { name: string; ctrl: boolean }) => {
            if (key.ctrl && key.name === 'c') {
                state = -1;
                cleanup();
                resolve(null);
                return;
            }

            switch (key.name) {
                case 'up':
                    activeIndex = (activeIndex - 1 + items.length) % items.length;
                    render();
                    break;
                case 'down':
                    activeIndex = (activeIndex + 1) % items.length;
                    render();
                    break;
                case 'return': {
                    state = 1;
                    const item = items[activeIndex];
                    cleanup();
                    resolve(item ? item.value : null);
                    break;
                }
                case 'escape':
                case 'q':
                    state = -1;
                    cleanup();
                    resolve(null);
                    break;
            }
        };

        if (process.stdin.isTTY) process.stdin.setRawMode(true);
        readline.emitKeypressEvents(process.stdin);
        process.stdin.on('keypress', handleKey);

        render();
    });
}

/**
 * Utility to strip ANSI codes for length calculation
 */
function stripAnsi(str: string): string {
    return str.replace(/[\u001b\u009b][[()#;?]*(?:[0-9]{1,4}(?:;[0-9]{0,4})*)?[0-9A-ORZcf-nqry=><]/g, '');
}

/**
 * Draws a professional box with a title and content
 */
export function drawBox(title: string, content: string[], width?: number): void {
    const terminalWidth = process.stdout.columns || 80;
    const boxWidth = width || Math.min(terminalWidth - 2, 80);
    const border = '─'.repeat(boxWidth - 2);
    const innerWidth = boxWidth - 4;

    process.stdout.write(chalk.cyan(`┌${border}┐\n`));

    // Title Line
    const visibleTitle = stripAnsi(title);
    const titlePadding = ' '.repeat(Math.max(0, innerWidth - visibleTitle.length));
    process.stdout.write(chalk.cyan(`│ `) + chalk.bold.white(title) + titlePadding + chalk.cyan(` │\n`));

    process.stdout.write(chalk.cyan(`├${border}┤\n`));

    content.forEach(line => {
        // Handle multiline wrapping
        const visibleLine = stripAnsi(line);
        if (visibleLine.length > innerWidth) {
            const chunks = line.match(new RegExp(`.{1,${innerWidth}}`, 'g')) || [line];
            chunks.forEach(chunk => {
                const visibleChunk = stripAnsi(chunk);
                const padding = ' '.repeat(Math.max(0, innerWidth - visibleChunk.length));
                process.stdout.write(chalk.cyan(`│ `) + chunk + padding + chalk.cyan(` │\n`));
            });
        } else {
            const padding = ' '.repeat(Math.max(0, innerWidth - visibleLine.length));
            process.stdout.write(chalk.cyan(`│ `) + line + padding + chalk.cyan(` │\n`));
        }
    });

    process.stdout.write(chalk.cyan(`└${border}┘\n`));
}

/**
 * Draws a chat-style message bubble
 */
export function drawMessage(role: 'USER' | 'POG' | 'SYSTEM', text: string, width = 70): void {
    const color = role === 'USER' ? chalk.blue : role === 'POG' ? chalk.green : chalk.yellow;
    const label = role === 'USER' ? '👤 YOU' : role === 'POG' ? '🤖 POG' : '⚙️  SYS';

    process.stdout.write(`\n${color.bold(label)}:\n`);
    const maxWidth = Math.min(process.stdout.columns - 4 || width, width);
    const wrapped = text.match(new RegExp(`.{1,${maxWidth}}`, 'g')) || [text];
    wrapped.forEach(line => {
        process.stdout.write(`${line}\n`);
    });
}

/**
 * Draws a professional Sovereign Status Report (Table)
 */
export function drawSovereignReport(title: string, data: Record<string, string | number>): void {
    const entries = Object.entries(data);
    const maxKeyLen = Math.max(...entries.map(([k]) => k.length), 0);
    const content = entries.map(([k, v], i) => {
        const key = chalk.cyan(k.padEnd(maxKeyLen));
        const value = i % 2 === 0 ? chalk.white(v) : chalk.gray(v);
        return `${chalk.gray('  ● ')}${key} ${chalk.gray('➜')} ${value}`;
    });

    drawBox(`👑 ${title}`, content);
}

/**
 * Renders the persistent Sovereign Status Line at the bottom of the screen
 */
export function drawSovereignFooter(stats: {
    substrate: string;
    extension: string;
    edge: string;
    session: string;
    errors: number;
}): void {
    const width = process.stdout.columns || 80;
    const substrateColor = stats.substrate.includes('ACTIVE') ? chalk.green : chalk.red;
    const extColor = stats.extension === 'ACTIVE' ? chalk.green : chalk.red;
    const edgeColor = stats.edge === 'ACTIVE' ? chalk.green : chalk.red;
    const errorColor = stats.errors > 0 ? chalk.bold.red : chalk.gray;

    const line = [
        chalk.cyan('🏰 ') + substrateColor(stats.substrate.split(' ')[0]),
        chalk.cyan('🔌 ') + extColor(stats.extension),
        chalk.cyan('🌩️ ') + edgeColor(stats.edge),
        chalk.cyan('💾 ') + chalk.gray(stats.session.substring(0, 8)),
        stats.errors > 0 ? errorColor(`\u2716 ${stats.errors} ERRORS (Ctrl+F12)`) : chalk.gray('✔ READY')
    ].join(chalk.gray(' | '));

    const visibleLine = stripAnsi(line);
    const padding = ' '.repeat(Math.max(0, width - visibleLine.length - 2));

    // Use absolute positioning if possible, but for simple REPL we just print
    process.stdout.write(`\n${chalk.bgBlack.white(' ')}${line}${padding}${chalk.bgBlack.white(' ')}\n`);
}

/**
 * Renders the collapsed/detailed reports panel
 */
export function drawDetailedReports(reports: { type: string, content: string }[]): void {
    if (reports.length === 0) {
        drawBox('📋 DETAILED REPORTS', [chalk.gray('No reports captured.')]);
        return;
    }

    const content = reports.map(r => {
        const icon = r.type === 'error' ? chalk.red('✖') : chalk.blue('ℹ');
        const color = r.type === 'error' ? chalk.red : chalk.white;
        return `${icon} ${chalk.bold(r.type.toUpperCase())}: ${color(r.content)}`;
    });

    drawBox('📋 DETAILED REPORTS (Ctrl+F12 to close)', content);
}

/**
 * AST Watcher - File system monitoring with structural change detection
 * 
 * Responsibilities:
 * - Monitor project files for changes
 * - Hash file contents to detect real changes
 * - Parse changed files (placeholder for tree-sitter)
 * - Emit events for Orchestrator
 */

import { EventEmitter } from 'events';
import chokidar from 'chokidar';
import { readFileSync, existsSync } from 'fs';
import { createHash } from 'crypto';
import pino from 'pino';
import type { Result, VibeConfig } from '../core/models.js';

const logger = pino({
  name: 'ASTWatcher',
  base: { hostname: 'POG-VIBE' }
});

export interface WatcherEvents {
  fileChanged: (data: { filePath: string; hasStructuralChange: boolean }) => void;
  watchError: (data: { error: Error }) => void;
}

export class ASTWatcher extends EventEmitter {
  private watcher?: chokidar.FSWatcher;
  private readonly fileHashes: Map<string, string> = new Map();

  constructor(private readonly config: VibeConfig) {
    super();
  }

  /**
   * Update the project root and restart the watcher
   */
  async setProjectRoot(newRoot: string): Promise<void> {
    logger.info({ newRoot }, 'Updating AST Watcher root');
    await this.stop();
    (this.config as any).projectRoot = newRoot;
    this.initialize();
  }

  override on<K extends keyof WatcherEvents>(
    event: K,
    listener: WatcherEvents[K]
  ): this {
    return super.on(event, listener);
  }

  override emit<K extends keyof WatcherEvents>(
    event: K,
    ...args: Parameters<WatcherEvents[K]>
  ): boolean {
    return super.emit(event, ...args);
  }

  initialize(): Result<void> {
    try {
      logger.info({ projectRoot: this.config.projectRoot }, 'Initializing AST Watcher');

      this.watcher = chokidar.watch(this.config.projectRoot, {
        ignored: [
          '**/node_modules/**',
          '**/dist/**',
          '**/.git/**',
          '**/.pog-coder-vibe/**',
          this.config.pogDir
        ],
        persistent: true,
        ignoreInitial: false // Process initial files to build hash map
      });

      this.setupHandlers();

      return { ok: true, value: undefined };
    } catch (error) {
      logger.error({ error }, 'Failed to initialize watcher');
      return { ok: false, error: error as Error };
    }
  }

  private setupHandlers(): void {
    if (!this.watcher) return;

    this.watcher
      .on('add', (filePath: string) => this.handleFileChange(filePath, false))
      .on('change', (filePath: string) => this.handleFileChange(filePath, true))
      .on('error', (error: Error) => {
        logger.error({ error }, 'Watcher error');
        this.emit('watchError', { error });
      });
  }

  private handleFileChange(filePath: string, isUpdate: boolean): void {
    try {
      if (!existsSync(filePath)) return;

      const content = readFileSync(filePath, 'utf-8');
      const hash = createHash('md5').update(content).digest('hex');
      const previousHash = this.fileHashes.get(filePath);

      if (hash === previousHash) {
        // No real change (e.g. metadata update only)
        return;
      }

      this.fileHashes.set(filePath, hash);

      if (isUpdate) {
        logger.debug({ filePath }, 'Structural change detected');
        this.emit('fileChanged', { filePath, hasStructuralChange: true });
      }
    } catch (error) {
      logger.warn({ error, filePath }, 'Failed to process file change');
    }
  }

  async stop(): Promise<void> {
    if (this.watcher) {
      await this.watcher.close();
    }
    this.removeAllListeners();
    logger.info('Watcher stopped');
  }
}

export interface RateLimitResult {
    allowed: boolean;
    message?: string;
    count?: number;
    limit?: number;
    window?: number;
    firstRequestTime?: number;
}

interface RateLimitState {
    count: number;
    firstRequestTime: number;
}

export class RateLimiter implements DurableObject {
    private state: DurableObjectState;

    constructor(state: DurableObjectState, env: any) {
        this.state = state;
    }

    async fetch(request: Request): Promise<Response> {
        const url = new URL(request.url);
        const key = url.pathname.slice(1); // Remove leading slash
        const limit = parseInt(url.searchParams.get('limit') || '10');
        const windowMs = parseInt(url.searchParams.get('window') || '60000');

        let data = (await this.state.storage.get<RateLimitState>(key)) || { count: 0, firstRequestTime: Date.now() };

        const now = Date.now();
        if (now - data.firstRequestTime > windowMs) {
            data = { count: 1, firstRequestTime: now };
        } else {
            data.count++;
        }

        const allowed = data.count <= limit;

        // Only write if changed (optimization)
        await this.state.storage.put(key, data);

        const result: RateLimitResult = {
            allowed,
            message: allowed ? 'OK' : 'Rate limit exceeded',
            count: data.count,
            limit,
            window: windowMs,
            firstRequestTime: data.firstRequestTime
        };

        return new Response(JSON.stringify(result), {
            headers: { 'Content-Type': 'application/json' }
        });
    }
}

import { RateLimiter } from './RateLimiter';

export interface Env {
